('g5_2_soc_u3_L01_basic#1','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C1',1,'mc','auto','다른 나라가 힘으로 빼앗아 다스리는 것을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C1","difficulty":1,"kind":"mc","stem":"다른 나라가 힘으로 빼앗아 다스리는 것을 무엇이라고 하나요?","options":[{"t":"식민 통치","correct":true},{"t":"광복","mis":"SO5-2-u3-X02"},{"t":"개항","mis":"SO5-2-u3-X02"},{"t":"정부 수립","mis":"SO5-2-u3-X02"}],"explanation":["힘으로 빼앗았어요.","그 나라가 다스려요.","식민 통치예요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#2','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',1,'sa','auto','황제가 반대했는데도 일제가 억지로 맺어 대한 제국의 외교권을 빼앗은 조약은 무엇인가요? (을○○○)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C2","difficulty":1,"kind":"sa","stem":"황제가 반대했는데도 일제가 억지로 맺어 대한 제국의 외교권을 빼앗은 조약은 무엇인가요? (을○○○)","answer":["을사늑약"],"explanation":["억지로 맺었어요.","외교권을 빼앗겼어요.","을사늑약이에요."],"mis":"SO5-2-u3-X04"}'::jsonb),
('g5_2_soc_u3_L01_basic#3','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',1,'mc','auto','나라를 지키려고 스스로 일어나 일제와 싸운 사람들을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X09','SO5-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C4","difficulty":1,"kind":"mc","stem":"나라를 지키려고 스스로 일어나 일제와 싸운 사람들을 무엇이라고 하나요?","options":[{"t":"의병","correct":true},{"t":"특사","mis":"SO5-2-u3-X05"},{"t":"헌병","mis":"SO5-2-u3-X09"},{"t":"신하","mis":"SO5-2-u3-X06"}],"explanation":["스스로 일어났어요.","일제와 싸웠어요.","의병이에요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#4','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C3',1,'ox','auto','황제는 을사늑약이 무효임을 알리려고 헤이그의 평화 회의에 특사를 보냈어요.',ARRAY['SO5-2-u3-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C3","difficulty":1,"kind":"ox","stem":"황제는 을사늑약이 무효임을 알리려고 헤이그의 평화 회의에 특사를 보냈어요.","answer":"O","reason_options":[{"t":"늑약의 부당함을 세계에 알리려 했기 때문에","correct":true},{"t":"특사가 늑약에 이름을 쓰러 갔기 때문에","mis":"SO5-2-u3-X05"}],"mis":"SO5-2-u3-X05","explanation":["황제는 반대했어요.","특사를 보냈어요.","무효임을 알리려 했어요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#5','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',2,'mc','auto','어느 조약의 내용 메모로 보아 이 조약으로 대한 제국이 빼앗긴 권리는 어느 것인가요?',ARRAY['SO5-2-u3-X03']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C2","difficulty":2,"kind":"mc","stem":"어느 조약의 내용 메모로 보아 이 조약으로 대한 제국이 빼앗긴 권리는 어느 것인가요?","options":[{"t":"외교권","correct":true},{"t":"화폐를 만드는 권리","mis":"SO5-2-u3-X03"},{"t":"농사짓는 권리","mis":"SO5-2-u3-X03"},{"t":"학교를 세우는 권리","mis":"SO5-2-u3-X03"}],"explanation":["외교를 일본이 감독해요.","다른 나라와 조약을 못 맺어요.","외교권이에요."],"asset":{"type":"passage","lines":["제1조 — 일본 정부가 대한 제국의 외교에 관한 일을 모두 감독한다.","제2조 — 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺지 못한다.","— 황제는 끝까지 반대했지만 일본 군대가 궁궐을 둘러쌌다."],"title":"어느 조약의 내용 메모"}}'::jsonb),
('g5_2_soc_u3_L01_basic#6','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',2,'mc','auto','을사늑약을 「늑약」이라고 부르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X04']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C2","difficulty":2,"kind":"mc","stem":"을사늑약을 「늑약」이라고 부르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"황제가 반대했는데도 일제가 군대를 앞세워 억지로 맺었기 때문에","correct":true},{"t":"두 나라가 뜻을 모아 기쁘게 맺었기 때문에","mis":"SO5-2-u3-X04"},{"t":"대한 제국이 먼저 맺자고 했기 때문에","mis":"SO5-2-u3-X04"},{"t":"조약을 맺은 곳의 이름이 「늑」이기 때문에","mis":"SO5-2-u3-X04"}],"explanation":["늑약은 억지로 맺은 조약이에요.","황제는 반대했어요.","군대를 앞세웠어요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#7','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',2,'mc','auto','의병 운동이 더욱 활발해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X07','SO5-2-u3-X05']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"mc","stem":"의병 운동이 더욱 활발해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대한 제국 군대가 해산되자 군인들이 의병에 들어갔다","correct":true},{"t":"일제가 의병에게 무기를 나누어 주었다","mis":"SO5-2-u3-X07"},{"t":"헤이그 특사가 회의에서 이겼다","mis":"SO5-2-u3-X05"},{"t":"다른 나라 군대가 대신 싸워 주었다","mis":"SO5-2-u3-X07"}],"explanation":["군대가 해산되었어요.","군인들이 합류했어요.","훈련된 솜씨로 싸웠어요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#8','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C1',2,'mc','auto','이 단원에서 공부할 두 주제를 차례로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C1","difficulty":2,"kind":"mc","stem":"이 단원에서 공부할 두 주제를 차례로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"식민 통치와 저항으로 달라진 생활 → 8·15 광복과 6·25 전쟁으로 달라진 생활","correct":true},{"t":"8·15 광복과 6·25 전쟁으로 달라진 생활 → 식민 통치와 저항으로 달라진 생활","mis":"SO5-2-u3-X46"},{"t":"조선의 건국 → 개항 이후 달라진 생활","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁 → 3·1 운동","mis":"SO5-2-u3-X46"}],"explanation":["먼저 나라를 빼앗겼어요.","그다음 되찾았어요.","그 뒤 전쟁이 있었어요."]}'::jsonb),
('g5_2_soc_u3_L01_basic#9','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',2,'ox','auto','외국 기자의 의병 취재 메모를 보면 의병에는 훈련받은 군인만 있었어요.',ARRAY['SO5-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"ox","stem":"외국 기자의 의병 취재 메모를 보면 의병에는 훈련받은 군인만 있었어요.","answer":"X","reason_options":[{"t":"낡은 한복 차림의 젊은이와 군인이 섞여 여러 사람이 함께했기 때문에","correct":true},{"t":"의병은 나라에서 뽑은 군인으로만 이루어졌기 때문에","mis":"SO5-2-u3-X06"}],"mis":"SO5-2-u3-X06","explanation":["한복 차림 젊은이가 있어요.","군인도 섞였어요.","여러 사람이 함께했어요."],"asset":{"type":"passage","lines":["외국 기자가 산골 마을에서 의병들을 만났다.","낡은 한복 차림의 젊은이와 군복을 입은 군인이 섞여 있었다.","제대로 쓸 만한 총은 몇 자루 없었다.","그래도 「나라를 지키다 죽는 편이 노예로 사는 것보다 낫다」고 했다."],"title":"외국 기자의 의병 취재 메모"}}'::jsonb),
('g5_2_soc_u3_L01_basic#10','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C3',3,'error','auto','을사늑약 뒤의 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X01','SO5-2-u3-X07']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C3","difficulty":3,"kind":"error","stem":"을사늑약 뒤의 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「헤이그 특사가 회의에서 연설해서 늑약을 바로 없앴어.」","correct":true,"mis_target":"SO5-2-u3-X05"},{"t":"준우 — 「상인은 가게 문을 닫고 학생은 등교를 거부했어.」","mis":"SO5-2-u3-X01"},{"t":"하린 — 「해산된 군인들이 의병에 들어갔어.」","mis":"SO5-2-u3-X07"}],"explanation":["특사는 회의장에 못 들어갔어요.","기자들에게 알렸어요.","서아의 말이 잘못됐어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#1','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',2,'match','auto','단원의 중요한 용어와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C1","difficulty":2,"kind":"match","stem":"단원의 중요한 용어와 뜻을 알맞게 이으세요.","pairs":[{"l":"식민 통치","r":"힘으로 빼앗아 다스림"},{"l":"저항","r":"빼앗김에 맞서 싸움"},{"l":"광복","r":"빼앗긴 나라를 되찾음"}],"mis":"SO5-2-u3-X02","explanation":["빼앗아 다스리면 식민 통치예요.","맞서면 저항이에요.","되찾으면 광복이에요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#2','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',2,'mc','auto','의병들이 만주와 연해주로 건너간 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X05','SO5-2-u3-X07']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"mc","stem":"의병들이 만주와 연해주로 건너간 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일제가 큰 부대로 탄압해 나라 안에서 싸우기 어려워졌기 때문에","correct":true},{"t":"만주에서 편히 쉬려고","mis":"SO5-2-u3-X12"},{"t":"특사와 함께 평화 회의에 가려고","mis":"SO5-2-u3-X05"},{"t":"농사지을 땅을 사려고","mis":"SO5-2-u3-X07"}],"explanation":["일제가 큰 부대로 눌렀어요.","나라 안에서 어려워졌어요.","나라 밖에서 싸움을 이었어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#3','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',3,'mc','auto','어느 조약의 내용 메모 제2조 때문에 대한 제국이 겪게 될 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X03']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C2","difficulty":3,"kind":"mc","stem":"어느 조약의 내용 메모 제2조 때문에 대한 제국이 겪게 될 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 처지를 다른 나라에 직접 알리고 도움을 청하기 어려워진다","correct":true},{"t":"다른 나라와 마음대로 조약을 맺을 수 있다","mis":"SO5-2-u3-X03"},{"t":"학교에서 일본어를 배우지 않아도 된다","mis":"SO5-2-u3-X03"},{"t":"백성이 세금을 내지 않아도 된다","mis":"SO5-2-u3-X03"}],"explanation":["일본을 거쳐야 해요.","직접 조약을 못 맺어요.","도움을 청하기 어려워요."],"asset":{"type":"passage","lines":["제1조 — 일본 정부가 대한 제국의 외교에 관한 일을 모두 감독한다.","제2조 — 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺지 못한다.","— 황제는 끝까지 반대했지만 일본 군대가 궁궐을 둘러쌌다."],"title":"어느 조약의 내용 메모"}}'::jsonb),
('g5_2_soc_u3_L01_challenge#4','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C3',3,'mc','auto','헤이그 특사가 회의장에는 들어가지 못했지만 한 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X04']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C3","difficulty":3,"kind":"mc","stem":"헤이그 특사가 회의장에는 들어가지 못했지만 한 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 나라 기자들 앞에서 대한 제국의 처지와 늑약의 부당함을 알렸다","correct":true},{"t":"아무것도 하지 못하고 돌아와 소용이 없었다","mis":"SO5-2-u3-X05"},{"t":"일본과 새 조약을 맺고 돌아왔다","mis":"SO5-2-u3-X04"},{"t":"회의에서 늑약을 무효로 만들었다","mis":"SO5-2-u3-X05"}],"explanation":["회의장은 막혔어요.","기자들을 만났어요.","세계에 부당함을 알렸어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#5','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',3,'ox','auto','일제가 다스리던 시기에도 우리 민족은 감시 속에서 여러 방법으로 일제에 맞섰어요.',ARRAY['SO5-2-u3-X01']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C1","difficulty":3,"kind":"ox","stem":"일제가 다스리던 시기에도 우리 민족은 감시 속에서 여러 방법으로 일제에 맞섰어요.","answer":"O","reason_options":[{"t":"의병·만세·몰래 돕기처럼 나라를 되찾을 때까지 저항이 이어졌기 때문에","correct":true},{"t":"힘이 약해 아무것도 하지 못했기 때문에","mis":"SO5-2-u3-X01"}],"mis":"SO5-2-u3-X01","explanation":["감시가 심했어요.","그래도 맞섰어요.","저항은 이어졌어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#6','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',3,'error','auto','의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X06','SO5-2-u3-X07']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C4","difficulty":3,"kind":"error","stem":"의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「의병은 나라에서 월급을 받는 군인만 될 수 있었어.」","correct":true,"mis_target":"SO5-2-u3-X06"},{"t":"지안 — 「여성도 노래를 지어 의병을 북돋웠어.」","mis":"SO5-2-u3-X06"},{"t":"민재 — 「탄압을 피해 만주와 연해주로 건너가 싸웠어.」","mis":"SO5-2-u3-X07"}],"explanation":["스스로 일어난 사람들이에요.","여성·농민도 있었어요.","태오의 말이 잘못됐어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#7','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',3,'mc','auto','「을사늑약 → 헤이그 특사 → 의병 운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X05','SO5-2-u3-X03']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C2","difficulty":3,"kind":"mc","stem":"「을사늑약 → 헤이그 특사 → 의병 운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?","options":[{"t":"외교권을 빼앗겨서 → 황제는 특사로 부당함을 알리려 했고 → 사람들은 의병을 일으켜 맞섰다","correct":true},{"t":"의병이 일어나서 → 늑약을 맺었고 → 특사를 보냈다","mis":"SO5-2-u3-X46"},{"t":"특사가 회의에서 이겨서 → 늑약이 없어지고 → 의병이 흩어졌다","mis":"SO5-2-u3-X05"},{"t":"외교권을 되찾아서 → 의병이 해산했다","mis":"SO5-2-u3-X03"}],"explanation":["먼저 외교권을 빼앗겼어요.","황제는 세계에 알렸어요.","사람들은 의병으로 맞섰어요."]}'::jsonb),
('g5_2_soc_u3_L01_challenge#8','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',4,'mc','auto','어느 거리 그림에서 개항 이후 들어온 모습이 아니라 이 단원에서 새로 나타난 모습끼리 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C1","difficulty":4,"kind":"mc","stem":"어느 거리 그림에서 개항 이후 들어온 모습이 아니라 이 단원에서 새로 나타난 모습끼리 짝지은 것은 어느 것인가요?","options":[{"t":"㉱ 태극기를 든 학생들 · ㉲ 기차역으로 향하는 쌀가마 수레","correct":true},{"t":"㉮ 전차가 지나는 큰길 · ㉯ 양복 가게","mis":"SO5-2-u3-X46"},{"t":"㉯ 자전거 가게 · ㉮ 전차","mis":"SO5-2-u3-X46"},{"t":"㉰ 한복과 서양식 옷 · ㉯ 양복 가게","mis":"SO5-2-u3-X46"}],"explanation":["전차·양복은 개항 뒤 들어왔어요.","태극기는 맞서는 모습이에요.","쌀이 실려 가는 모습도 새로워요."],"asset":{"type":"passage","lines":["㉮ 전차가 지나는 큰길","㉯ 자전거 가게와 양복 가게","㉰ 한복과 서양식 옷을 입은 사람들","㉱ 태극기를 든 학생들","㉲ 기차역으로 향하는 쌀가마 수레"],"title":"어느 거리 그림 살피기"}}'::jsonb),
('g5_2_soc_u3_L01_challenge#9','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',4,'mc','auto','「안사람 의병가」를 쉬운 말로 읽고, 노래를 지은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X06','SO5-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":4,"kind":"mc","stem":"「안사람 의병가」를 쉬운 말로 읽고, 노래를 지은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 지키는 일에 여성들도 함께하자고 힘을 북돋우려고","correct":true},{"t":"여성은 집안일만 하라고 알리려고","mis":"SO5-2-u3-X06"},{"t":"의병을 그만두라고 말리려고","mis":"SO5-2-u3-X01"},{"t":"일제에게 잘 보이려고","mis":"SO5-2-u3-X01"}],"explanation":["여성 의병장이 지었어요.","집에만 있을 수 없다고 했어요.","함께 나라를 지키자는 노래예요."],"asset":{"type":"passage","lines":["한 여성 의병장이 마을 여성들에게 노래를 지어 불러 주었다.","나라가 위태로운데 여성이라고 집에만 있을 수 없다는 내용이다.","힘을 모아 의병을 돕고 나라를 지키자고 북돋웠다."],"title":"「안사람 의병가」를 쉬운 말로"}}'::jsonb),
('g5_2_soc_u3_L01_challenge#10','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',4,'essay','teacher','을사늑약이 대한 제국에 준 영향을 쓰고, 이에 맞선 사람들의 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C2","difficulty":4,"kind":"essay","stem":"을사늑약이 대한 제국에 준 영향을 쓰고, 이에 맞선 사람들의 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 을사늑약으로 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺을 수 없게 되어 외교권을 빼앗겼다. 황제는 헤이그 평화 회의에 특사를 보내 늑약이 무효임을 세계에 알리려 했고, 사람들은 곳곳에서 의병을 일으켜 일제와 싸웠다.","scoring_points":["외교권을 빼앗긴 영향을 썼는가","맞선 노력 두 가지를 썼는가","노력의 뜻(부당함 알리기·나라 지키기)을 썼는가"]},"explanation":["외교권을 빼앗겼어요.","특사와 의병이 있어요.","뜻을 함께 써요."]}'::jsonb),
('g5_2_soc_u3_L02_basic#1','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',1,'sa','auto','일제가 나라를 빼앗은 뒤 우리나라를 다스리려고 세운 기관은 무엇인가요? (조선 ○○○)','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"sa","stem":"일제가 나라를 빼앗은 뒤 우리나라를 다스리려고 세운 기관은 무엇인가요? (조선 ○○○)","answer":["조선 총독부","조선총독부","총독부"],"explanation":["일제가 세웠어요.","군인 출신이 우두머리였어요.","조선 총독부예요."],"mis":"SO5-2-u3-X08"}'::jsonb),
