('g5_2_soc_u3_L02_basic#6','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',2,'mc','auto','일제가 헌병에게 경찰 일을 맡긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C5","difficulty":2,"kind":"mc","stem":"일제가 헌병에게 경찰 일을 맡긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한국인을 감시하고 독립운동을 막으려고","correct":true},{"t":"한국인의 안전을 지켜 주려고","mis":"SO5-2-u3-X09"},{"t":"군인이 남아돌아서","mis":"SO5-2-u3-X09"},{"t":"학교를 많이 세우려고","mis":"SO5-2-u3-X09"}],"explanation":["헌병은 군인이에요.","감시했어요.","독립운동을 막으려 했어요."]}'::jsonb),
('g5_2_soc_u3_L02_basic#7','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C6',2,'mc','auto','토지 조사 사업 탐구 메모로 보아 이 사업 뒤 농민의 생활로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X10','SO5-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C6","difficulty":2,"kind":"mc","stem":"토지 조사 사업 탐구 메모로 보아 이 사업 뒤 농민의 생활로 알맞은 것은 어느 것인가요?","options":[{"t":"땅을 잃거나 남의 땅을 빌려 농사짓는 농민이 늘었다","correct":true},{"t":"모든 농민이 땅을 더 많이 갖게 되었다","mis":"SO5-2-u3-X10"},{"t":"자기 땅에서 농사짓는 농민이 늘었다","mis":"SO5-2-u3-X11"},{"t":"농민이 세금을 내지 않게 되었다","mis":"SO5-2-u3-X10"}],"explanation":["신고 못 한 땅을 빼앗겼어요.","빌려 짓는 농민이 늘었어요.","생활이 어려워졌어요."],"asset":{"type":"passage","lines":["① 일제는 땅 주인을 확인한다며 전국의 땅을 조사했다.","② 정해진 기간 안에 땅을 신고해야 했다.","③ 신고하지 못한 땅이나 마을이 함께 쓰던 땅은 빼앗기기도 했다.","④ 시간이 갈수록 남의 땅을 빌려 농사짓는 농민이 늘었다."],"title":"토지 조사 사업 탐구 메모"}}'::jsonb),
