('g5_2_soc_u3_L02_challenge#7','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C7',3,'mc','auto','남겨진 어느 가족의 기록으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X47']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C7","difficulty":3,"kind":"mc","stem":"남겨진 어느 가족의 기록으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이름이 덜 알려진 사람들도 큰 고통을 견디며 독립운동을 도왔다","correct":true},{"t":"나라 밖 생활은 넉넉하고 편했다","mis":"SO5-2-u3-X12"},{"t":"독립군은 돈 걱정 없이 싸웠다","mis":"SO5-2-u3-X12"},{"t":"기록은 역사를 아는 데 쓸모가 없다","mis":"SO5-2-u3-X47"}],"explanation":["재산을 팔고 떠났어요.","굶는 날이 많았어요.","그래도 독립군을 도왔어요."],"asset":{"type":"passage","lines":["한 집안의 형제들이 집과 땅을 모두 팔았다.","가족을 이끌고 추운 겨울 강을 건너 만주로 갔다.","그곳에 학교를 세워 독립군을 길렀다.","하루 한 끼도 어려웠지만 옷을 지어 번 돈마저 독립군에게 보냈다."],"title":"남겨진 어느 가족의 기록"}}'::jsonb),
('g5_2_soc_u3_L02_challenge#8','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C5',4,'mc','auto','「헌병 경찰 → 나라 밖 독립운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X09','SO5-2-u3-X10']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C5","difficulty":4,"kind":"mc","stem":"「헌병 경찰 → 나라 밖 독립운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?","options":[{"t":"헌병이 감시하고 탄압해서 → 나라 안 독립운동이 어려워졌고 → 독립운동가들은 나라 밖에 학교와 단체를 세웠다","correct":true},{"t":"나라 밖에 학교를 세워서 → 헌병이 생겼다","mis":"SO5-2-u3-X46"},{"t":"헌병이 독립운동을 도와서 → 독립군이 생겼다","mis":"SO5-2-u3-X09"},{"t":"토지 조사 사업으로 땅을 얻어서 → 만주로 갔다","mis":"SO5-2-u3-X10"}],"explanation":["헌병이 감시했어요.","나라 안이 어려워졌어요.","나라 밖에서 힘을 길렀어요."]}'::jsonb),
