('g5_2_soc_u3_L09_challenge#8','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',4,'mc','auto','대한민국 임시 정부 수립 기념일을 알리는 옷을 만들 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C24","difficulty":4,"kind":"mc","stem":"대한민국 임시 정부 수립 기념일을 알리는 옷을 만들 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"그림 — 상하이의 작은 청사와 태극기 · 문구 — 「힘을 모아 나라를 되찾자」","correct":true},{"t":"그림 — 천막 학교 · 문구 — 「전쟁을 멈추자」","mis":"SO5-2-u3-X45"},{"t":"그림 — 투표함 · 문구 — 「첫 민주 선거」","mis":"SO5-2-u3-X45"},{"t":"그림 — 장터의 옷감 · 문구 — 「우리 물건을 쓰자」","mis":"SO5-2-u3-X45"}],"explanation":["임시 정부는 상하이에 있었어요.","힘을 모으려 세웠어요.","그 뜻을 담아요."]}'::jsonb),
