('g5_2_soc_u3_review_c#10','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C7',2,'error','auto','만주와 미국에서 이어진 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C7","difficulty":2,"kind":"error","stem":"만주와 미국에서 이어진 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정우 — 「흥사단은 만주에서 독립군을 기른 학교야.」","correct":true,"mis_target":"SO5-2-u3-X13"},{"t":"서윤 — 「신흥 무관 학교는 만주에 있었어.」","mis":"SO5-2-u3-X13"},{"t":"하민 — 「흥사단은 미국에서 실력을 키웠어.」","mis":"SO5-2-u3-X13"}],"explanation":["흥사단은 미국이에요.","만주 학교는 신흥 무관 학교예요.","정우의 말이 잘못됐어요."]}'::jsonb),
