('g5_2_soc_u3_review_d#21','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C23',3,'ox','auto','솔이네 기억 상자 ⑧의 신청서는 전쟁이 끝난 지 오랜 세월이 지나도 이어진 아픔을 보여 줘요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":21,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"ox","stem":"솔이네 기억 상자 ⑧의 신청서는 전쟁이 끝난 지 오랜 세월이 지나도 이어진 아픔을 보여 줘요.","answer":"O","reason_options":[{"t":"휴전선 때문에 헤어진 가족을 오래도록 찾고 그리워했기 때문에","correct":true},{"t":"신청서는 전쟁이 시작된 날 쓴 것이기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["오랜 세월이 지났어요.","아직 동생을 찾았어요.","아픔이 이어졌어요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb),
('g5_2_soc_u3_review_d#22','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C20',3,'mc','auto','광복과 대한민국 정부 수립 사이에 있었던 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":22,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"mc","stem":"광복과 대한민국 정부 수립 사이에 있었던 일로 알맞은 것은 어느 것인가요?","options":[{"t":"38도선 남북에 미군과 소련군이 들어오고 5·10 총선거를 치렀다","correct":true},{"t":"3·1 운동이 일어났다","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁이 일어났다","mis":"SO5-2-u3-X46"},{"t":"을사늑약을 맺었다","mis":"SO5-2-u3-X46"}],"explanation":["광복 뒤 38도선이 생겼어요.","총선거를 치렀어요.","그 뒤 정부를 세웠어요."]}'::jsonb),
('g5_2_soc_u3_review_d#23','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C23',4,'mc','auto','솔이네 할머니의 기억 상자를 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X47']::text[],false,'{"seq":23,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"mc","stem":"솔이네 할머니의 기억 상자를 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 되찾으려 애쓴 사람들과 전쟁의 아픔을 기억하고 평화를 소중히 여긴다","correct":true},{"t":"지난 일이니 모두 잊는다","mis":"SO5-2-u3-X43"},{"t":"날짜만 외우고 넘어간다","mis":"SO5-2-u3-X47"},{"t":"다른 집안 이야기는 나와 관계없다고 여긴다","mis":"SO5-2-u3-X47"}],"explanation":["노력을 기억해요.","아픔도 기억해요.","평화를 소중히 여겨요."]}'::jsonb),
('g5_2_soc_u3_review_d#24','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C19',4,'essay','teacher','솔이네 기억 상자 ⑥을 보고 8·15 광복 뒤 달라진 생활 두 가지를 쓰고, 대한민국 정부가 세워지는 과정을 차례대로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u3-C19","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ⑥을 보고 8·15 광복 뒤 달라진 생활 두 가지를 쓰고, 대한민국 정부가 세워지는 과정을 차례대로 쓰세요.","answer_guide":{"answer":"예: 할머니는 일본식 이름 대신 자기 이름을 다시 썼고, 다시 나온 한글 신문을 읽었다. 정부는 남한에서 5·10 총선거를 치러 국회의원을 뽑고, 국회가 헌법을 만들어 알린 뒤, 헌법에 따라 대통령을 뽑고, 8월 15일에 대한민국 정부를 세웠다.","scoring_points":["달라진 생활 두 가지를 썼는가","총선거부터 정부 수립까지 차례를 썼는가","기억 상자를 근거로 들었는가"]},"explanation":["이름을 되찾았어요.","한글 신문을 읽었어요.","선거 → 헌법 → 대통령 → 정부예요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb),
('g5_2_soc_u3_review_d#25','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C22',4,'essay','teacher','이 단원에서 배운 사람들 가운데 가장 마음에 남는 사람들(예: 의병, 3·1 운동의 학생, 피란민)을 골라, 그 사람들의 생활과 마음을 그때의 사실에 맞게 쓰고 오늘의 나와 이어 생각을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u3-C22","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 사람들 가운데 가장 마음에 남는 사람들(예: 의병, 3·1 운동의 학생, 피란민)을 골라, 그 사람들의 생활과 마음을 그때의 사실에 맞게 쓰고 오늘의 나와 이어 생각을 쓰세요.","answer_guide":{"answer":"예: 천막 학교에서 공부한 피란민 학생들이 마음에 남는다. 집은 판잣집이고 물도 모자랐지만 전쟁이 끝난 뒤를 위해 배움을 멈추지 않았다. 오늘 나는 튼튼한 교실에서 공부하니, 그 학생들처럼 배움을 소중히 여기고 평화를 지키는 사람이 되고 싶다.","scoring_points":["사람들을 하나 골랐는가","생활과 마음을 사실에 맞게 썼는가","오늘의 나와 이어 썼는가"]},"explanation":["사람들을 골라요.","사실에 맞게 써요.","오늘의 나와 이어요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-1-u1-C1','kor',6,1,'u1',1,'가치의 뜻 — 사람들이 자신의 삶에서 중요하게 여기는 것 (물건에 매겨진 값이나 누구나 지켜야 하는 하나의 규칙이 아니다)',ARRAY['6국05-06 문학']::text[],1),
('K6-1-u1-C2','kor',6,1,'u1',1,'가치를 나타내는 낱말 — 용기 · 배려 · 정직 · 끈기 · 자유 · 평화 · 존중 · 성실 · 우정 · 희망 · 책임 · 성장처럼 마음이 무엇을 향하는지 나타내는 낱말이며, 운동장 · 숙제 · 시간표처럼 눈에 보이는 물건이나 하는 일과는 다르다',ARRAY['6국05-06 문학']::text[],2),
('K6-1-u1-C3','kor',6,1,'u1',1,'사람마다 앞에 두는 가치가 다르다 — 세상에는 여러 가치가 함께 있고 사람마다 살아온 일이 달라 앞에 두는 가치도 다르며, 서로 어긋나 보여도 둘 다 옳을 수 있으므로 어느 가치가 더 훌륭한지 등수를 매기지 않고 다른 사람이 소중히 여기는 것을 이해하고 존중한다',ARRAY['6국05-06 문학']::text[],3),
('K6-1-u1-C4','kor',6,1,'u1',1,'말과 행동에 숨은 가치 — 인물이 한 말과 행동에는 소중히 여기는 것이 숨어 있어(맡은 일은 끝까지 하고 싶었다 → 책임 · 어제보다 나아지는 게 좋다 → 성장 · 누군가 돌아왔을 때 마실 물이 있어야 한다 → 약속), 그 사람이 무엇을 얻으려고 그렇게 했는지 생각하면 가치가 보인다',ARRAY['6국05-06 문학']::text[],4),
('K6-1-u1-C5','kor',6,1,'u1',1,'실망스러운 인물에게서도 얻는 생각 — 본받고 싶은 인물뿐 아니라 실망스러운 인물(먼저 떠나며 우물을 덮자고 한 사람)에게서도 편한 쪽만 고르면 무엇이 없어지는지처럼 생각할 거리를 얻을 수 있다',ARRAY['6국05-06 문학']::text[],5),
('K6-1-u1-C6','kor',6,1,'u1',2,'전기문의 뜻 — 실제로 있었던 인물과 사건을 바탕으로 그 사람의 삶을 사실에 근거해 적은 글로, 지어낸 이야기가 아니므로 그 시대의 모습이 함께 담긴다 (있음직한 일을 지어낸 글이나 오늘 일을 그날 알리는 글과 다르다)',ARRAY['6국05-06 문학']::text[],6),
('K6-1-u1-C7','kor',6,1,'u1',2,'글에서 시대 상황 찾기 — 「나라는 이미 일본에 빼앗긴 뒤였다 · 여자가 먼 길을 홀로 떠나는 일이 드물던 때 · 국경을 넘다 붙잡히면 목숨이 위험했다 · 임시정부는 추격을 피해 옮겨 다녔다」처럼 그때가 어떤 때였는지 알려 주는 문장이 시대 상황이다',ARRAY['6국05-06 문학']::text[],7),
('K6-1-u1-C8','kor',6,1,'u1',2,'시대 상황과 관련지어 말과 행동 읽기 — 같은 말도 때에 따라 무게가 달라서, 「제가 다녀오겠습니다」는 시대를 빼고 보면 심부름을 맡겠다는 말이지만 붙잡히면 목숨이 위험한 때를 넣고 보면 목숨을 걸고 나서겠다는 말이 된다',ARRAY['6국05-06 문학']::text[],8),
('K6-1-u1-C9','kor',6,1,'u1',2,'되풀이되는 말과 행동에서 가치 찾기 — 한 번 한 일보다 여러 번 되풀이한 일(조사를 받고도 다시 길을 나섬)과 처음부터 끝까지 이어지는 태도에 인물이 소중히 여기는 것이 드러나며, 근거는 글에 실제로 나온 일에서만 찾는다',ARRAY['6국05-06 문학']::text[],9),
('K6-1-u1-C10','kor',6,1,'u1',2,'인물이 추구하는 가치를 파악하는 방법 — 인물이 처한 상황을 이해하고 → 인물이 한 말과 행동을 살피고 → 그 상황에서 그렇게 한 까닭을 생각하며 추구하는 가치를 파악하며, 이 방법은 전기문뿐 아니라 이야기 · 시 · 극본에도 그대로 쓴다 (가치 낱말을 먼저 정해 놓고 장면을 끼워 맞추지 않는다)',ARRAY['6국05-06 문학']::text[],10),
('K6-1-u1-C11','kor',6,1,'u1',2,'근거가 있으면 다른 답도 좋은 답 — 같은 글을 읽어도 어디에 주목하느냐에 따라 인물이 추구하는 가치를 다르게 볼 수 있어(위험을 알고 강을 건넘 → 용기 · 계속 되풀이함 → 책임), 중요한 것은 글에서 근거를 댈 수 있는가이며 근거 없이 고른 가치는 좋은 답이 아니다',ARRAY['6국05-06 문학']::text[],11),
('K6-1-u1-C12','kor',6,1,'u1',4,'낯선 낱말의 뜻 알기 — 읽기 전이나 읽으며 낯선 낱말의 뜻을 알아 두면 내용이 잘 이해된다 (옹기 = 간장 · 김치 따위를 담는 질그릇 · 수비 = 흙을 물에 풀어 고운 흙만 걸러 내는 일 · 잿물 = 그릇 겉에 입혀 윤이 나게 하는 물 · 가마 = 그릇을 넣고 불을 때어 구워 내는 시설 · 수선 = 낡거나 헌 물건을 고침 · 부품 = 기계를 이루는 낱낱의 조각 · 돋보기 = 작은 것을 크게 보이게 하는 알 · 고집 = 자기 생각을 굽히지 않음)',ARRAY['6국02-05 읽기']::text[],12),
('K6-1-u1-C13','kor',6,1,'u1',4,'일이 일어난 차례 간추리기 — 사건을 시간 차례에 따라 간추리며 앞의 일이 뒤의 일의 까닭이 되는 흐름을 잡으면(흙만 거르는 날이 길어짐 → 만복의 조바심 → 항아리가 갈라진 일 → 만복은 떠나고 연수는 남음) 인물이 왜 그런 선택을 했는지 보인다',ARRAY['6국05-06 문학']::text[],13),
('K6-1-u1-C14','kor',6,1,'u1',4,'비슷한 처지의 두 인물이 추구하는 가치 비교 — 같은 해에 들어와 같이 가난하고 같은 일을 맡은 만복과 연수도 바라보는 곳이 달라(만복 — 결과와 앞날 · 성취와 효, 연수 — 과정과 쓸 사람 · 정성과 끈기와 책임), 처지가 같아도 추구하는 가치는 다를 수 있으며 그 다른 까닭을 찾는다',ARRAY['6국05-06 문학']::text[],14),
('K6-1-u1-C15','kor',6,1,'u1',4,'옳고 그름으로 가르지 않기 — 「연수가 옳고 만복이 잘못했다 · 돈을 좇는 것은 나쁜 가치다」처럼 옳다 · 그르다, 좋다 · 나쁘다로 갈라 버리면 인물이 보이지 않으므로, 두 사람이 소중히 여기는 것이 어떻게 다른지와 처지가 같은데 왜 다른 길을 골랐는지를 묻는다 (만복이 돈을 앞에 둔 데에도 가난한 어머니를 빨리 모시려는 까닭이 있다)',ARRAY['6국05-06 문학']::text[],15),
('K6-1-u1-C16','kor',6,1,'u1',4,'같은 가치도 실천하는 모습이 다르다 — 만복의 효는 빨리 돈을 벌어 어머니께 집을 지어 드리는 것이고 연수의 효는 어머니가 부끄럽지 않을 만큼 한 가지 일을 익히는 것이듯, 가치는 낱말만 보아서는 알 수 없고 어떤 상황에서 어떻게 실천되는지를 함께 보아야 뜻이 제대로 보인다',ARRAY['6국05-06 문학']::text[],16),
('K6-1-u1-C17','kor',6,1,'u1',4,'가치를 알아보는 질문과 인물 면담 — 인물이 추구하는 가치를 알아보려면 「( )을 한 까닭은 무엇인가요? · ( )할 때 어떤 생각이 · 어떤 마음이 들었나요?」처럼 까닭과 생각과 마음을 묻는 질문이 좋으며(글을 보면 바로 답이 나오는 질문은 가치를 알려 주지 못한다), 면담에서는 내 생각이 아니라 그 인물의 처지에서 답한다',ARRAY['6국01-03 듣기·말하기']::text[],17),
('K6-1-u1-C18','kor',6,1,'u1',7,'인물의 마음을 짐작해 가치 찾기 — 인물의 마음(소진이 목 안이 뜨거워지며 화를 냄 — 오래 해 온 것을 쉽게 놓은 듯 보여 받아들이기 어려움)과 인물이 추구하는 가치(끈기)는 다르지만, 마음을 먼저 짐작해 보면 그 아래에 있는 소중히 여기는 것을 찾을 수 있다',ARRAY['6국05-06 문학']::text[],18),
('K6-1-u1-C19','kor',6,1,'u1',7,'두 인물의 가치와 선택의 까닭 — 밀려도 연습을 두 배로 하는 소진(끈기 · 도전)과 할 만큼 해 본 뒤 하고 싶은 것으로 옮긴 윤아(자아실현 · 즐거움 · 후회 없는 노력)는 둘 다 대충 한 사람이 아니고 무엇을 앞에 두느냐가 달랐을 뿐이며, 선택의 까닭을 알면 다른 선택도 이해할 수 있다',ARRAY['6국05-06 문학']::text[],19),
('K6-1-u1-C20','kor',6,1,'u1',7,'인물의 가치를 내 삶과 관련짓기 — 인물과 비슷한 마음이 들었던 내 경험을 떠올리고 → 그때 나의 선택과 인물의 선택에서 같은 점과 다른 점을 찾고 → 내가 앞으로 어떤 가치를 추구하며 무엇을 해 볼지 정한다 (인물 이야기만 다시 하거나 인물을 평가만 하는 말은 관련짓기가 아니다)',ARRAY['6국02-05 읽기']::text[],20),
('K6-1-u1-C21','kor',6,1,'u1',7,'가치에는 등수가 없다 — 「끈기가 즐거움보다 훌륭하다」처럼 가치를 한 줄로 세우지 않으며, 사람마다 살아온 일이 달라 선택의 까닭도 다르므로 특정한 가치를 절대로 여기지 않고 저마다의 까닭을 살핀다',ARRAY['6국05-06 문학']::text[],21),
('K6-1-u1-C22','kor',6,1,'u1',7,'가치를 담은 편지 — 인물에게 쓰거나 인물이 되어 나에게 쓰며, 인물의 가치를 보며 생각이 달라진 점이나 새롭게 깨달은 점과 내가 추구하고 싶은 가치를 어떻게 실천할지 다짐을 담고, 편지 형식을 다 갖추는 것보다 가치와 까닭이 드러나는 것이 더 중요하다',ARRAY['6국02-05 읽기']::text[],22),
('K6-1-u1-C23','kor',6,1,'u1',9,'인물의 생각이 바뀌는 흐름 따라 읽기 — 인물의 생각은 한곳에 머물지 않으므로(진아 — 간판이 부끄러움 → 이름표 뒷면의 사연으로 손님의 마음을 앎 → 돌려보내는 할아버지에 놀람 → 할머니 시계가 돌자 부끄럽지 않음) 어디에서 무엇을 보고 어떻게 바뀌었는지 장면마다 따라가며 읽는다',ARRAY['6국05-06 문학']::text[],23),
('K6-1-u1-C24','kor',6,1,'u1',9,'같은 이야기 다른 판단 — 둘 다 근거로 — 「할아버지는 지나치게 옛것을 붙잡는다(근거: 고치는 값이 새것과 비슷함)」와 「할아버지는 고집이 아니라 정성이다(근거: 손해가 될 때는 새로 사라고 돌려보낸 장면)」처럼 같은 작품도 가치에 대한 판단이 갈릴 수 있으며, 가치에는 위아래 순서가 없고 중요한 것은 글에서 댄 근거다',ARRAY['6국05-06 문학']::text[],24),
('K6-1-u1-C25','kor',6,1,'u1',9,'가치를 고르는 일에 따르는 고민 — 「아끼는 것이 좋다」고 말하기는 쉽지만 실제로는 시간이 더 들고 값이 더 들고 기다려야 하듯, 가치를 고른다는 것은 그 어려움까지 고르는 일이며 정답은 없고 까닭이 있으면 된다',ARRAY['6국05-06 문학']::text[],25),
('K6-1-u1-C26','kor',6,1,'u1',9,'독서 감상문에 넣을 것 — 읽은 작품과 간단한 줄거리(길게 늘어놓지 않음) · 인물이 추구하는 가치와 그 근거가 된 장면 · 그 가치에 대한 내 생각과 떠오른 내 경험 · 내가 앞으로 추구하고 싶은 가치와 실천할 일을 넣으며, 줄거리를 옮겨 적거나 「재미있었다」로 끝나는 글은 감상문이라 하기 어렵고, 형식은 줄글 · 편지 · 그림이나 만화 가운데 골라도 된다',ARRAY['6국05-06 문학']::text[],26),
('K6-1-u1-C27','kor',6,1,'u1',9,'감상을 존중하며 주고받기 — 같은 작품을 읽어도 가치에 대한 생각은 서로 다르므로, 다른 생각을 들었을 때 「틀렸다」고 하지 않고 「어느 장면을 보고 그렇게 생각했어?」라고 물으며 예의 바르게 의견을 나눈다',ARRAY['6국01-03 듣기·말하기']::text[],27),
('K6-1-u1-C28','kor',6,1,'u1',12,'인물 소개의 중심은 가치 — 인물을 소개할 때 중심은 이름이나 줄거리나 책 자랑이 아니라 그 인물이 추구하는 가치이므로, 가치와 그 근거가 되는 장면을 말할 수 있는 인물을 고르고(인기 · 유명함 · 책 두께가 기준이 아님) 고른 까닭 · 가치가 드러난 장면 · 새롭게 안 점이나 본받고 싶은 점을 담는다',ARRAY['6국01-03 듣기·말하기']::text[],28),
('K6-1-u1-C29','kor',6,1,'u1',12,'소개 자료의 짜임과 지킬 것 — 처음(책 제목 · 지은이 · 인물 이름) → 가운데(인물이 처한 상황 · 말과 행동 · 추구하는 가치) → 끝(인물에 대한 내 생각과 느낌 · 실천하고 싶은 다짐)으로 짜고, 소개하는 글 · 광고지 · 동영상 가운데 골라 만들되 남의 그림 · 사진 · 글은 출처를 밝히거나 직접 만든 것을 쓰고 온라인에서는 예의를 지킨다 (책의 쪽수 · 값처럼 가치를 알려 주지 못하는 정보는 넣지 않는다)',ARRAY['6국01-03 듣기·말하기']::text[],29),
('K6-1-u1-C30','kor',6,1,'u1',12,'균형 있게 소개하기 — 인물의 가치를 소개할 때 무조건 훌륭하다고도 잘못했다고도 하지 않고, 왜 그런 선택을 할 수밖에 없었는지를 함께 말한다(「나는 이 선택에 다 동의하지는 않지만, 이런 상황이었다면 …」)',ARRAY['6국05-06 문학']::text[],30),
('K6-1-u1-C31','kor',6,1,'u1',12,'시에서 말하는 이가 추구하는 가치 — 시의 말하는 이에게도 추구하는 가치가 있어, 같은 방법(처한 상황 — 줄넘기를 하다 자꾸 걸려 세던 수가 처음으로 돌아감 → 말과 행동 — 「한 번 더」라고 말하고 다시 넘음 → 까닭 — 수가 아니라 내가 한 번씩 늘어난다고 여김)으로 끈기 · 성장 같은 가치를 찾으며, 「싫지 않다」에 주목해 즐거움으로 읽어도 근거가 있으면 좋은 답이다',ARRAY['6국05-06 문학']::text[],31),
('K6-1-u1-C32','kor',6,1,'u1',12,'내 삶에서 실천할 일 정하기 — 가치를 파악하는 방법을 아는 데서 그치지 않고 내가 추구하고 싶은 가치를 한 가지 정해 이번 주에 실제로 할 일을 「언제 · 무엇을」이 드러나게 적으며(가치: 책임 / 할 일: 모둠에서 맡은 기록을 끝나는 날까지 빠짐없이 적기), 「열심히 하겠다」처럼 두루뭉술하게 다짐하지 않는다',ARRAY['6국05-06 문학']::text[],32),
('K6-1-u1-C33','kor',6,1,'u1',12,'개선하다 · 적용하다 · 종합하다 — 개선하다 = 잘못된 것이나 부족한 것을 고쳐 더 좋게 만들다(미루는 버릇을 개선하다) · 적용하다 = 알맞게 이용하거나 맞추어 쓰다(가치를 파악하는 방법을 시에도 적용하다) · 종합하다 = 여러 가지를 한데 모아서 합하다(친구들의 의견을 종합하다) (기초 다지기)',ARRAY['기초 다지기(사고 도구어)']::text[],33)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-1-u1-X01','kor',6,'u1',ARRAY['K6-1-u1-C1']::text[],'가치를 물건에 매겨진 값이나 누구나 지켜야 하는 하나의 규칙으로 여긴다','삶에서 중요하게 여기는 것'),
('K6-1-u1-X02','kor',6,'u1',ARRAY['K6-1-u1-C2','K6-1-u1-C4']::text[],'운동장 · 숙제 · 시간표 · 우물처럼 눈에 보이는 물건이나 하는 일을 가치를 나타내는 낱말로 고른다','마음이 무엇을 향하나?'),
('K6-1-u1-X03','kor',6,'u1',ARRAY['K6-1-u1-C3','K6-1-u1-C21']::text[],'어느 가치가 더 훌륭한지 등수를 매기거나 어느 가치가 더 옳은지 가린다','가치에는 등수가 없어요'),
('K6-1-u1-X04','kor',6,'u1',ARRAY['K6-1-u1-C3','K6-1-u1-C27']::text[],'나와 다른 가치를 앞에 두는 사람을 틀렸다고 여긴다','까닭이 다를 뿐이에요'),
('K6-1-u1-X05','kor',6,'u1',ARRAY['K6-1-u1-C4','K6-1-u1-C10']::text[],'인물의 말과 행동이 아니라 나이 · 직업 · 생김새 · 좋아하는 것 같은 겉모습으로 가치를 정한다','무엇을 얻으려고 그렇게 했나?'),
('K6-1-u1-X06','kor',6,'u1',ARRAY['K6-1-u1-C5']::text[],'본받고 싶은 인물에게서만 배울 수 있다고 여겨, 실망스러운 인물에게서는 생각할 거리를 찾지 않는다','실망스러운 인물도 생각을 남겨요'),
('K6-1-u1-X07','kor',6,'u1',ARRAY['K6-1-u1-C6']::text[],'전기문을 있음직한 일을 지어낸 이야기나 그날 일어난 일을 알리는 글로 여긴다','실제 인물 · 사실 근거'),
('K6-1-u1-X08','kor',6,'u1',ARRAY['K6-1-u1-C7','K6-1-u1-C8']::text[],'시대 상황을 빼고 인물의 말과 행동을 읽어, 그 말과 행동에 담긴 무게를 놓친다','그때는 어떤 때였나?'),
('K6-1-u1-X09','kor',6,'u1',ARRAY['K6-1-u1-C9','K6-1-u1-C13']::text[],'글에 나오지 않은 일을 인물이 한 일이나 근거로 고른다','글에 실제로 나온 일만'),
('K6-1-u1-X10','kor',6,'u1',ARRAY['K6-1-u1-C9']::text[],'한 번 한 말이나 행동만 보고 가치를 정해, 여러 번 되풀이된 행동과 이어지는 태도를 보지 않는다','되풀이한 일에 주목'),
('K6-1-u1-X11','kor',6,'u1',ARRAY['K6-1-u1-C10']::text[],'가치 낱말을 먼저 정해 놓고 거기에 맞는 장면을 끼워 맞추거나, 상황 → 말과 행동 → 까닭의 차례를 뒤섞는다','상황 → 말과 행동 → 까닭'),
('K6-1-u1-X12','kor',6,'u1',ARRAY['K6-1-u1-C11','K6-1-u1-C24']::text[],'글에서 근거를 대지 않고 가치를 고르거나, 근거가 있어도 나와 다른 답은 틀린 답이라고 여긴다','근거를 댈 수 있는가'),
('K6-1-u1-X13','kor',6,'u1',ARRAY['K6-1-u1-C10','K6-1-u1-C31']::text[],'가치를 파악하는 방법이 전기문에만 쓰인다고 여겨, 이야기나 시에는 적용하지 않는다','이야기 · 시 · 극본에도'),
('K6-1-u1-X14','kor',6,'u1',ARRAY['K6-1-u1-C12']::text[],'낯선 낱말(수비 · 잿물 · 가마 · 수선 · 부품 · 고집)의 뜻을 서로 헷갈린다','그 낱말이 나온 문장을 다시 봐요'),
('K6-1-u1-X15','kor',6,'u1',ARRAY['K6-1-u1-C13']::text[],'일이 일어난 차례를 뒤섞거나, 앞의 일이 뒤의 일의 까닭이 되는 흐름을 잇지 못한다','앞의 일이 뒤의 일을 불러요'),
('K6-1-u1-X16','kor',6,'u1',ARRAY['K6-1-u1-C14']::text[],'처지가 같으면 추구하는 가치도 같아야 한다고 여긴다','같은 곳에서 다른 곳을 보아요'),
('K6-1-u1-X17','kor',6,'u1',ARRAY['K6-1-u1-C15','K6-1-u1-C30']::text[],'두 인물을 옳다 · 그르다, 좋다 · 나쁘다로 갈라 평가해 다른 길을 고른 까닭을 보지 않는다','왜 다른 길을 골랐을까?'),
('K6-1-u1-X18','kor',6,'u1',ARRAY['K6-1-u1-C16']::text[],'가치 낱말이 같으면 뜻도 같다고 여겨, 그 가치가 어떤 상황에서 어떻게 실천되는지 보지 않는다','어떻게 실천하나?'),
('K6-1-u1-X19','kor',6,'u1',ARRAY['K6-1-u1-C17']::text[],'글을 보면 바로 답이 나오는 질문(몇 해 · 무엇으로)을 가치를 알아보는 질문으로 고른다','까닭 · 생각 · 마음을 묻는 질문'),
('K6-1-u1-X20','kor',6,'u1',ARRAY['K6-1-u1-C17']::text[],'인물 면담에서 그 인물의 처지가 아니라 내 생각으로 답한다','그 인물이라면?'),
('K6-1-u1-X21','kor',6,'u1',ARRAY['K6-1-u1-C18']::text[],'인물의 마음(화남 · 서운함)과 인물이 추구하는 가치를 같은 것으로 여긴다','마음 아래에 있는 소중한 것'),
('K6-1-u1-X22','kor',6,'u1',ARRAY['K6-1-u1-C18']::text[],'인물이 그런 마음이 든 까닭을 글에 없는 겉일(상을 더 받음 · 약속에 늦음)에서 찾는다','글 속 장면에서 까닭 찾기'),
('K6-1-u1-X23','kor',6,'u1',ARRAY['K6-1-u1-C19','K6-1-u1-C21']::text[],'다른 가치를 고른 인물을 대충 한 사람이나 참을성 없는 사람으로 여긴다','무엇을 앞에 두느냐가 다를 뿐'),
('K6-1-u1-X24','kor',6,'u1',ARRAY['K6-1-u1-C20']::text[],'인물 이야기만 다시 하거나 인물을 평가만 하는 것을 내 삶과 관련지은 것으로 여긴다','내 경험 · 내 선택은?'),
('K6-1-u1-X25','kor',6,'u1',ARRAY['K6-1-u1-C22','K6-1-u1-C32']::text[],'다짐을 「열심히 하겠다」처럼 언제 무엇을 할지 없이 두루뭉술하게 쓴다','언제 · 무엇을'),
('K6-1-u1-X26','kor',6,'u1',ARRAY['K6-1-u1-C22']::text[],'가치를 담은 편지에서 형식을 다 갖추는 것이 가치와 까닭보다 중요하다고 여긴다','가치와 까닭이 먼저'),
('K6-1-u1-X27','kor',6,'u1',ARRAY['K6-1-u1-C23']::text[],'인물의 생각이 처음부터 끝까지 그대로라고 여겨, 무엇을 보고 어떻게 바뀌었는지 따라가지 않는다','장면마다 생각이 어떻게?'),
('K6-1-u1-X28','kor',6,'u1',ARRAY['K6-1-u1-C25']::text[],'가치를 고르는 일을 말로 고르면 끝나는 쉬운 일로 여겨, 실제로 따르는 어려움(시간 · 값 · 기다림)을 보지 않는다','그 어려움까지 고르는 일'),
('K6-1-u1-X29','kor',6,'u1',ARRAY['K6-1-u1-C26']::text[],'독서 감상문을 줄거리를 옮겨 적는 글로 여긴다','가치에 대한 내 생각'),
('K6-1-u1-X30','kor',6,'u1',ARRAY['K6-1-u1-C26']::text[],'독서 감상문에 「재미있었다 · 좋은 이야기였다」처럼 어느 장면이 왜 그런지 없이 막연한 느낌만 쓴다','가치 · 근거 장면 · 내 경험'),
('K6-1-u1-X31','kor',6,'u1',ARRAY['K6-1-u1-C26']::text[],'독서 감상문은 반드시 줄글로만 써야 한다고 여긴다','편지 · 그림 · 만화도 돼요'),
('K6-1-u1-X32','kor',6,'u1',ARRAY['K6-1-u1-C24','K6-1-u1-C23']::text[],'인물을 한 장면만 보고 판단해, 판단을 바꿀 수 있는 다른 장면(돌려보낸 장면)을 놓친다','다른 장면도 살펴요'),
('K6-1-u1-X33','kor',6,'u1',ARRAY['K6-1-u1-C28']::text[],'인물 소개를 책 자랑 · 줄거리 · 이야기의 끝을 알려 주는 일로 여겨 가치를 빠뜨린다','책 광고가 아니라 가치 소개'),
('K6-1-u1-X34','kor',6,'u1',ARRAY['K6-1-u1-C28']::text[],'소개할 인물을 인기 · 유명함 · 책 두께로 고른다','가치와 근거를 댈 수 있는 인물'),
('K6-1-u1-X35','kor',6,'u1',ARRAY['K6-1-u1-C29']::text[],'소개 자료의 처음 · 가운데 · 끝에 넣을 내용을 뒤섞거나, 쪽수 · 값처럼 가치와 상관없는 정보를 넣는다','처음 · 가운데 · 끝'),
('K6-1-u1-X36','kor',6,'u1',ARRAY['K6-1-u1-C29']::text[],'남의 그림 · 사진 · 글을 출처를 밝히지 않고 가져다 쓴다','출처를 밝히거나 직접 만든 것'),
('K6-1-u1-X37','kor',6,'u1',ARRAY['K6-1-u1-C31']::text[],'시에는 인물이 없어 가치를 찾을 수 없다고 여기거나, 말하는 이의 말과 행동이 아닌 곳에서 가치를 찾는다','말하는 이가 한 말과 행동'),
('K6-1-u1-X38','kor',6,'u1',ARRAY['K6-1-u1-C33']::text[],'개선하다 · 적용하다 · 종합하다의 뜻을 서로 헷갈린다','고침 · 맞추어 씀 · 모아서 합함'),
('K6-1-u1-X39','kor',6,'u1',ARRAY['K6-1-u1-C32','K6-1-u1-C20']::text[],'가치를 파악하는 방법을 아는 데서 그쳐, 내 삶에서 실제로 할 일까지 정하지 않는다','이번 주에 실제로 할 일은?')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_kor_u1_L01_basic#1','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C1',1,'mc','auto','「가치」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X01','K6-1-u1-X02']::text[],false,'{"seq":1,"concept":"K6-1-u1-C1","difficulty":1,"kind":"mc","stem":"「가치」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 자신의 삶에서 중요하게 여기는 것","correct":true},{"t":"물건에 매겨진 값","mis":"K6-1-u1-X01"},{"t":"누구나 지켜야 하는 하나의 규칙","mis":"K6-1-u1-X01"},{"t":"학교에서 정한 시간표","mis":"K6-1-u1-X02"}],"explanation":["값은 물건에 붙는 것이에요.","규칙은 모두가 지키는 약속이에요.","가치는 삶에서 중요하게 여기는 것이에요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#2','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C2',1,'mc','auto','가치를 나타내는 낱말은 어느 것인가요?',ARRAY['K6-1-u1-X02']::text[],false,'{"seq":2,"concept":"K6-1-u1-C2","difficulty":1,"kind":"mc","stem":"가치를 나타내는 낱말은 어느 것인가요?","options":[{"t":"우정","correct":true},{"t":"운동장","mis":"K6-1-u1-X02"},{"t":"숙제","mis":"K6-1-u1-X02"},{"t":"시간표","mis":"K6-1-u1-X02"}],"explanation":["운동장 · 숙제 · 시간표는 눈에 보이는 것이나 하는 일이에요.","우정은 마음이 향하는 것이에요.","가치 낱말은 마음이 무엇을 향하는지 나타내요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#3','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C4',1,'mc','auto','예서가 소중히 여기는 가치로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X05','K6-1-u1-X02']::text[],false,'{"seq":3,"concept":"K6-1-u1-C4","difficulty":1,"kind":"mc","stem":"예서가 소중히 여기는 가치로 알맞은 것은 어느 것인가요?","options":[{"t":"책임","correct":true},{"t":"경쟁","mis":"K6-1-u1-X05"},{"t":"급식","mis":"K6-1-u1-X02"},{"t":"자유","mis":"K6-1-u1-X05"}],"explanation":["아무도 안 하려는 일을 한 학기 내내 했어요.","「맡은 일은 끝까지」라고 말했어요.","맡은 일을 끝까지 하려는 마음은 책임이에요."],"asset":{"type":"speech","turns":[{"who":"예서","text":"우리 반 급식 도우미는 아무도 안 하려고 해. 그래도 나는 한 학기 내내 했어. 맡은 일은 끝까지 하고 싶었거든."},{"who":"리안","text":"나는 달리기에서 계속 져. 그래도 아침마다 운동장을 돌아. 이기는 것보다 어제보다 나아지는 게 좋아서."}]}}'::jsonb),
('g6_1_kor_u1_L01_basic#4','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C3',1,'ox','auto','세상에는 여러 가치가 있고 사람마다 앞에 두는 가치가 다를 수 있어요.',ARRAY['K6-1-u1-X03']::text[],false,'{"seq":4,"concept":"K6-1-u1-C3","difficulty":1,"kind":"ox","stem":"세상에는 여러 가치가 있고 사람마다 앞에 두는 가치가 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 살아온 일이 달라 앞에 두는 것도 다르기 때문에","correct":true},{"t":"가치는 하나뿐이라 모두 같은 것을 앞에 두어야 하기 때문에","mis":"K6-1-u1-X03"}],"mis":"K6-1-u1-X03","explanation":["용기 · 배려 · 정직 · 끈기 …… 가치는 여럿이에요.","살아온 일이 다르면 앞에 두는 것도 달라요.","다른 사람의 가치를 이해하고 존중해요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#5','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C4',2,'mc','auto','리안이 「어제보다 나아지는 게 좋아서」 운동장을 돈다고 한 말에 숨은 가치는 무엇인가요?',ARRAY['K6-1-u1-X05','K6-1-u1-X02']::text[],false,'{"seq":5,"concept":"K6-1-u1-C4","difficulty":2,"kind":"mc","stem":"리안이 「어제보다 나아지는 게 좋아서」 운동장을 돈다고 한 말에 숨은 가치는 무엇인가요?","options":[{"t":"성장","correct":true},{"t":"승리","mis":"K6-1-u1-X05"},{"t":"운동장","mis":"K6-1-u1-X02"},{"t":"편안함","mis":"K6-1-u1-X05"}],"explanation":["리안은 이기는 것보다 나아지는 것을 좋아해요.","어제보다 나아지는 것은 성장이에요.","운동장은 장소라 가치가 아니에요."],"asset":{"type":"speech","turns":[{"who":"예서","text":"우리 반 급식 도우미는 아무도 안 하려고 해. 그래도 나는 한 학기 내내 했어. 맡은 일은 끝까지 하고 싶었거든."},{"who":"리안","text":"나는 달리기에서 계속 져. 그래도 아침마다 운동장을 돌아. 이기는 것보다 어제보다 나아지는 게 좋아서."}]}}'::jsonb),
('g6_1_kor_u1_L01_basic#6','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C4',2,'mc','auto','예서의 감상문에서 우물을 지킨 사람이 추구한 가치로 예서가 본 것은 무엇인가요?',ARRAY['K6-1-u1-X05','K6-1-u1-X02']::text[],false,'{"seq":6,"concept":"K6-1-u1-C4","difficulty":2,"kind":"mc","stem":"예서의 감상문에서 우물을 지킨 사람이 추구한 가치로 예서가 본 것은 무엇인가요?","options":[{"t":"돌아올 사람에 대한 약속","correct":true},{"t":"우물을 팔아 돈을 버는 일","mis":"K6-1-u1-X05"},{"t":"남보다 앞서려는 마음","mis":"K6-1-u1-X05"},{"t":"마을에서 가장 오래된 우물","mis":"K6-1-u1-X02"}],"explanation":["감상문의 마지막 문장을 보아요.","예서는 그 사람이 지킨 것이 우물이 아니라고 했어요.","돌아올 사람에 대한 약속을 지켰다고 보았어요."],"asset":{"type":"passage","lines":["나는 마을에서 가장 오래된 우물을 지킨 사람의 이야기를 읽었다.","마을 사람들이 하나둘 떠나 우물을 쓰는 사람이 줄었을 때에도","그 사람은 날마다 물을 길어 올려 물길을 살려 두었다.","왜 그렇게까지 하느냐는 물음에 그는 이렇게 대답했다고 한다.","「누군가 돌아왔을 때 마실 물이 있어야 하니까요.」","나라면 사람이 없는 우물을 그렇게 오래 돌보지 못했을 것 같다.","그래서 그 사람이 지킨 것은 우물이 아니라","돌아올 사람에 대한 약속이었다고 생각한다."],"title":"예서가 쓴 독서 감상문"}}'::jsonb),
('g6_1_kor_u1_L01_basic#7','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C4',2,'match','auto','인물의 말이나 행동과 어울리는 가치를 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u1-C4","difficulty":2,"kind":"match","stem":"인물의 말이나 행동과 어울리는 가치를 이으세요.","pairs":[{"l":"보는 사람이 없어도 날마다 물을 길었다","r":"꾸준함"},{"l":"무너진 담을 혼자 다시 쌓았다","r":"책임"},{"l":"잘못을 감추지 않고 먼저 말했다","r":"정직"}],"mis":"K6-1-u1-X05","explanation":["날마다 이어 한 일은 꾸준함이에요.","맡은 것을 끝까지 돌보면 책임이에요.","감추지 않고 말하면 정직이에요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#8','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C5',2,'ox','auto','실망스러운 인물에게서는 생각할 거리를 얻을 수 없어요.',ARRAY['K6-1-u1-X06']::text[],false,'{"seq":8,"concept":"K6-1-u1-C5","difficulty":2,"kind":"ox","stem":"실망스러운 인물에게서는 생각할 거리를 얻을 수 없어요.","answer":"X","reason_options":[{"t":"편한 쪽만 고르면 무엇이 없어지는지처럼 실망스러운 인물도 생각을 남기기 때문에","correct":true},{"t":"본받고 싶은 인물만 읽을 가치가 있기 때문에","mis":"K6-1-u1-X06"}],"mis":"K6-1-u1-X06","explanation":["우물을 덮자고 한 사람도 생각을 남겨요.","그 선택이 무엇을 없애는지 생각하게 해요.","본받고 싶은 인물과 실망스러운 인물 모두 생각을 남겨요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#9','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C3',2,'error','auto','가치에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X04']::text[],false,'{"seq":9,"concept":"K6-1-u1-C3","difficulty":2,"kind":"error","stem":"가치에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도하 — 「약속을 지키는 게 자유보다 훨씬 훌륭한 가치야.」","correct":true,"mis_target":"K6-1-u1-X03"},{"t":"은채 — 「사람마다 앞에 두는 가치가 다를 수 있어.」","mis":"K6-1-u1-X03"},{"t":"규리 — 「두 사람이 왜 다른 것을 소중히 여기는지 살펴보자.」","mis":"K6-1-u1-X04"}],"explanation":["은채와 규리는 바르게 말했어요.","도하는 가치에 등수를 매겼어요.","어느 가치가 더 훌륭한지 가리지 않아요."]}'::jsonb),
('g6_1_kor_u1_L01_basic#10','kor',6,1,'u1','L01','g6_1_kor_u1_L01_basic','lesson_basic','K6-1-u1-C3',3,'mc','auto','「나는 약속을 지키는 게 가장 중요해.」, 「나는 하고 싶은 일을 마음껏 해 보는 게 더 중요해.」 두 말을 들었을 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X04']::text[],false,'{"seq":10,"concept":"K6-1-u1-C3","difficulty":3,"kind":"mc","stem":"「나는 약속을 지키는 게 가장 중요해.」, 「나는 하고 싶은 일을 마음껏 해 보는 게 더 중요해.」 두 말을 들었을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"두 사람이 소중히 여기는 것이 어떻게 다른지와 그 까닭을 살펴본다","correct":true},{"t":"둘 가운데 더 옳은 말을 골라 따른다","mis":"K6-1-u1-X03"},{"t":"나와 다른 말을 한 사람에게 틀렸다고 말해 준다","mis":"K6-1-u1-X04"},{"t":"두 말이 어긋나므로 둘 다 틀렸다고 본다","mis":"K6-1-u1-X03"}],"explanation":["두 말은 어긋나 보여도 둘 다 옳을 수 있어요.","옳고 그름을 가리는 일이 아니에요.","어떻게 다른지와 그 까닭을 살펴요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#1','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C2',2,'mc','auto','다음 가운데 가치를 나타내는 낱말끼리 묶은 것은 어느 것인가요?',ARRAY['K6-1-u1-X02']::text[],false,'{"seq":1,"concept":"K6-1-u1-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 가치를 나타내는 낱말끼리 묶은 것은 어느 것인가요?","options":[{"t":"성실 · 희망 · 배려","correct":true},{"t":"성실 · 운동장 · 배려","mis":"K6-1-u1-X02"},{"t":"숙제 · 희망 · 시간표","mis":"K6-1-u1-X02"},{"t":"우물 · 급식 · 달리기","mis":"K6-1-u1-X02"}],"explanation":["운동장 · 숙제 · 시간표 · 우물은 눈에 보이는 것이에요.","급식 · 달리기는 하는 일이에요.","성실 · 희망 · 배려는 마음이 향하는 것이에요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#2','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C1',2,'ox','auto','가치는 물건이 얼마인지 나타내는 값과 같은 뜻이에요.',ARRAY['K6-1-u1-X01']::text[],false,'{"seq":2,"concept":"K6-1-u1-C1","difficulty":2,"kind":"ox","stem":"가치는 물건이 얼마인지 나타내는 값과 같은 뜻이에요.","answer":"X","reason_options":[{"t":"이 단원의 가치는 삶에서 중요하게 여기는 것을 뜻하기 때문에","correct":true},{"t":"가치가 높다는 말은 값이 비싸다는 뜻이기 때문에","mis":"K6-1-u1-X01"}],"mis":"K6-1-u1-X01","explanation":["예서가 맡은 일을 끝까지 한 것에는 값이 없어요.","그래도 소중히 여기는 것이 있어요.","삶에서 중요하게 여기는 것이 가치예요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#3','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C4',3,'mc','auto','예서는 감상문에서 왜 「그 사람이 지킨 것은 우물이 아니라 약속이었다」고 했을까요?',ARRAY['K6-1-u1-X09','K6-1-u1-X05']::text[],false,'{"seq":3,"concept":"K6-1-u1-C4","difficulty":3,"kind":"mc","stem":"예서는 감상문에서 왜 「그 사람이 지킨 것은 우물이 아니라 약속이었다」고 했을까요?","options":[{"t":"「누군가 돌아왔을 때 마실 물이 있어야 한다」는 말에서 돌아올 사람을 생각하는 마음을 읽었기 때문에","correct":true},{"t":"그 사람이 우물을 팔지 않았기 때문에","mis":"K6-1-u1-X09"},{"t":"우물이 마을에서 가장 오래된 것이었기 때문에","mis":"K6-1-u1-X05"},{"t":"그 사람이 마을에서 가장 나이가 많았기 때문에","mis":"K6-1-u1-X05"}],"explanation":["인물이 한 말에 주목해요.","무엇을 얻으려고 날마다 물을 길었는지 생각해요.","돌아올 사람을 위한 약속을 지킨 거예요."],"asset":{"type":"passage","lines":["나는 마을에서 가장 오래된 우물을 지킨 사람의 이야기를 읽었다.","마을 사람들이 하나둘 떠나 우물을 쓰는 사람이 줄었을 때에도","그 사람은 날마다 물을 길어 올려 물길을 살려 두었다.","왜 그렇게까지 하느냐는 물음에 그는 이렇게 대답했다고 한다.","「누군가 돌아왔을 때 마실 물이 있어야 하니까요.」","나라면 사람이 없는 우물을 그렇게 오래 돌보지 못했을 것 같다.","그래서 그 사람이 지킨 것은 우물이 아니라","돌아올 사람에 대한 약속이었다고 생각한다."],"title":"예서가 쓴 독서 감상문"}}'::jsonb),
('g6_1_kor_u1_L01_challenge#4','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C2',3,'error','auto','가치를 나타내는 낱말을 모았어요. 알맞지 않게 모은 친구는 누구인가요?',ARRAY['K6-1-u1-X02']::text[],false,'{"seq":4,"concept":"K6-1-u1-C2","difficulty":3,"kind":"error","stem":"가치를 나타내는 낱말을 모았어요. 알맞지 않게 모은 친구는 누구인가요?","options":[{"t":"하율 — 「용기, 숙제, 존중」","correct":true,"mis_target":"K6-1-u1-X02"},{"t":"서진 — 「정직, 평화, 끈기」","mis":"K6-1-u1-X02"},{"t":"라온 — 「자유, 우정, 성실」","mis":"K6-1-u1-X02"}],"explanation":["서진과 라온은 가치 낱말만 모았어요.","하율은 하는 일인 숙제를 넣었어요.","가치 낱말은 마음이 향하는 것이에요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#5','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C5',3,'mc','auto','먼저 떠나면서 우물을 덮어 버리자고 한 사람에게서 얻을 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X06','K6-1-u1-X05','K6-1-u1-X17']::text[],false,'{"seq":5,"concept":"K6-1-u1-C5","difficulty":3,"kind":"mc","stem":"먼저 떠나면서 우물을 덮어 버리자고 한 사람에게서 얻을 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"편한 쪽만 고르면 다른 사람에게 필요한 것이 없어질 수 있다","correct":true},{"t":"실망스러운 인물이므로 얻을 것이 없다","mis":"K6-1-u1-X06"},{"t":"우물은 덮어 두는 것이 가장 좋다","mis":"K6-1-u1-X05"},{"t":"떠나는 사람은 모두 나쁜 사람이다","mis":"K6-1-u1-X17"}],"explanation":["실망스러운 인물도 생각을 남겨요.","우물을 덮으면 돌아올 사람이 마실 물이 없어져요.","편한 쪽만 고르면 무엇이 없어지는지 생각해요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#6','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C4',3,'mc','auto','예서와 리안의 말을 함께 읽고 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u1-X05','K6-1-u1-X03','K6-1-u1-X01']::text[],false,'{"seq":6,"concept":"K6-1-u1-C4","difficulty":3,"kind":"mc","stem":"예서와 리안의 말을 함께 읽고 알맞게 말한 것은 어느 것인가요?","options":[{"t":"두 사람이 한 일은 다르지만 각자 소중히 여기는 것이 말 속에 숨어 있다","correct":true},{"t":"두 사람 모두 이기는 것을 가장 소중히 여긴다","mis":"K6-1-u1-X05"},{"t":"급식 도우미를 한 예서의 가치가 리안보다 더 훌륭하다","mis":"K6-1-u1-X03"},{"t":"두 사람은 하는 일이 달라서 가치가 없다","mis":"K6-1-u1-X01"}],"explanation":["예서는 책임, 리안은 성장을 말 속에 담았어요.","가치에 등수를 매기지 않아요.","말과 행동 속에서 가치를 찾아요."],"asset":{"type":"speech","turns":[{"who":"예서","text":"우리 반 급식 도우미는 아무도 안 하려고 해. 그래도 나는 한 학기 내내 했어. 맡은 일은 끝까지 하고 싶었거든."},{"who":"리안","text":"나는 달리기에서 계속 져. 그래도 아침마다 운동장을 돌아. 이기는 것보다 어제보다 나아지는 게 좋아서."}]}}'::jsonb),
('g6_1_kor_u1_L01_challenge#7','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C3',3,'match','auto','말과 그 말을 고칠 방향을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u1-C3","difficulty":3,"kind":"match","stem":"말과 그 말을 고칠 방향을 알맞게 이으세요.","pairs":[{"l":"「약속이 자유보다 훌륭해.」","r":"등수를 매기지 않고 어떻게 다른지 본다"},{"l":"「너는 틀렸어.」","r":"왜 그것을 소중히 여기는지 물어본다"},{"l":"「가치는 하나뿐이야.」","r":"여러 가치가 함께 있음을 안다"}],"mis":"K6-1-u1-X04","explanation":["가치에는 등수가 없어요.","다른 사람의 가치는 까닭을 물어 이해해요.","세상에는 여러 가치가 있어요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#8','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C3',4,'mc','auto','우리 반에서 「소풍 장소」를 두고 한 친구는 「모두가 함께 놀 수 있는 곳」을, 다른 친구는 「새로운 것을 배울 수 있는 곳」을 앞세웠어요. 이 단원에서 배운 대로 생각한 것은 어느 것인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X04','K6-1-u1-X01']::text[],false,'{"seq":8,"concept":"K6-1-u1-C3","difficulty":4,"kind":"mc","stem":"우리 반에서 「소풍 장소」를 두고 한 친구는 「모두가 함께 놀 수 있는 곳」을, 다른 친구는 「새로운 것을 배울 수 있는 곳」을 앞세웠어요. 이 단원에서 배운 대로 생각한 것은 어느 것인가요?","options":[{"t":"두 친구가 앞에 두는 가치(함께함 · 배움)가 다르고 그 까닭이 있으니, 까닭을 들어 보고 서로 존중한다","correct":true},{"t":"함께 노는 것이 배우는 것보다 더 옳으니 첫째 친구를 따른다","mis":"K6-1-u1-X03"},{"t":"나와 생각이 다른 친구는 틀렸다고 말해 준다","mis":"K6-1-u1-X04"},{"t":"소풍 장소는 물건이 아니므로 가치와 상관없다","mis":"K6-1-u1-X01"}],"explanation":["두 친구는 앞에 두는 가치가 달라요.","어느 쪽이 더 옳은지 가리지 않아요.","까닭을 들어 보고 존중해요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#9','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C1',4,'essay','teacher','「가치」가 무엇인지 내 말로 설명하고, 내가 소중히 여기는 가치 한 가지를 내가 한 말이나 행동을 근거로 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u1-C1","difficulty":4,"kind":"essay","stem":"「가치」가 무엇인지 내 말로 설명하고, 내가 소중히 여기는 가치 한 가지를 내가 한 말이나 행동을 근거로 들어 쓰세요.","answer_guide":{"answer":"예: 가치는 사람들이 자기 삶에서 중요하게 여기는 것이다. 나는 「배려」를 소중히 여긴다. 왜냐하면 지난주 짝이 준비물을 안 가져왔을 때 내 색연필을 나누어 쓰자고 먼저 말했기 때문이다. 내가 손해를 보더라도 함께 편하게 하고 싶었다.","scoring_points":["가치를 삶에서 중요하게 여기는 것으로 설명했는가","가치 낱말을 하나 골랐는가","내가 한 말이나 행동을 근거로 들었는가"]},"explanation":["가치는 값이나 규칙이 아니에요.","마음이 향하는 낱말을 골라요.","내 말과 행동에서 근거를 찾아요."]}'::jsonb),
('g6_1_kor_u1_L01_challenge#10','kor',6,1,'u1','L01','g6_1_kor_u1_L01_challenge','lesson_challenge','K6-1-u1-C3',4,'essay','teacher','「어떤 가치가 더 훌륭한지 순서를 매기지 않는다.」는 약속이 왜 필요한지 예서와 리안의 말을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u1-C3","difficulty":4,"kind":"essay","stem":"「어떤 가치가 더 훌륭한지 순서를 매기지 않는다.」는 약속이 왜 필요한지 예서와 리안의 말을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 예서는 맡은 일을 끝까지 하는 책임을, 리안은 어제보다 나아지는 성장을 소중히 여긴다. 두 사람은 살아온 일이 달라 앞에 두는 것이 다를 뿐이다. 만약 책임이 성장보다 훌륭하다고 순서를 매기면 리안이 소중히 여기는 것을 낮추어 보게 되고, 리안이 왜 그렇게 하는지 이해할 수 없게 된다. 그래서 순서를 매기지 않고 어떻게 다른지와 그 까닭을 살펴야 한다.","scoring_points":["두 사람의 가치를 바르게 찾았는가","앞에 두는 것이 다를 뿐이라고 썼는가","순서를 매기면 생기는 문제를 썼는가"]},"explanation":["두 사람의 가치를 먼저 찾아요.","앞에 두는 것이 다를 뿐이에요.","순서를 매기면 이해할 수 없게 돼요."],"asset":{"type":"speech","turns":[{"who":"예서","text":"우리 반 급식 도우미는 아무도 안 하려고 해. 그래도 나는 한 학기 내내 했어. 맡은 일은 끝까지 하고 싶었거든."},{"who":"리안","text":"나는 달리기에서 계속 져. 그래도 아침마다 운동장을 돌아. 이기는 것보다 어제보다 나아지는 게 좋아서."}]}}'::jsonb),
('g6_1_kor_u1_L02_basic#1','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C6',1,'mc','auto','전기문에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X07']::text[],false,'{"seq":1,"concept":"K6-1-u1-C6","difficulty":1,"kind":"mc","stem":"전기문에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"실제 인물의 삶을 사실에 근거해 쓴 글","correct":true},{"t":"있음직한 일을 새로 지어낸 글","mis":"K6-1-u1-X07"},{"t":"오늘 일어난 일을 그날 알리는 글","mis":"K6-1-u1-X07"},{"t":"인물의 마음을 짧은 줄로 노래한 글","mis":"K6-1-u1-X07"}],"explanation":["지어낸 이야기와 달라요.","실제로 있었던 인물과 사건이 바탕이에요.","그래서 그 시대의 모습이 함께 담겨요."]}'::jsonb),
('g6_1_kor_u1_L02_basic#2','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C6',1,'ox','auto','전기문에는 인물이 살던 시대의 모습이 함께 담겨요.',ARRAY['K6-1-u1-X07']::text[],false,'{"seq":2,"concept":"K6-1-u1-C6","difficulty":1,"kind":"ox","stem":"전기문에는 인물이 살던 시대의 모습이 함께 담겨요.","answer":"O","reason_options":[{"t":"실제로 있었던 인물과 사건을 바탕으로 쓴 글이기 때문에","correct":true},{"t":"글쓴이가 시대를 마음대로 지어내기 때문에","mis":"K6-1-u1-X07"}],"mis":"K6-1-u1-X07","explanation":["전기문은 지어낸 글이 아니에요.","실제 인물은 실제 시대에 살았어요.","그래서 시대 모습이 함께 담겨요."]}'::jsonb),
('g6_1_kor_u1_L02_basic#3','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C7',1,'mc','auto','「강을 건넌 사람」에서 시대 상황을 알려 주는 문장은 어느 것인가요?',ARRAY['K6-1-u1-X08']::text[],false,'{"seq":3,"concept":"K6-1-u1-C7","difficulty":1,"kind":"mc","stem":"「강을 건넌 사람」에서 시대 상황을 알려 주는 문장은 어느 것인가요?","options":[{"t":"국경을 넘다 붙잡히면 목숨이 위험하던 때였다","correct":true},{"t":"「제가 다녀오겠습니다.」","mis":"K6-1-u1-X08"},{"t":"정정화는 혼자 압록강을 건넜다","mis":"K6-1-u1-X08"},{"t":"그는 끼니를 마련하고 아픈 사람을 돌보았다","mis":"K6-1-u1-X08"}],"explanation":["말과 행동은 인물이 한 일이에요.","시대 상황은 그때가 어떤 때였는지예요.","붙잡히면 목숨이 위험하던 때가 시대 상황이에요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L02_basic#4','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C9',1,'mc','auto','「강을 건넌 사람」에서 정정화가 한 일은 어느 것인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":4,"concept":"K6-1-u1-C9","difficulty":1,"kind":"mc","stem":"「강을 건넌 사람」에서 정정화가 한 일은 어느 것인가요?","options":[{"t":"국내와 상하이를 여러 차례 오갔다","correct":true},{"t":"군대를 이끌고 싸움에 나갔다","mis":"K6-1-u1-X09"},{"t":"외국에서 학교를 세워 교장이 되었다","mis":"K6-1-u1-X09"},{"t":"임시정부를 처음 세웠다","mis":"K6-1-u1-X09"}],"explanation":["글에 실제로 나온 일만 찾아요.","군대 · 학교 이야기는 글에 없어요.","여러 차례 오가며 돈을 모아 왔어요."],"asset":{"type":"passage","lines":["그 뒤로 정정화는 국내와 상하이 사이를 여러 차례 오갔다.","조사를 받은 적도 있었지만 그는 다시 길을 나섰다.","그가 모아 온 돈은 임시정부의 살림과 활동에 쓰였다.","임시정부가 일본의 추격을 피해 여러 도시로 옮겨 다닐 때에도","그는 끼니를 마련하고 아픈 사람을 돌보았다. 이름이 남는 일은 아니었다.","광복이 될 때까지 스물다섯 해 동안 그는 그 일을 놓지 않았다.","그가 남긴 글에는 자랑보다 함께 걸은 사람들의 이름이 더 많았다."],"title":"전기문 「강을 건넌 사람」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L02_basic#5','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C7',2,'mc','auto','이 글의 시대 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X08','K6-1-u1-X09']::text[],false,'{"seq":5,"concept":"K6-1-u1-C7","difficulty":2,"kind":"mc","stem":"이 글의 시대 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 빼앗겨 감시가 심하고 여성의 활동이 제한되던 때","correct":true},{"t":"누구나 자유롭게 나라 밖을 오가던 때","mis":"K6-1-u1-X08"},{"t":"전쟁이 끝나고 나라를 이미 되찾은 때","mis":"K6-1-u1-X08"},{"t":"임시정부에 돈이 넘쳐 나던 때","mis":"K6-1-u1-X09"}],"explanation":["나라는 이미 빼앗긴 뒤였어요.","여자가 홀로 떠나는 일이 드물었어요.","국경을 넘다 붙잡히면 위험했어요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L02_basic#6','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C8',2,'mc','auto','시대 상황을 넣고 보면 「제가 다녀오겠습니다.」는 어떤 말이 되나요?',ARRAY['K6-1-u1-X08','K6-1-u1-X09']::text[],false,'{"seq":6,"concept":"K6-1-u1-C8","difficulty":2,"kind":"mc","stem":"시대 상황을 넣고 보면 「제가 다녀오겠습니다.」는 어떤 말이 되나요?","options":[{"t":"목숨을 걸고 위험한 길에 나서겠다는 말","correct":true},{"t":"가벼운 심부름을 맡겠다는 말","mis":"K6-1-u1-X08"},{"t":"먼 곳으로 여행을 가겠다는 말","mis":"K6-1-u1-X08"},{"t":"남에게 일을 미루겠다는 말","mis":"K6-1-u1-X09"}],"explanation":["시대를 빼면 심부름처럼 보여요.","그때는 붙잡히면 목숨이 위험했어요.","같은 말도 때에 따라 무게가 달라요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L02_basic#7','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C9',2,'match','auto','정정화의 말이나 행동과 그렇게 한 까닭을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u1-C9","difficulty":2,"kind":"match","stem":"정정화의 말이나 행동과 그렇게 한 까닭을 이으세요.","pairs":[{"l":"기다리는 대신 강을 건넜다","r":"스스로 할 일을 찾으려고"},{"l":"조사를 받고도 다시 길을 나섰다","r":"시작한 일을 끝까지 하려고"},{"l":"이름이 남지 않는 살림일을 맡았다","r":"함께하는 사람들을 지키려고"}],"mis":"K6-1-u1-X10","explanation":["기다리기만 해서는 달라지지 않는다고 보았어요.","한 번이 아니라 되풀이했어요.","함께 걷는 사람들을 돌보았어요."]}'::jsonb),
('g6_1_kor_u1_L02_basic#8','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C10',2,'ox','auto','인물이 추구하는 가치를 파악할 때에는 인물이 처한 상황부터 이해해 봐요.',ARRAY['K6-1-u1-X11']::text[],false,'{"seq":8,"concept":"K6-1-u1-C10","difficulty":2,"kind":"ox","stem":"인물이 추구하는 가치를 파악할 때에는 인물이 처한 상황부터 이해해 봐요.","answer":"O","reason_options":[{"t":"상황 → 말과 행동 → 까닭의 차례로 살펴야 가치가 드러나기 때문에","correct":true},{"t":"가치 낱말을 먼저 정해 놓고 장면을 찾으면 되기 때문에","mis":"K6-1-u1-X11"}],"mis":"K6-1-u1-X11","explanation":["먼저 처한 상황을 알아요.","그다음 말과 행동을 살펴요.","그렇게 한 까닭에서 가치를 찾아요."]}'::jsonb),
('g6_1_kor_u1_L02_basic#9','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C10',2,'blank','auto','표의 ( ㉠ )에 들어갈 가치로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X12','K6-1-u1-X02']::text[],false,'{"seq":9,"concept":"K6-1-u1-C10","difficulty":2,"kind":"blank","stem":"표의 ( ㉠ )에 들어갈 가치로 알맞은 것은 어느 것인가요?","options":[{"t":"용기 · 책임 · 함께함","correct":true},{"t":"명예 · 경쟁 · 자랑","mis":"K6-1-u1-X12"},{"t":"편안함 · 휴식","mis":"K6-1-u1-X12"},{"t":"여행 · 상하이","mis":"K6-1-u1-X02"}],"explanation":["위험을 알면서 나섰어요.","여러 번 되풀이했어요.","함께 걸은 사람들의 이름을 남겼어요."],"asset":{"type":"passage","lines":["처한 상황 · 나라를 빼앗기고, 여성이 나서기 어렵던 때","말과 행동 · 홀로 국경을 넘고, 위험을 알면서 여러 번 되풀이함","그렇게 한 까닭 · 기다리기만 해서는 달라지지 않는다고 보았기 때문","추구하는 가치 · ( ㉠ )"],"title":"정정화가 추구한 가치 정리하기"}}'::jsonb),
('g6_1_kor_u1_L02_basic#10','kor',6,1,'u1','L02','g6_1_kor_u1_L02_basic','lesson_basic','K6-1-u1-C11',3,'mc','auto','예서는 정정화의 가치를 「용기」로, 리안은 「책임」으로 보았어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u1-X12','K6-1-u1-X03']::text[],false,'{"seq":10,"concept":"K6-1-u1-C11","difficulty":3,"kind":"mc","stem":"예서는 정정화의 가치를 「용기」로, 리안은 「책임」으로 보았어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"두 사람 모두 글에서 근거를 댈 수 있으므로 둘 다 좋은 답이다","correct":true},{"t":"답은 하나뿐이므로 둘 가운데 하나는 틀렸다","mis":"K6-1-u1-X12"},{"t":"근거와 상관없이 마음에 드는 가치를 고르면 된다","mis":"K6-1-u1-X12"},{"t":"책임이 용기보다 훌륭한 가치이므로 리안이 맞다","mis":"K6-1-u1-X03"}],"explanation":["어디에 주목하느냐에 따라 답이 달라져요.","중요한 것은 글에서 댄 근거예요.","근거가 있으면 서로 다른 답도 좋은 답이에요."]}'::jsonb),
('g6_1_kor_u1_L02_challenge#1','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C6',2,'error','auto','전기문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X07','K6-1-u1-X08']::text[],false,'{"seq":1,"concept":"K6-1-u1-C6","difficulty":2,"kind":"error","stem":"전기문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"해온 — 「전기문은 재미있게 하려고 인물이 하지 않은 일도 지어내.」","correct":true,"mis_target":"K6-1-u1-X07"},{"t":"유나 — 「실제 인물과 사건을 바탕으로 해.」","mis":"K6-1-u1-X07"},{"t":"지호 — 「그 시대의 모습이 함께 담겨.」","mis":"K6-1-u1-X08"}],"explanation":["유나와 지호는 바르게 말했어요.","해온은 전기문을 지어낸 이야기로 여겼어요.","전기문은 사실에 근거해요."]}'::jsonb),
('g6_1_kor_u1_L02_challenge#2','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C9',2,'mc','auto','정정화가 「책임」을 소중히 여겼다는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X08','K6-1-u1-X09','K6-1-u1-X10']::text[],false,'{"seq":2,"concept":"K6-1-u1-C9","difficulty":2,"kind":"mc","stem":"정정화가 「책임」을 소중히 여겼다는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조사를 받은 적이 있어도 다시 길을 나서 여러 차례 오갔다","correct":true},{"t":"스무 살이 되기 전에 나라를 빼앗겼다","mis":"K6-1-u1-X08"},{"t":"훈장을 받아 이름을 널리 알렸다","mis":"K6-1-u1-X09"},{"t":"남편과 시아버지가 상하이로 떠났다","mis":"K6-1-u1-X10"}],"explanation":["나라를 빼앗긴 것은 시대 상황이에요.","남편이 떠난 것은 정정화가 한 일이 아니에요.","되풀이한 행동에서 책임이 보여요."],"asset":{"type":"passage","lines":["그 뒤로 정정화는 국내와 상하이 사이를 여러 차례 오갔다.","조사를 받은 적도 있었지만 그는 다시 길을 나섰다.","그가 모아 온 돈은 임시정부의 살림과 활동에 쓰였다.","임시정부가 일본의 추격을 피해 여러 도시로 옮겨 다닐 때에도","그는 끼니를 마련하고 아픈 사람을 돌보았다. 이름이 남는 일은 아니었다.","광복이 될 때까지 스물다섯 해 동안 그는 그 일을 놓지 않았다.","그가 남긴 글에는 자랑보다 함께 걸은 사람들의 이름이 더 많았다."],"title":"전기문 「강을 건넌 사람」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L02_challenge#3','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C8',3,'mc','auto','「저는 눈에 덜 띕니다.」라는 말을 시대 상황과 관련지어 가장 알맞게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u1-X08','K6-1-u1-X05']::text[],false,'{"seq":3,"concept":"K6-1-u1-C8","difficulty":3,"kind":"mc","stem":"「저는 눈에 덜 띕니다.」라는 말을 시대 상황과 관련지어 가장 알맞게 읽은 것은 어느 것인가요?","options":[{"t":"감시가 심한 때에 여자가 의심을 덜 받는다는 점을 살펴 스스로 위험한 일을 맡겠다는 뜻이다","correct":true},{"t":"자기가 키가 작다는 것을 말한 것이다","mis":"K6-1-u1-X08"},{"t":"남들에게 칭찬받고 싶어서 한 말이다","mis":"K6-1-u1-X05"},{"t":"위험한 일을 피하려고 둘러댄 말이다","mis":"K6-1-u1-X08"}],"explanation":["그때는 감시가 심했어요.","여자가 홀로 떠나는 일이 드물어 덜 의심받았어요.","그 점을 살펴 스스로 나섰어요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L02_challenge#4','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C10',3,'mc','auto','인물이 추구하는 가치를 파악하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X11','K6-1-u1-X05']::text[],false,'{"seq":4,"concept":"K6-1-u1-C10","difficulty":3,"kind":"mc","stem":"인물이 추구하는 가치를 파악하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"처한 상황 이해하기 → 말과 행동 살피기 → 그렇게 한 까닭 생각하기","correct":true},{"t":"가치 낱말 정하기 → 그에 맞는 장면 찾기 → 이유 붙이기","mis":"K6-1-u1-X11"},{"t":"인물의 나이와 직업 → 좋아하는 것 → 가치","mis":"K6-1-u1-X05"},{"t":"그렇게 한 까닭 → 처한 상황 → 말과 행동","mis":"K6-1-u1-X11"}],"explanation":["가치 낱말을 먼저 정하지 않아요.","나이와 직업은 겉모습이에요.","상황 → 말과 행동 → 까닭의 차례예요."]}'::jsonb),
('g6_1_kor_u1_L02_challenge#5','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C13',3,'ox','auto','전기문에서 쓴 가치 파악 방법은 이야기나 시를 읽을 때에도 쓸 수 있어요.',ARRAY['K6-1-u1-X13']::text[],false,'{"seq":5,"concept":"K6-1-u1-C13","difficulty":3,"kind":"ox","stem":"전기문에서 쓴 가치 파악 방법은 이야기나 시를 읽을 때에도 쓸 수 있어요.","answer":"O","reason_options":[{"t":"이야기 · 시 · 극본의 인물이나 말하는 이에게도 상황과 말 · 행동 · 까닭이 있기 때문에","correct":true},{"t":"실제 인물이 아니면 가치가 없기 때문에","mis":"K6-1-u1-X13"}],"mis":"K6-1-u1-X13","explanation":["이야기 속 인물에게도 상황이 있어요.","시의 말하는 이도 말하고 행동해요.","같은 방법을 그대로 써요."]}'::jsonb),
('g6_1_kor_u1_L02_challenge#6','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C11',3,'mc','auto','정정화가 추구한 가치를 말한 것 가운데 좋은 답이라고 하기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u1-X12']::text[],false,'{"seq":6,"concept":"K6-1-u1-C11","difficulty":3,"kind":"mc","stem":"정정화가 추구한 가치를 말한 것 가운데 좋은 답이라고 하기 어려운 것은 어느 것인가요?","options":[{"t":"「명예」 — 사람들이 정정화를 칭찬했을 것 같아서","correct":true},{"t":"「용기」 — 목숨이 위험한 길인 줄 알면서 혼자 강을 건넜기 때문에","mis":"K6-1-u1-X12"},{"t":"「책임」 — 조사를 받고도 다시 길을 나섰기 때문에","mis":"K6-1-u1-X12"},{"t":"「함께함」 — 남긴 글에 자랑보다 함께 걸은 사람들의 이름이 더 많았기 때문에","mis":"K6-1-u1-X12"}],"explanation":["용기 · 책임 · 함께함은 글에서 근거를 댔어요.","명예는 「것 같아서」로 짐작만 했어요.","근거 없이 고른 가치는 좋은 답이 아니에요."],"asset":{"type":"passage","lines":["그 뒤로 정정화는 국내와 상하이 사이를 여러 차례 오갔다.","조사를 받은 적도 있었지만 그는 다시 길을 나섰다.","그가 모아 온 돈은 임시정부의 살림과 활동에 쓰였다.","임시정부가 일본의 추격을 피해 여러 도시로 옮겨 다닐 때에도","그는 끼니를 마련하고 아픈 사람을 돌보았다. 이름이 남는 일은 아니었다.","광복이 될 때까지 스물다섯 해 동안 그는 그 일을 놓지 않았다.","그가 남긴 글에는 자랑보다 함께 걸은 사람들의 이름이 더 많았다."],"title":"전기문 「강을 건넌 사람」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L02_challenge#7','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C7',3,'match','auto','문장과 그 문장이 알려 주는 것을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u1-C7","difficulty":3,"kind":"match","stem":"문장과 그 문장이 알려 주는 것을 이으세요.","pairs":[{"l":"나라는 이미 일본에 빼앗긴 뒤였다","r":"시대 상황"},{"l":"정정화는 혼자 압록강을 건넜다","r":"인물의 행동"},{"l":"기다리기만 해서는 달라지지 않는다고 보았다","r":"그렇게 한 까닭"}],"mis":"K6-1-u1-X11","explanation":["그때가 어떤 때였는지는 시대 상황이에요.","인물이 한 일은 행동이에요.","왜 그렇게 했는지가 까닭이에요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L02_challenge#8','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C9',4,'mc','auto','정정화가 남긴 글에 「자랑보다 함께 걸은 사람들의 이름이 더 많았다」는 것과 이름이 남지 않는 살림일을 스물다섯 해 동안 맡은 것을 함께 볼 때 가장 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u1-X10','K6-1-u1-X05']::text[],false,'{"seq":8,"concept":"K6-1-u1-C9","difficulty":4,"kind":"mc","stem":"정정화가 남긴 글에 「자랑보다 함께 걸은 사람들의 이름이 더 많았다」는 것과 이름이 남지 않는 살림일을 스물다섯 해 동안 맡은 것을 함께 볼 때 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"한두 번이 아니라 끝까지 이어진 태도이므로 함께하는 사람들을 소중히 여기는 마음을 가치로 볼 근거가 된다","correct":true},{"t":"훈장을 받았으므로 명예를 가장 소중히 여겼다","mis":"K6-1-u1-X10"},{"t":"살림일은 나라 일이 아니므로 가치와 상관없다","mis":"K6-1-u1-X05"},{"t":"이름을 적은 것은 한 번뿐이라 가치를 알 수 없다","mis":"K6-1-u1-X10"}],"explanation":["끝까지 이어진 태도에 주목해요.","이름이 남지 않는 일도 소중히 했어요.","함께하는 사람들을 앞에 두었어요."],"asset":{"type":"passage","lines":["그 뒤로 정정화는 국내와 상하이 사이를 여러 차례 오갔다.","조사를 받은 적도 있었지만 그는 다시 길을 나섰다.","그가 모아 온 돈은 임시정부의 살림과 활동에 쓰였다.","임시정부가 일본의 추격을 피해 여러 도시로 옮겨 다닐 때에도","그는 끼니를 마련하고 아픈 사람을 돌보았다. 이름이 남는 일은 아니었다.","광복이 될 때까지 스물다섯 해 동안 그는 그 일을 놓지 않았다.","그가 남긴 글에는 자랑보다 함께 걸은 사람들의 이름이 더 많았다."],"title":"전기문 「강을 건넌 사람」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L02_challenge#9','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C10',4,'essay','teacher','「인물이 처한 상황 → 말과 행동 → 그렇게 한 까닭」의 차례로 정정화가 추구한 가치를 한 가지 파악해 쓰세요. 연도 같은 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u1-C10","difficulty":4,"kind":"essay","stem":"「인물이 처한 상황 → 말과 행동 → 그렇게 한 까닭」의 차례로 정정화가 추구한 가치를 한 가지 파악해 쓰세요. 연도 같은 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 처한 상황 — 나라를 빼앗겨 감시가 심했고 여자가 홀로 먼 길을 떠나기 어려웠으며, 국경을 넘다 붙잡히면 목숨이 위험했다. 말과 행동 — 「제가 다녀오겠습니다.」 하고 나서서 국내와 상하이를 여러 차례 오가며 돈을 모아 왔고, 조사를 받고도 다시 길을 나섰다. 까닭 — 기다리기만 해서는 아무것도 달라지지 않는다고 보았기 때문이다. 그래서 나는 정정화가 「책임」을 추구했다고 생각한다.","scoring_points":["처한 상황을 썼는가","말과 행동을 글에서 찾아 썼는가","까닭을 들어 가치를 파악했는가"]},"explanation":["그때가 어떤 때였는지 먼저 써요.","글에 나온 말과 행동을 찾아요.","까닭과 이어 가치를 정해요."]}'::jsonb),
('g6_1_kor_u1_L02_challenge#10','kor',6,1,'u1','L02','g6_1_kor_u1_L02_challenge','lesson_challenge','K6-1-u1-C8',4,'essay','teacher','「같은 말도 때에 따라 무게가 다르다.」는 것을 「제가 다녀오겠습니다.」라는 말로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u1-C8","difficulty":4,"kind":"essay","stem":"「같은 말도 때에 따라 무게가 다르다.」는 것을 「제가 다녀오겠습니다.」라는 말로 설명하세요.","answer_guide":{"answer":"예: 시대를 빼고 보면 「제가 다녀오겠습니다.」는 그냥 심부름을 맡겠다는 가벼운 말로 보인다. 그러나 그때는 나라를 빼앗겨 감시가 심했고 국경을 넘다 붙잡히면 목숨이 위험했다. 이 시대 상황을 넣고 보면 그 말은 목숨을 걸고 위험한 길에 나서겠다는 무거운 말이 된다. 그래서 인물의 말과 행동은 시대 상황과 관련지어 읽어야 그 안에 담긴 마음이 드러난다.","scoring_points":["시대를 뺀 뜻을 썼는가","시대 상황을 넣은 뜻을 썼는가","관련지어 읽어야 하는 까닭을 썼는가"]},"explanation":["시대를 빼고 읽어 봐요.","시대를 넣고 읽어 봐요.","무게가 어떻게 달라졌는지 써요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L04_basic#1','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C12',1,'match','auto','옹기를 만드는 일과 관련된 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u1-C12","difficulty":1,"kind":"match","stem":"옹기를 만드는 일과 관련된 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"수비","r":"흙을 물에 풀어 고운 흙만 걸러 내는 일"},{"l":"잿물","r":"그릇 겉에 입혀 윤이 나게 하는 물"},{"l":"가마","r":"그릇을 넣고 불을 때어 구워 내는 시설"}],"mis":"K6-1-u1-X14","explanation":["수비는 흙을 고르는 일이에요.","잿물은 그릇 겉에 입혀요.","가마에서 불을 때어 구워요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#2','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C12',1,'mc','auto','「옹기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X14']::text[],false,'{"seq":2,"concept":"K6-1-u1-C12","difficulty":1,"kind":"mc","stem":"「옹기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"간장 · 김치 따위를 담는 질그릇","correct":true},{"t":"그릇을 굽는 시설","mis":"K6-1-u1-X14"},{"t":"그릇 겉에 입히는 물","mis":"K6-1-u1-X14"},{"t":"흙을 거르는 일","mis":"K6-1-u1-X14"}],"explanation":["그릇을 굽는 시설은 가마예요.","겉에 입히는 물은 잿물이에요.","옹기는 장을 담는 질그릇이에요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#3','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C14',1,'mc','auto','만복과 연수의 처지로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":3,"concept":"K6-1-u1-C14","difficulty":1,"kind":"mc","stem":"만복과 연수의 처지로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 집이 가난했고 같은 일을 맡았다","correct":true},{"t":"둘 다 옹기점 주인의 아들이었다","mis":"K6-1-u1-X09"},{"t":"둘 다 첫날부터 그릇을 빚었다","mis":"K6-1-u1-X09"},{"t":"만복만 가난했다","mis":"K6-1-u1-X09"}],"explanation":["같은 해에 들어왔어요.","둘 다 집이 가난했어요.","가마 어른은 둘에게 똑같이 수비를 맡겼어요."],"asset":{"type":"passage","lines":["만복과 연수는 같은 해에 옹기점에 들어왔다. 둘 다 집이 가난했다.","가마 어른은 두 아이에게 똑같이 수비를 맡겼다.","그날 걸러 낸 흙은 이듬해에나 그릇이 되었다.","반년이 지나도 흙만 거르자 만복은 조바심이 났다.","「흙 고르는 일이야 사람을 사서 시키면 그만 아닙니까.","저는 빨리 그릇을 빚어 팔고, 어머니께 기와집을 지어 드리고 싶습니다.」","연수는 걸러 낸 흙을 손끝으로 문질러 보는 버릇이 있었다.","어제 흙보다 오늘 흙이 곱게 걸러졌는지 알아보려는 것이었다."],"title":"이야기 「흙을 고르는 아이」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L04_basic#4','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C13',1,'mc','auto','만복이 옹기점을 떠난 까닭은 무엇인가요?',ARRAY['K6-1-u1-X22']::text[],false,'{"seq":4,"concept":"K6-1-u1-C13","difficulty":1,"kind":"mc","stem":"만복이 옹기점을 떠난 까닭은 무엇인가요?","options":[{"t":"더 빨리 돈을 벌어 어머니를 모시고 싶어서","correct":true},{"t":"가마 어른에게 크게 꾸중을 들어서","mis":"K6-1-u1-X22"},{"t":"옹기 만드는 일을 한 번도 좋아한 적이 없어서","mis":"K6-1-u1-X22"},{"t":"연수와 크게 다투어서","mis":"K6-1-u1-X22"}],"explanation":["만복은 기와집을 지어 드리고 싶다고 했어요.","되파는 일이 더 빨리 돈이 된다고 했어요.","꾸중이나 다툼은 글에 없어요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L04_basic#5','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C14',2,'ox','auto','같은 곳에서 같은 일을 배우는 두 사람은 추구하는 가치도 반드시 같아요.',ARRAY['K6-1-u1-X16']::text[],false,'{"seq":5,"concept":"K6-1-u1-C14","difficulty":2,"kind":"ox","stem":"같은 곳에서 같은 일을 배우는 두 사람은 추구하는 가치도 반드시 같아요.","answer":"X","reason_options":[{"t":"처지가 같아도 바라보는 곳이 달라 추구하는 가치가 다를 수 있기 때문에","correct":true},{"t":"같은 일을 하면 같은 것을 소중히 여기게 되기 때문에","mis":"K6-1-u1-X16"}],"mis":"K6-1-u1-X16","explanation":["만복과 연수는 처지가 같았어요.","만복은 결과와 앞날을, 연수는 과정과 쓸 사람을 보았어요.","처지가 같아도 가치는 다를 수 있어요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#6','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C14',2,'mc','auto','연수가 날마다 흙을 손끝으로 문질러 본 행동에서 알 수 있는 가치는 무엇인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X12','K6-1-u1-X02']::text[],false,'{"seq":6,"concept":"K6-1-u1-C14","difficulty":2,"kind":"mc","stem":"연수가 날마다 흙을 손끝으로 문질러 본 행동에서 알 수 있는 가치는 무엇인가요?","options":[{"t":"정성 · 끈기","correct":true},{"t":"성취 · 효","mis":"K6-1-u1-X18"},{"t":"명예 · 경쟁","mis":"K6-1-u1-X12"},{"t":"옹기 · 흙","mis":"K6-1-u1-X02"}],"explanation":["어제 흙보다 오늘 흙이 고운지 살폈어요.","날마다 되풀이했어요.","과정을 소중히 하는 정성과 끈기예요."],"asset":{"type":"passage","lines":["만복과 연수는 같은 해에 옹기점에 들어왔다. 둘 다 집이 가난했다.","가마 어른은 두 아이에게 똑같이 수비를 맡겼다.","그날 걸러 낸 흙은 이듬해에나 그릇이 되었다.","반년이 지나도 흙만 거르자 만복은 조바심이 났다.","「흙 고르는 일이야 사람을 사서 시키면 그만 아닙니까.","저는 빨리 그릇을 빚어 팔고, 어머니께 기와집을 지어 드리고 싶습니다.」","연수는 걸러 낸 흙을 손끝으로 문질러 보는 버릇이 있었다.","어제 흙보다 오늘 흙이 곱게 걸러졌는지 알아보려는 것이었다."],"title":"이야기 「흙을 고르는 아이」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L04_basic#7','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C13',2,'mc','auto','「흙을 고르는 아이」에서 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X15']::text[],false,'{"seq":7,"concept":"K6-1-u1-C13","difficulty":2,"kind":"mc","stem":"「흙을 고르는 아이」에서 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"흙 고르는 일을 맡음 → 만복이 조바심을 냄 → 항아리가 갈라진 일 → 만복은 떠나고 연수는 첫 그릇을 빚음","correct":true},{"t":"만복이 떠남 → 흙 고르는 일을 맡음 → 항아리가 갈라진 일 → 만복이 조바심을 냄","mis":"K6-1-u1-X15"},{"t":"연수가 첫 그릇을 빚음 → 만복이 조바심을 냄 → 흙 고르는 일을 맡음 → 항아리가 갈라진 일","mis":"K6-1-u1-X15"},{"t":"항아리가 갈라진 일 → 연수가 첫 그릇을 빚음 → 만복이 떠남 → 흙 고르는 일을 맡음","mis":"K6-1-u1-X15"}],"explanation":["처음에 둘은 흙 고르는 일을 맡았어요.","흙만 거르는 날이 길어지자 만복이 조바심을 냈어요.","가을에 만복은 떠나고 연수는 남았어요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#8','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C15',2,'ox','auto','「연수가 옳고 만복이 잘못했다.」라고 판단하며 읽는 것이 알맞아요.',ARRAY['K6-1-u1-X17']::text[],false,'{"seq":8,"concept":"K6-1-u1-C15","difficulty":2,"kind":"ox","stem":"「연수가 옳고 만복이 잘못했다.」라고 판단하며 읽는 것이 알맞아요.","answer":"X","reason_options":[{"t":"옳고 그름으로 가르면 만복이 돈을 앞에 둔 까닭(어머니를 빨리 모시려는 마음)이 보이지 않기 때문에","correct":true},{"t":"돈을 좇는 것은 언제나 나쁜 가치이기 때문에","mis":"K6-1-u1-X17"}],"mis":"K6-1-u1-X17","explanation":["좋다 · 나쁘다로 가르지 않아요.","만복에게도 까닭이 있어요.","처지가 같은데 왜 다른 길을 골랐는지 물어요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#9','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C17',2,'mc','auto','연수의 가치를 알아보기에 가장 알맞은 질문은 어느 것인가요?',ARRAY['K6-1-u1-X19']::text[],false,'{"seq":9,"concept":"K6-1-u1-C17","difficulty":2,"kind":"mc","stem":"연수의 가치를 알아보기에 가장 알맞은 질문은 어느 것인가요?","options":[{"t":"「첫 그릇을 보고 무거운 마음이 든 까닭은 무엇인가요?」","correct":true},{"t":"「옹기점에 들어온 지 몇 해가 되었나요?」","mis":"K6-1-u1-X19"},{"t":"「옹기점에서 만드는 그릇은 무엇으로 만드나요?」","mis":"K6-1-u1-X19"},{"t":"「가마 어른의 이름은 무엇인가요?」","mis":"K6-1-u1-X19"}],"explanation":["글을 보면 바로 답이 나오는 질문은 가치를 알려 주지 못해요.","까닭과 마음을 물어요.","무거운 마음의 까닭에 가치가 담겨요."]}'::jsonb),
('g6_1_kor_u1_L04_basic#10','kor',6,1,'u1','L04','g6_1_kor_u1_L04_basic','lesson_basic','K6-1-u1-C16',3,'mc','auto','만복과 연수가 모두 「효」를 소중히 여긴다고 할 때, 두 사람의 효가 어떻게 다른지 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X03']::text[],false,'{"seq":10,"concept":"K6-1-u1-C16","difficulty":3,"kind":"mc","stem":"만복과 연수가 모두 「효」를 소중히 여긴다고 할 때, 두 사람의 효가 어떻게 다른지 알맞게 말한 것은 어느 것인가요?","options":[{"t":"만복은 빨리 돈을 벌어 집을 지어 드리는 효, 연수는 어머니가 부끄럽지 않을 만큼 한 가지 일을 익히는 효","correct":true},{"t":"두 사람 모두 효를 추구하므로 효의 뜻도 똑같다","mis":"K6-1-u1-X18"},{"t":"만복의 효가 연수의 효보다 더 훌륭하다","mis":"K6-1-u1-X03"},{"t":"연수는 어머니 이야기를 하지 않았으므로 효와 상관없다","mis":"K6-1-u1-X18"}],"explanation":["가치 낱말이 같아도 실천하는 모습은 달라요.","어떤 상황에서 어떻게 실천하는지 함께 봐요.","그래야 그 가치의 뜻이 보여요."]}'::jsonb),
('g6_1_kor_u1_L04_challenge#1','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C12',2,'mc','auto','「그릇은 빚는 날이 아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」에서 「흙을 거르는 날」에 하는 일은 무엇인가요?',ARRAY['K6-1-u1-X14']::text[],false,'{"seq":1,"concept":"K6-1-u1-C12","difficulty":2,"kind":"mc","stem":"「그릇은 빚는 날이 아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」에서 「흙을 거르는 날」에 하는 일은 무엇인가요?","options":[{"t":"수비","correct":true},{"t":"잿물 입히기","mis":"K6-1-u1-X14"},{"t":"가마에 불 때기","mis":"K6-1-u1-X14"},{"t":"물레로 빚기","mis":"K6-1-u1-X14"}],"explanation":["흙을 물에 풀어 고운 흙만 걸러요.","이 일을 수비라고 해요.","가장 먼저 배우는 일이에요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L04_challenge#2','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C15',2,'error','auto','「흙을 고르는 아이」를 읽고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X17','K6-1-u1-X16']::text[],false,'{"seq":2,"concept":"K6-1-u1-C15","difficulty":2,"kind":"error","stem":"「흙을 고르는 아이」를 읽고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"수아 — 「돈을 좇은 만복은 나쁜 가치를 가진 아이야.」","correct":true,"mis_target":"K6-1-u1-X17"},{"t":"건우 — 「만복은 어머니를 빨리 모시고 싶었구나.」","mis":"K6-1-u1-X17"},{"t":"채린 — 「처지가 같은데 왜 둘이 다른 길을 골랐을까?」","mis":"K6-1-u1-X16"}],"explanation":["건우와 채린은 까닭을 살폈어요.","수아는 만복을 나쁘다고 갈랐어요.","옳고 그름이 아니라 다른 까닭을 봐요."]}'::jsonb),
('g6_1_kor_u1_L04_challenge#3','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C14',3,'mc','auto','두 사람이 바라보는 곳을 알맞게 비교한 것은 어느 것인가요?',ARRAY['K6-1-u1-X16','K6-1-u1-X02']::text[],false,'{"seq":3,"concept":"K6-1-u1-C14","difficulty":3,"kind":"mc","stem":"두 사람이 바라보는 곳을 알맞게 비교한 것은 어느 것인가요?","options":[{"t":"만복은 결과와 앞날을, 연수는 과정과 그릇을 쓸 사람을 바라본다","correct":true},{"t":"만복은 과정을, 연수는 돈을 바라본다","mis":"K6-1-u1-X16"},{"t":"두 사람 모두 기와집을 바라본다","mis":"K6-1-u1-X16"},{"t":"만복은 흙을, 연수는 가마를 바라본다","mis":"K6-1-u1-X02"}],"explanation":["만복은 빨리 그릇을 팔고 싶어 했어요.","연수는 날마다 흙을 살폈어요.","첫 그릇 앞에서 쓸 사람을 생각했어요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L04_challenge#4','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C14',3,'mc','auto','연수가 첫 그릇 앞에서 기쁨보다 무거운 것을 먼저 느낀 까닭에서 알 수 있는 가치는 무엇인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X21','K6-1-u1-X22']::text[],false,'{"seq":4,"concept":"K6-1-u1-C14","difficulty":3,"kind":"mc","stem":"연수가 첫 그릇 앞에서 기쁨보다 무거운 것을 먼저 느낀 까닭에서 알 수 있는 가치는 무엇인가요?","options":[{"t":"그릇을 쓸 사람을 생각하는 책임","correct":true},{"t":"남보다 빨리 그릇을 빚으려는 경쟁","mis":"K6-1-u1-X18"},{"t":"그릇이 비뚤어 부끄러운 마음","mis":"K6-1-u1-X21"},{"t":"가마 어른에게 칭찬받으려는 마음","mis":"K6-1-u1-X22"}],"explanation":["누군가의 집에서 한 해 내내 장을 품을 그릇이에요.","쓸 사람을 생각했어요.","그 마음 아래에 책임이 있어요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L04_challenge#5','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C17',3,'mc','auto','만복을 인물 면담할 때 「그릇을 되파는 일을 고른 까닭은 무엇인가요?」라는 질문에 가장 알맞은 답은 어느 것인가요?',ARRAY['K6-1-u1-X20','K6-1-u1-X09','K6-1-u1-X22']::text[],false,'{"seq":5,"concept":"K6-1-u1-C17","difficulty":3,"kind":"mc","stem":"만복을 인물 면담할 때 「그릇을 되파는 일을 고른 까닭은 무엇인가요?」라는 질문에 가장 알맞은 답은 어느 것인가요?","options":[{"t":"「흙만 거르다가는 어머니를 모실 날이 너무 멀어 보였어요. 하루라도 빨리 집을 지어 드리고 싶었어요.」","correct":true},{"t":"「흙 고르는 일도 소중하니 저라면 남았을 거예요.」","mis":"K6-1-u1-X20"},{"t":"「저는 원래 옹기점에 들어온 적이 없어요.」","mis":"K6-1-u1-X09"},{"t":"「연수가 미워서 떠났어요.」","mis":"K6-1-u1-X22"}],"explanation":["면담은 그 인물의 처지에서 답해요.","내 생각이 아니라 만복의 마음으로 답해요.","이야기에 어울리게 답해요."]}'::jsonb),
('g6_1_kor_u1_L04_challenge#6','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C17',3,'ox','auto','인물 면담에서는 내가 평소 소중히 여기는 가치에 맞추어 답하는 것이 좋아요.',ARRAY['K6-1-u1-X20']::text[],false,'{"seq":6,"concept":"K6-1-u1-C17","difficulty":3,"kind":"ox","stem":"인물 면담에서는 내가 평소 소중히 여기는 가치에 맞추어 답하는 것이 좋아요.","answer":"X","reason_options":[{"t":"면담은 그 인물의 처지와 말 · 행동에 어울리게 답하는 활동이기 때문에","correct":true},{"t":"내 생각이 인물보다 옳기 때문에","mis":"K6-1-u1-X20"}],"mis":"K6-1-u1-X20","explanation":["나 대신 인물이 되어 봐요.","인물이 처한 상황을 떠올려요.","그 인물의 처지에서 답해요."]}'::jsonb),
('g6_1_kor_u1_L04_challenge#7','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C14',3,'match','auto','인물의 모습과 추구하는 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u1-C14","difficulty":3,"kind":"match","stem":"인물의 모습과 추구하는 가치를 알맞게 이으세요.","pairs":[{"l":"빨리 돈을 벌어 어머니를 모시려 함","r":"성취 · 효"},{"l":"날마다 흙의 고운 정도를 손끝으로 살핌","r":"정성 · 끈기"},{"l":"첫 그릇 앞에서 무거움을 느낌","r":"책임"}],"mis":"K6-1-u1-X16","explanation":["만복은 성취와 효를 앞에 두었어요.","연수는 날마다 흙을 살폈어요.","첫 그릇 앞에서 쓸 사람을 생각했어요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L04_challenge#8','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C16',4,'mc','auto','「두 사람 다 『끈기』가 있다.」고 할 때, 그 끈기가 어떻게 다르게 실천되는지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X17','K6-1-u1-X03']::text[],false,'{"seq":8,"concept":"K6-1-u1-C16","difficulty":4,"kind":"mc","stem":"「두 사람 다 『끈기』가 있다.」고 할 때, 그 끈기가 어떻게 다르게 실천되는지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"연수의 끈기는 지루한 흙 고르기를 해마다 이어 가는 것이고, 만복의 끈기는 가난을 벗어날 길을 포기하지 않고 새로 찾아 나선 것이다","correct":true},{"t":"끈기라는 낱말이 같으니 두 사람이 한 일도 같다","mis":"K6-1-u1-X18"},{"t":"만복은 떠났으므로 끈기가 전혀 없다","mis":"K6-1-u1-X17"},{"t":"끈기는 오래 한 사람만 가질 수 있으므로 연수의 끈기가 더 훌륭하다","mis":"K6-1-u1-X03"}],"explanation":["같은 가치도 실천하는 모습이 달라요.","떠났다고 끈기가 없다고 단정하지 않아요.","상황 속 실천을 함께 봐요."]}'::jsonb),
('g6_1_kor_u1_L04_challenge#9','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C15',4,'essay','teacher','「처지가 같은 만복과 연수는 왜 서로 다른 길을 골랐을까?」에 대한 내 생각을 두 사람의 말과 행동을 근거로 쓰세요. 누가 옳은지는 가리지 마세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u1-C15","difficulty":4,"kind":"essay","stem":"「처지가 같은 만복과 연수는 왜 서로 다른 길을 골랐을까?」에 대한 내 생각을 두 사람의 말과 행동을 근거로 쓰세요. 누가 옳은지는 가리지 마세요.","answer_guide":{"answer":"예: 만복은 「빨리 그릇을 빚어 팔고 어머니께 기와집을 지어 드리고 싶다」고 했다. 가난한 어머니를 하루라도 빨리 모시고 싶은 마음이 커서 결과와 앞날을 앞에 둔 것 같다. 연수는 날마다 흙을 손끝으로 견주어 보고, 첫 그릇 앞에서 쓸 사람을 생각했다. 연수는 과정과 쓸 사람을 앞에 두었다. 두 사람은 같은 처지였지만 무엇을 먼저 바라보았는지가 달라 다른 길을 고른 것이다.","scoring_points":["만복의 말과 행동을 근거로 들었는가","연수의 말과 행동을 근거로 들었는가","옳고 그름이 아니라 앞에 둔 것의 차이로 설명했는가"]},"explanation":["만복의 말에서 까닭을 찾아요.","연수의 행동에서 까닭을 찾아요.","옳고 그름이 아니라 차이를 써요."],"asset":{"type":"passage","lines":["만복과 연수는 같은 해에 옹기점에 들어왔다. 둘 다 집이 가난했다.","가마 어른은 두 아이에게 똑같이 수비를 맡겼다.","그날 걸러 낸 흙은 이듬해에나 그릇이 되었다.","반년이 지나도 흙만 거르자 만복은 조바심이 났다.","「흙 고르는 일이야 사람을 사서 시키면 그만 아닙니까.","저는 빨리 그릇을 빚어 팔고, 어머니께 기와집을 지어 드리고 싶습니다.」","연수는 걸러 낸 흙을 손끝으로 문질러 보는 버릇이 있었다.","어제 흙보다 오늘 흙이 곱게 걸러졌는지 알아보려는 것이었다."],"title":"이야기 「흙을 고르는 아이」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L04_challenge#10','kor',6,1,'u1','L04','g6_1_kor_u1_L04_challenge','lesson_challenge','K6-1-u1-C17',4,'essay','teacher','만복이나 연수에게 할 질문을 두 가지 만들고, 그 인물이 되어 답해 보세요. 질문은 까닭이나 마음을 묻는 것으로 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u1-C17","difficulty":4,"kind":"essay","stem":"만복이나 연수에게 할 질문을 두 가지 만들고, 그 인물이 되어 답해 보세요. 질문은 까닭이나 마음을 묻는 것으로 만드세요.","answer_guide":{"answer":"예: 연수에게 묻는 질문 — 「만복이 떠날 때 아무 말도 하지 못한 까닭은 무엇인가요?」 연수의 답 — 「만복이 어머니를 얼마나 생각하는지 알아서 붙잡을 수 없었어요. 그래도 마음 한쪽이 허전했어요.」 질문 — 「반년 동안 흙만 거를 때 어떤 생각이 들었나요?」 연수의 답 — 「어제보다 고운 흙을 걸러 내면 그걸로 하루가 뿌듯했어요. 이 흙이 누군가의 장독이 된다고 생각했어요.」","scoring_points":["까닭이나 마음을 묻는 질문을 두 가지 만들었는가","그 인물의 처지에서 답했는가","이야기의 상황과 말 · 행동에 어울리게 답했는가"]},"explanation":["까닭과 마음을 물어요.","그 인물이 되어 답해요.","이야기에 어울리게 지어 답해요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#1','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C18',1,'mc','auto','소진이 윤아에게 화를 낸 까닭은 무엇인가요?',ARRAY['K6-1-u1-X22']::text[],false,'{"seq":1,"concept":"K6-1-u1-C18","difficulty":1,"kind":"mc","stem":"소진이 윤아에게 화를 낸 까닭은 무엇인가요?","options":[{"t":"오래 해 온 것을 쉽게 놓은 듯 보여 받아들이기 어려웠기 때문에","correct":true},{"t":"윤아가 자기보다 상을 더 많이 받아서","mis":"K6-1-u1-X22"},{"t":"윤아가 약속 시간에 늦게 나와서","mis":"K6-1-u1-X22"},{"t":"윤아가 플루트를 빌려주지 않아서","mis":"K6-1-u1-X22"}],"explanation":["소진은 연습을 두 배로 하고 있었어요.","윤아는 오 년을 분 플루트를 놓았어요.","쉽게 놓은 것처럼 보여 받아들이기 어려웠어요."],"asset":{"type":"passage","lines":["소진은 합주부에서 오래 첫째 줄 가운데에서 플루트를 불었다.","올해 들어온 가율의 소리가 곱다는 말이 돌더니 소진은 한 칸 뒤로 밀렸다.","연습을 두 배로 했다. 그래도 이번 달에도 가율이 앞이었다.","졸업한 선배 윤아는 지난겨울 갑자기 플루트를 놓고 팀파니로 옮겼다.","「언니, 왜 플루트 그만뒀어?」 「팀파니가 하고 싶어서.」","소진은 목 안이 뜨거워졌다. 「오 년을 불었잖아. 좀 안 된다고","그렇게 쉽게 놓아 버려?」 소진은 목소리가 커지는 것을 멈출 수 없었다."],"title":"이야기 「한 칸 뒤에서」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L07_basic#2','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C19',1,'mc','auto','윤아가 플루트를 그만두고 팀파니로 옮긴 까닭은 무엇인가요?',ARRAY['K6-1-u1-X23','K6-1-u1-X22','K6-1-u1-X09']::text[],false,'{"seq":2,"concept":"K6-1-u1-C19","difficulty":1,"kind":"mc","stem":"윤아가 플루트를 그만두고 팀파니로 옮긴 까닭은 무엇인가요?","options":[{"t":"할 만큼 해 보았고, 더 하고 싶은 것을 찾았기 때문에","correct":true},{"t":"플루트가 힘들어 금방 포기했기 때문에","mis":"K6-1-u1-X23"},{"t":"소진과 다투었기 때문에","mis":"K6-1-u1-X22"},{"t":"합주부를 아예 그만두려고","mis":"K6-1-u1-X09"}],"explanation":["「할 만큼 해 봐서 아쉽지가 않아.」라고 했어요.","팀파니 소리가 좋다고 했어요.","쉽게 놓은 것이 아니에요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L07_basic#3','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C10',1,'mc','auto','앞 차시에서 정리한, 인물이 추구하는 가치를 파악하는 세 걸음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X11','K6-1-u1-X05']::text[],false,'{"seq":3,"concept":"K6-1-u1-C10","difficulty":1,"kind":"mc","stem":"앞 차시에서 정리한, 인물이 추구하는 가치를 파악하는 세 걸음으로 알맞은 것은 어느 것인가요?","options":[{"t":"처한 상황 → 말과 행동 → 그렇게 한 까닭","correct":true},{"t":"가치 낱말 정하기 → 그에 맞는 장면 찾기","mis":"K6-1-u1-X11"},{"t":"인물의 나이와 직업 → 좋아하는 것","mis":"K6-1-u1-X05"},{"t":"그렇게 한 까닭 → 말과 행동 → 처한 상황","mis":"K6-1-u1-X11"}],"explanation":["앞 차시에서 정리한 세 걸음이에요.","상황을 먼저 봐요.","말과 행동을 살피고 까닭을 생각해요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#4','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C19',1,'match','auto','인물의 말과 드러나는 가치를 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u1-C19","difficulty":1,"kind":"match","stem":"인물의 말과 드러나는 가치를 이으세요.","pairs":[{"l":"「오 년을 불었잖아. 그렇게 쉽게 놓아 버려?」","r":"끈기"},{"l":"「할 만큼 해 봐서 아쉽지가 않아.」","r":"후회 없는 노력"},{"l":"「내가 치면 강당이 같이 울려. 그게 좋아.」","r":"좋아하는 일"}],"mis":"K6-1-u1-X21","explanation":["소진은 쉽게 놓지 않는 것을 소중히 해요.","윤아는 할 만큼 해 보았어요.","좋아하는 일을 할 때 얼굴이 환했어요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#5','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C18',2,'ox','auto','인물의 마음과 인물이 추구하는 가치는 같은 것이에요.',ARRAY['K6-1-u1-X21']::text[],false,'{"seq":5,"concept":"K6-1-u1-C18","difficulty":2,"kind":"ox","stem":"인물의 마음과 인물이 추구하는 가치는 같은 것이에요.","answer":"X","reason_options":[{"t":"마음(화남)과 가치(끈기)는 다르지만 마음을 짐작하면 그 아래의 가치를 찾을 수 있기 때문에","correct":true},{"t":"화를 내는 것 자체가 가치이기 때문에","mis":"K6-1-u1-X21"}],"mis":"K6-1-u1-X21","explanation":["소진은 화가 났어요.","화난 마음 아래에 끈기를 소중히 여기는 것이 있어요.","마음을 짐작해 가치를 찾아요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#6','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C19',2,'mc','auto','소진과 윤아를 비교한 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X23','K6-1-u1-X16','K6-1-u1-X05']::text[],false,'{"seq":6,"concept":"K6-1-u1-C19","difficulty":2,"kind":"mc","stem":"소진과 윤아를 비교한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"두 사람 모두 대충 하지 않았고 무엇을 앞에 두느냐가 달랐다","correct":true},{"t":"윤아는 참을성이 없고 소진이 더 훌륭하다","mis":"K6-1-u1-X23"},{"t":"두 사람은 추구하는 가치가 똑같다","mis":"K6-1-u1-X16"},{"t":"소진은 이기는 것만 생각하는 사람이다","mis":"K6-1-u1-X05"}],"explanation":["소진은 끈기와 도전을, 윤아는 자아실현과 즐거움을 앞에 두었어요.","둘 다 대충 한 사람이 아니에요.","앞에 둔 것이 달랐을 뿐이에요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L07_basic#7','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C20',2,'mc','auto','인물과 자신을 잘 관련지은 말은 어느 것인가요?',ARRAY['K6-1-u1-X24','K6-1-u1-X23']::text[],false,'{"seq":7,"concept":"K6-1-u1-C20","difficulty":2,"kind":"mc","stem":"인물과 자신을 잘 관련지은 말은 어느 것인가요?","options":[{"t":"「나도 줄넘기에서 계속 걸렸을 때 그만둘까 했는데, 소진처럼 한 번 더 해 보기로 했다.」","correct":true},{"t":"「소진은 플루트를 불고 윤아는 팀파니를 친다.」","mis":"K6-1-u1-X24"},{"t":"「윤아는 참을성이 없다. 소진이 더 훌륭하다.」","mis":"K6-1-u1-X23"},{"t":"「이 이야기는 합주부 이야기다.」","mis":"K6-1-u1-X24"}],"explanation":["인물 이야기만 하는 말은 관련짓기가 아니에요.","인물을 평가만 하는 말도 아니에요.","내 경험과 선택을 함께 말해요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#8','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C21',2,'ox','auto','「끈기가 즐거움보다 훌륭한 가치다.」라고 한 줄로 세울 수 있어요.',ARRAY['K6-1-u1-X03']::text[],false,'{"seq":8,"concept":"K6-1-u1-C21","difficulty":2,"kind":"ox","stem":"「끈기가 즐거움보다 훌륭한 가치다.」라고 한 줄로 세울 수 있어요.","answer":"X","reason_options":[{"t":"사람마다 살아온 일이 달라 선택의 까닭도 다르므로 가치에는 등수가 없기 때문에","correct":true},{"t":"오래 버티는 것이 언제나 가장 훌륭하기 때문에","mis":"K6-1-u1-X03"}],"mis":"K6-1-u1-X03","explanation":["가치를 한 줄로 세우지 않아요.","소진과 윤아는 까닭이 달라요.","까닭을 알면 다른 선택도 이해돼요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#9','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C22',2,'mc','auto','가치를 담은 편지에서 가장 중요한 것은 어느 것인가요?',ARRAY['K6-1-u1-X26','K6-1-u1-X24']::text[],false,'{"seq":9,"concept":"K6-1-u1-C22","difficulty":2,"kind":"mc","stem":"가치를 담은 편지에서 가장 중요한 것은 어느 것인가요?","options":[{"t":"인물의 가치와 그에 대한 내 생각의 까닭이 드러나는 것","correct":true},{"t":"편지 형식을 빠짐없이 다 갖추는 것","mis":"K6-1-u1-X26"},{"t":"글씨를 예쁘게 쓰는 것","mis":"K6-1-u1-X26"},{"t":"인물의 이야기를 처음부터 다시 쓰는 것","mis":"K6-1-u1-X24"}],"explanation":["형식을 다 갖추지 않아도 돼요.","이야기를 다시 쓰는 것도 아니에요.","가치와 까닭이 드러나야 해요."]}'::jsonb),
('g6_1_kor_u1_L07_basic#10','kor',6,1,'u1','L07','g6_1_kor_u1_L07_basic','lesson_basic','K6-1-u1-C20',3,'mc','auto','인물의 가치를 나와 견주는 방법의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X23','K6-1-u1-X24','K6-1-u1-X39']::text[],false,'{"seq":10,"concept":"K6-1-u1-C20","difficulty":3,"kind":"mc","stem":"인물의 가치를 나와 견주는 방법의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"비슷한 마음이 들었던 내 경험 떠올리기 → 나와 인물의 선택에서 같은 점과 다른 점 찾기 → 앞으로 추구할 가치와 할 일 정하기","correct":true},{"t":"인물 평가하기 → 더 훌륭한 인물 고르기 → 그 인물 따라 하기","mis":"K6-1-u1-X23"},{"t":"줄거리 다시 쓰기 → 인물 이름 외우기 → 느낌 쓰기","mis":"K6-1-u1-X24"},{"t":"앞으로 할 일 정하기 → 인물 고르기 → 경험은 생략하기","mis":"K6-1-u1-X39"}],"explanation":["내 경험부터 떠올려요.","같은 점과 다른 점을 찾아요.","앞으로 추구할 가치와 할 일을 정해요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#1','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C18',2,'mc','auto','「소진은 목 안이 뜨거워졌다.」에서 짐작할 수 있는 소진의 마음은 무엇인가요?',ARRAY['K6-1-u1-X21','K6-1-u1-X22']::text[],false,'{"seq":1,"concept":"K6-1-u1-C18","difficulty":2,"kind":"mc","stem":"「소진은 목 안이 뜨거워졌다.」에서 짐작할 수 있는 소진의 마음은 무엇인가요?","options":[{"t":"서운하고 받아들이기 어려운 마음","correct":true},{"t":"신나고 기쁜 마음","mis":"K6-1-u1-X21"},{"t":"배가 고픈 마음","mis":"K6-1-u1-X22"},{"t":"졸리고 지친 마음","mis":"K6-1-u1-X22"}],"explanation":["윤아가 대수롭지 않다는 듯 말했어요.","소진은 그때 이유를 못 물을 만큼 서운했어요.","목 안이 뜨거워진 것은 서운하고 받아들이기 어려운 마음이에요."],"asset":{"type":"passage","lines":["소진은 합주부에서 오래 첫째 줄 가운데에서 플루트를 불었다.","올해 들어온 가율의 소리가 곱다는 말이 돌더니 소진은 한 칸 뒤로 밀렸다.","연습을 두 배로 했다. 그래도 이번 달에도 가율이 앞이었다.","졸업한 선배 윤아는 지난겨울 갑자기 플루트를 놓고 팀파니로 옮겼다.","「언니, 왜 플루트 그만뒀어?」 「팀파니가 하고 싶어서.」","소진은 목 안이 뜨거워졌다. 「오 년을 불었잖아. 좀 안 된다고","그렇게 쉽게 놓아 버려?」 소진은 목소리가 커지는 것을 멈출 수 없었다."],"title":"이야기 「한 칸 뒤에서」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L07_challenge#2','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C19',2,'error','auto','소진과 윤아를 비교했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X23','K6-1-u1-X10']::text[],false,'{"seq":2,"concept":"K6-1-u1-C19","difficulty":2,"kind":"error","stem":"소진과 윤아를 비교했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민재 — 「윤아는 힘들면 그만두는 아이라서 팀파니도 곧 그만둘 거야.」","correct":true,"mis_target":"K6-1-u1-X23"},{"t":"세아 — 「윤아는 할 만큼 해 본 뒤 하고 싶은 것으로 옮겼어.」","mis":"K6-1-u1-X23"},{"t":"하준 — 「소진은 밀려도 연습을 두 배로 했어.」","mis":"K6-1-u1-X10"}],"explanation":["세아와 하준은 글에서 근거를 찾았어요.","민재는 윤아를 참을성 없는 아이로 여겼어요.","윤아는 대충 한 사람이 아니에요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#3','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C19',3,'mc','auto','윤아가 「즐거움」을 앞에 둔다는 근거로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":3,"concept":"K6-1-u1-C19","difficulty":3,"kind":"mc","stem":"윤아가 「즐거움」을 앞에 둔다는 근거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"소진에게 상을 양보한다","correct":true},{"t":"「팀파니가 하고 싶어서」라고 말한다","mis":"K6-1-u1-X09"},{"t":"소리가 좋다고 말할 때 얼굴이 환하다","mis":"K6-1-u1-X09"},{"t":"「내가 치면 강당이 같이 울려. 그게 좋아.」라고 말한다","mis":"K6-1-u1-X09"}],"explanation":["근거는 글 안에 있어야 해요.","상을 양보한 일은 글에 없어요.","표정과 말에서 즐거움이 보여요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L07_challenge#4','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C18',3,'mc','auto','소진이 화를 낸 마음 아래에 있는 가치로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X21','K6-1-u1-X22','K6-1-u1-X19']::text[],false,'{"seq":4,"concept":"K6-1-u1-C18","difficulty":3,"kind":"mc","stem":"소진이 화를 낸 마음 아래에 있는 가치로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오래 해 온 것을 쉽게 놓지 않으려는 끈기","correct":true},{"t":"화를 내는 것 자체","mis":"K6-1-u1-X21"},{"t":"윤아보다 상을 많이 받고 싶은 마음","mis":"K6-1-u1-X22"},{"t":"팀파니를 치고 싶은 마음","mis":"K6-1-u1-X19"}],"explanation":["마음은 화남이에요.","그 아래에는 쉽게 놓지 않는 것을 소중히 하는 마음이 있어요.","그것이 끈기예요."],"asset":{"type":"passage","lines":["소진은 합주부에서 오래 첫째 줄 가운데에서 플루트를 불었다.","올해 들어온 가율의 소리가 곱다는 말이 돌더니 소진은 한 칸 뒤로 밀렸다.","연습을 두 배로 했다. 그래도 이번 달에도 가율이 앞이었다.","졸업한 선배 윤아는 지난겨울 갑자기 플루트를 놓고 팀파니로 옮겼다.","「언니, 왜 플루트 그만뒀어?」 「팀파니가 하고 싶어서.」","소진은 목 안이 뜨거워졌다. 「오 년을 불었잖아. 좀 안 된다고","그렇게 쉽게 놓아 버려?」 소진은 목소리가 커지는 것을 멈출 수 없었다."],"title":"이야기 「한 칸 뒤에서」 앞부분"}}'::jsonb),
('g6_1_kor_u1_L07_challenge#5','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C23',3,'mc','auto','이야기 끝에서 소진의 생각은 어떻게 달라졌나요?',ARRAY['K6-1-u1-X27','K6-1-u1-X09']::text[],false,'{"seq":5,"concept":"K6-1-u1-C23","difficulty":3,"kind":"mc","stem":"이야기 끝에서 소진의 생각은 어떻게 달라졌나요?","options":[{"t":"「나는 왜 부는가」를 스스로 묻고, 아직 그만두고 싶지 않다고 생각했다","correct":true},{"t":"처음부터 끝까지 윤아에게 화가 나 있었다","mis":"K6-1-u1-X27"},{"t":"윤아를 따라 플루트를 그만두었다","mis":"K6-1-u1-X09"},{"t":"가율에게 자리를 돌려 달라고 했다","mis":"K6-1-u1-X09"}],"explanation":["윤아의 물음이 집에 오는 길까지 따라왔어요.","이기려고 부는지, 좋아서 부는지 물었어요.","다음 날 일찍 음악실 문을 열었어요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_L07_challenge#6','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C19',3,'match','auto','인물의 선택과 그 까닭을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u1-C19","difficulty":3,"kind":"match","stem":"인물의 선택과 그 까닭을 이으세요.","pairs":[{"l":"소진 — 플루트를 계속 분다","r":"끝이라고 할 만큼 해 보지 않았다고 느껴서"},{"l":"윤아 — 팀파니로 옮겼다","r":"할 만큼 해 보았고 더 하고 싶은 것을 찾아서"},{"l":"만복 — 옹기점을 떠났다","r":"어머니를 하루라도 빨리 모시고 싶어서"}],"mis":"K6-1-u1-X23","explanation":["소진은 아직 그만두고 싶지 않았어요.","윤아는 아쉽지 않다고 했어요.","만복에게도 까닭이 있어요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#7','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C20',3,'ox','auto','「윤아는 참을성이 없다.」라고 인물을 평가하는 것도 인물과 나를 관련지은 것이에요.',ARRAY['K6-1-u1-X24']::text[],false,'{"seq":7,"concept":"K6-1-u1-C20","difficulty":3,"kind":"ox","stem":"「윤아는 참을성이 없다.」라고 인물을 평가하는 것도 인물과 나를 관련지은 것이에요.","answer":"X","reason_options":[{"t":"관련짓기는 내 경험과 선택을 인물과 견주는 것이기 때문에","correct":true},{"t":"인물을 평가하면 내 생각이 드러나기 때문에","mis":"K6-1-u1-X24"}],"mis":"K6-1-u1-X24","explanation":["평가만 하면 내 경험이 없어요.","내 경험을 떠올려요.","내 선택과 인물의 선택을 견주어요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#8','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C22',4,'mc','auto','인물이 되어 나에게 쓰는 편지로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X26','K6-1-u1-X25','K6-1-u1-X24']::text[],false,'{"seq":8,"concept":"K6-1-u1-C22","difficulty":4,"kind":"mc","stem":"인물이 되어 나에게 쓰는 편지로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 윤아야. 너도 하고 싶은 걸 찾았을 때 망설였지? 할 만큼 해 봤다면 옮겨 가도 괜찮아. 이번 주엔 네가 진짜 좋아하는 걸 하나 적어 봐.」","correct":true},{"t":"「안녕하세요. 저는 윤아입니다. 날씨가 좋네요. 안녕히 계세요.」","mis":"K6-1-u1-X26"},{"t":"「나는 윤아야. 앞으로 열심히 살아.」","mis":"K6-1-u1-X25"},{"t":"「윤아는 플루트를 그만두고 팀파니로 옮겼다.」","mis":"K6-1-u1-X24"}],"explanation":["인사만 있는 편지에는 가치가 없어요.","두루뭉술한 다짐도 아니에요.","가치와 까닭, 할 일이 담겨야 해요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#9','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C20',4,'essay','teacher','소진과 윤아 가운데 나와 비슷한 가치를 추구하는 인물을 고르고, 비슷한 마음이 들었던 내 경험과 그때의 선택을 들어 같은 점과 다른 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u1-C20","difficulty":4,"kind":"essay","stem":"소진과 윤아 가운데 나와 비슷한 가치를 추구하는 인물을 고르고, 비슷한 마음이 들었던 내 경험과 그때의 선택을 들어 같은 점과 다른 점을 쓰세요.","answer_guide":{"answer":"예: 나는 소진과 비슷하다. 나도 피아노 대회에서 친구에게 밀려 속상했던 적이 있는데, 그때 그만두지 않고 연습 시간을 늘렸다. 소진처럼 쉽게 놓고 싶지 않았다는 점이 같다. 다른 점은 소진은 「나는 왜 부는가」를 스스로 물었지만, 나는 이기는 것만 생각했다는 점이다. 앞으로는 좋아서 치는 마음도 함께 지키고 싶다.","scoring_points":["인물 하나를 골랐는가","비슷한 마음이 들었던 내 경험과 선택을 썼는가","같은 점과 다른 점을 모두 썼는가"]},"explanation":["나와 비슷한 인물을 골라요.","내 경험과 선택을 떠올려요.","같은 점과 다른 점을 견주어요."]}'::jsonb),
('g6_1_kor_u1_L07_challenge#10','kor',6,1,'u1','L07','g6_1_kor_u1_L07_challenge','lesson_challenge','K6-1-u1-C21',4,'essay','teacher','「가치에는 등수가 없다.」는 것을 소진과 윤아가 선택한 까닭을 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u1-C21","difficulty":4,"kind":"essay","stem":"「가치에는 등수가 없다.」는 것을 소진과 윤아가 선택한 까닭을 들어 설명하세요.","answer_guide":{"answer":"예: 소진은 끝이라고 할 만큼 해 보지 않았다고 느껴 플루트를 계속 분다. 윤아는 할 만큼 해 보았고 더 하고 싶은 것을 찾아 팀파니로 옮겼다. 두 사람 모두 대충 하지 않았고, 살아온 일과 선택의 까닭이 다를 뿐이다. 그러므로 끈기가 즐거움보다 훌륭하다고 한 줄로 세울 수 없다. 까닭을 알면 나와 다른 선택도 이해할 수 있다.","scoring_points":["소진의 선택과 까닭을 썼는가","윤아의 선택과 까닭을 썼는가","까닭이 다를 뿐 등수가 없다고 설명했는가"]},"explanation":["소진의 까닭을 찾아요.","윤아의 까닭을 찾아요.","등수 대신 까닭을 봐요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#1','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C23',1,'mc','auto','「고치는 손」 처음에 진아는 할아버지의 간판을 어떻게 느꼈나요?',ARRAY['K6-1-u1-X27']::text[],false,'{"seq":1,"concept":"K6-1-u1-C23","difficulty":1,"kind":"mc","stem":"「고치는 손」 처음에 진아는 할아버지의 간판을 어떻게 느꼈나요?","options":[{"t":"조금 부끄러웠다","correct":true},{"t":"아주 자랑스러웠다","mis":"K6-1-u1-X27"},{"t":"아무 느낌이 없었다","mis":"K6-1-u1-X27"},{"t":"무서웠다","mis":"K6-1-u1-X27"}],"explanation":["고치는 값이 새로 사는 값보다 비쌀 때가 많았어요.","친구들은 고장 나면 새것을 샀어요.","그래서 간판이 조금 부끄러웠어요."],"asset":{"type":"passage","lines":["할아버지는 골목 끝에서 「무엇이든 고칩니다」 수선집을 한다.","나는 그 간판이 조금 부끄럽다. 고치는 값이 새로 사는 값보다 비쌀 때가 많다.","토요일마다 가게를 지키다 이름표 뒷면에 적힌 글씨를 보았다.","낡은 손목시계에는 「아버지 것. 소리만 나면 됩니다.」","부러진 우산에는 「첫 출근 날 산 것.」","나는 손님들이 왜 굳이 여기까지 오는지 조금 알 것 같았다."],"title":"이야기 「고치는 손」 앞부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_basic#2','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C12',1,'match','auto','「고치는 손」에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u1-C12","difficulty":1,"kind":"match","stem":"「고치는 손」에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"수선","r":"낡거나 헌 물건을 고침"},{"l":"부품","r":"기계를 이루는 낱낱의 조각"},{"l":"고집","r":"자기 생각을 굽히지 않음"}],"mis":"K6-1-u1-X14","explanation":["수선집은 물건을 고치는 곳이에요.","부품은 기계의 조각이에요.","고집은 생각을 굽히지 않는 거예요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#3','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C24',1,'mc','auto','할아버지가 추구하는 가치로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X32','K6-1-u1-X05']::text[],false,'{"seq":3,"concept":"K6-1-u1-C24","difficulty":1,"kind":"mc","stem":"할아버지가 추구하는 가치로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물건에 담긴 시간과 마음을 지키려는 정성","correct":true},{"t":"무엇이든 고쳐서 돈을 많이 벌려는 마음","mis":"K6-1-u1-X32"},{"t":"새 물건은 무조건 사지 말자는 생각","mis":"K6-1-u1-X32"},{"t":"돋보기를 잘 쓰는 솜씨","mis":"K6-1-u1-X05"}],"explanation":["「시계를 고친 게 아니라 시간을 고친 거다.」","손해가 되면 새로 사라고도 했어요.","물건에 담긴 시간과 마음을 지켜요."],"asset":{"type":"passage","lines":["어떤 날은 할아버지가 고치지 않고 돌려보냈다.","「고쳐도 오래 못 씁니다. 값도 새것과 비슷해요. 새로 사시는 게 낫겠습니다.」","「고치는 게 늘 옳은 건 아니야. 손님한테 손해가 되면 그건 고집이지 정성이 아니다.」","겨울이 오기 전, 나는 돌아가신 할머니가 쓰던 탁상시계를 들고 갔다.","할아버지가 아주 작은 나사 하나를 갈아 끼우자 시계가 다시 돌았다.","「이건 시계를 고친 게 아니라 시간을 고친 거다.」","나는 그날 간판을 다시 보았다. 이제는 부끄럽지 않았다."],"title":"이야기 「고치는 손」 뒷부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_basic#4','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C26',1,'mc','auto','독서 감상문에 넣을 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u1-X29']::text[],false,'{"seq":4,"concept":"K6-1-u1-C26","difficulty":1,"kind":"mc","stem":"독서 감상문에 넣을 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"처음부터 끝까지 빠짐없이 옮겨 적은 줄거리","correct":true},{"t":"인물이 추구하는 가치와 그 근거가 된 장면","mis":"K6-1-u1-X29"},{"t":"그 가치에 대한 내 생각과 떠오른 내 경험","mis":"K6-1-u1-X29"},{"t":"앞으로 추구하고 싶은 가치와 실천할 일","mis":"K6-1-u1-X29"}],"explanation":["줄거리는 간단히만 써요.","가치와 근거 장면을 넣어요.","내 생각 · 경험 · 실천할 일을 넣어요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#5','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C23',2,'mc','auto','진아가 「손님들이 왜 굳이 여기까지 오는지 조금 알 것 같았다」고 생각하게 된 까닭은 무엇인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":5,"concept":"K6-1-u1-C23","difficulty":2,"kind":"mc","stem":"진아가 「손님들이 왜 굳이 여기까지 오는지 조금 알 것 같았다」고 생각하게 된 까닭은 무엇인가요?","options":[{"t":"이름표 뒷면에 적힌 손님들의 사연을 보았기 때문에","correct":true},{"t":"할아버지가 상을 받았기 때문에","mis":"K6-1-u1-X09"},{"t":"친구들이 수선집을 칭찬했기 때문에","mis":"K6-1-u1-X09"},{"t":"수선 값이 아주 쌌기 때문에","mis":"K6-1-u1-X09"}],"explanation":["「아버지 것. 소리만 나면 됩니다.」","「첫 출근 날 산 것.」","물건마다 손님의 마음이 담겨 있었어요."],"asset":{"type":"passage","lines":["할아버지는 골목 끝에서 「무엇이든 고칩니다」 수선집을 한다.","나는 그 간판이 조금 부끄럽다. 고치는 값이 새로 사는 값보다 비쌀 때가 많다.","토요일마다 가게를 지키다 이름표 뒷면에 적힌 글씨를 보았다.","낡은 손목시계에는 「아버지 것. 소리만 나면 됩니다.」","부러진 우산에는 「첫 출근 날 산 것.」","나는 손님들이 왜 굳이 여기까지 오는지 조금 알 것 같았다."],"title":"이야기 「고치는 손」 앞부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_basic#6','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C24',2,'ox','auto','같은 이야기를 읽고도 할아버지의 가치에 대한 판단이 갈릴 수 있어요.',ARRAY['K6-1-u1-X12']::text[],false,'{"seq":6,"concept":"K6-1-u1-C24","difficulty":2,"kind":"ox","stem":"같은 이야기를 읽고도 할아버지의 가치에 대한 판단이 갈릴 수 있어요.","answer":"O","reason_options":[{"t":"두 판단 모두 글에서 근거를 댈 수 있으면 좋은 답이기 때문에","correct":true},{"t":"판단이 갈리면 둘 다 틀린 것이기 때문에","mis":"K6-1-u1-X12"}],"mis":"K6-1-u1-X12","explanation":["「옛것을 지나치게 붙잡는다」 — 값이 새것과 비슷하다는 근거","「고집이 아니라 정성이다」 — 돌려보낸 장면이 근거","가치에는 위아래가 없고 근거가 중요해요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#7','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C25',2,'ox','auto','「물건을 아끼는 것이 좋다.」는 가치를 고르는 일에는 아무런 어려움도 따르지 않아요.',ARRAY['K6-1-u1-X28']::text[],false,'{"seq":7,"concept":"K6-1-u1-C25","difficulty":2,"kind":"ox","stem":"「물건을 아끼는 것이 좋다.」는 가치를 고르는 일에는 아무런 어려움도 따르지 않아요.","answer":"X","reason_options":[{"t":"실제로는 시간이 더 들고 값이 더 들고 기다려야 하는 어려움까지 고르는 일이기 때문에","correct":true},{"t":"좋은 가치는 언제나 쉽게 지킬 수 있기 때문에","mis":"K6-1-u1-X28"}],"mis":"K6-1-u1-X28","explanation":["말하기는 쉬워요.","실제로는 시간 · 값 · 기다림이 따라요.","가치를 고르면 그 어려움까지 골라요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#8','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C26',2,'mc','auto','독서 감상문에 더 알맞은 글은 어느 것인가요?',ARRAY['K6-1-u1-X29','K6-1-u1-X30']::text[],false,'{"seq":8,"concept":"K6-1-u1-C26","difficulty":2,"kind":"mc","stem":"독서 감상문에 더 알맞은 글은 어느 것인가요?","options":[{"t":"「할아버지가 지킨 것은 물건이 아니라 시간이었다. 나도 낡은 필통을 버리지 못하는 까닭을 알 것 같다.」","correct":true},{"t":"「진아의 할아버지는 수선집을 한다. 시계와 우산을 고친다. 진아는 토요일에 가게를 지킨다.」","mis":"K6-1-u1-X29"},{"t":"「재미있었다. 정말 좋은 이야기였다. 다른 사람도 읽으면 좋겠다.」","mis":"K6-1-u1-X30"},{"t":"「표지가 예뻤고 책이 얇아서 금방 읽었다.」","mis":"K6-1-u1-X30"}],"explanation":["줄거리만 있는 글은 감상문이라 하기 어려워요.","막연한 느낌만으로는 부족해요.","가치와 내 경험이 함께 드러나야 해요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#9','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C26',2,'ox','auto','독서 감상문은 편지나 그림, 만화 형식으로 써도 돼요.',ARRAY['K6-1-u1-X31']::text[],false,'{"seq":9,"concept":"K6-1-u1-C26","difficulty":2,"kind":"ox","stem":"독서 감상문은 편지나 그림, 만화 형식으로 써도 돼요.","answer":"O","reason_options":[{"t":"형식보다 가치에 대한 내 생각이 드러나는 것이 중요하기 때문에","correct":true},{"t":"감상문은 반드시 줄글로만 써야 하기 때문에","mis":"K6-1-u1-X31"}],"mis":"K6-1-u1-X31","explanation":["형식은 자유예요.","줄글 · 편지 · 그림이나 만화 가운데 골라요.","가치에 대한 내 생각이 드러나야 해요."]}'::jsonb),
('g6_1_kor_u1_L09_basic#10','kor',6,1,'u1','L09','g6_1_kor_u1_L09_basic','lesson_basic','K6-1-u1-C27',3,'mc','auto','친구가 나와 다른 가치를 말했을 때 하기에 가장 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u1-X04','K6-1-u1-X03']::text[],false,'{"seq":10,"concept":"K6-1-u1-C27","difficulty":3,"kind":"mc","stem":"친구가 나와 다른 가치를 말했을 때 하기에 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「어느 장면을 보고 그렇게 생각했어?」","correct":true},{"t":"「그건 틀렸어.」","mis":"K6-1-u1-X04"},{"t":"「내 생각이 더 맞아.」","mis":"K6-1-u1-X03"},{"t":"「그런 생각은 하면 안 돼.」","mis":"K6-1-u1-X04"}],"explanation":["같은 작품도 생각은 서로 달라요.","틀렸다고 하지 않아요.","근거가 된 장면을 물어요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#1','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C23',2,'mc','auto','진아의 생각이 바뀐 흐름으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X27','K6-1-u1-X15']::text[],false,'{"seq":1,"concept":"K6-1-u1-C23","difficulty":2,"kind":"mc","stem":"진아의 생각이 바뀐 흐름으로 알맞은 것은 어느 것인가요?","options":[{"t":"간판이 부끄러움 → 이름표의 사연으로 손님의 마음을 앎 → 돌려보내는 할아버지에 놀람 → 시계가 돌자 부끄럽지 않음","correct":true},{"t":"처음부터 끝까지 간판이 부끄러움","mis":"K6-1-u1-X27"},{"t":"간판이 자랑스러움 → 부끄러움 → 수선집이 문을 닫음","mis":"K6-1-u1-X15"},{"t":"시계가 돎 → 이름표를 봄 → 간판이 부끄러움","mis":"K6-1-u1-X15"}],"explanation":["생각은 한곳에 머물지 않아요.","무엇을 보고 바뀌었는지 따라가요.","마지막에는 부끄럽지 않았어요."],"asset":{"type":"passage","lines":["어떤 날은 할아버지가 고치지 않고 돌려보냈다.","「고쳐도 오래 못 씁니다. 값도 새것과 비슷해요. 새로 사시는 게 낫겠습니다.」","「고치는 게 늘 옳은 건 아니야. 손님한테 손해가 되면 그건 고집이지 정성이 아니다.」","겨울이 오기 전, 나는 돌아가신 할머니가 쓰던 탁상시계를 들고 갔다.","할아버지가 아주 작은 나사 하나를 갈아 끼우자 시계가 다시 돌았다.","「이건 시계를 고친 게 아니라 시간을 고친 거다.」","나는 그날 간판을 다시 보았다. 이제는 부끄럽지 않았다."],"title":"이야기 「고치는 손」 뒷부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_challenge#2','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C24',2,'error','auto','「고치는 손」에 대한 판단을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X32','K6-1-u1-X12']::text[],false,'{"seq":2,"concept":"K6-1-u1-C24","difficulty":2,"kind":"error","stem":"「고치는 손」에 대한 판단을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태린 — 「할아버지는 무엇이든 고치는 고집쟁이야. 돈만 생각해.」","correct":true,"mis_target":"K6-1-u1-X32"},{"t":"윤서 — 「할아버지는 지나치게 옛것을 붙잡는 것 같아. 고치는 값이 새것과 비슷하다고 했잖아.」","mis":"K6-1-u1-X12"},{"t":"도경 — 「손해가 될 때는 새로 사라고 돌려보냈으니 고집이 아니라 정성이야.」","mis":"K6-1-u1-X12"}],"explanation":["윤서와 도경은 다른 판단이지만 둘 다 근거가 있어요.","태린은 돌려보낸 장면을 놓쳤어요.","다른 장면도 살펴야 해요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#3','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C24',3,'mc','auto','「할아버지는 고집이 아니라 정성이다.」라는 판단의 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X32','K6-1-u1-X09','K6-1-u1-X12']::text[],false,'{"seq":3,"concept":"K6-1-u1-C24","difficulty":3,"kind":"mc","stem":"「할아버지는 고집이 아니라 정성이다.」라는 판단의 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손님에게 손해가 될 때에는 고치지 않고 새로 사라고 돌려보낸 장면","correct":true},{"t":"간판에 「무엇이든 고칩니다」라고 적힌 것","mis":"K6-1-u1-X32"},{"t":"진아가 토요일마다 가게를 지킨 것","mis":"K6-1-u1-X09"},{"t":"고치는 값이 새것보다 비쌀 때가 많은 것","mis":"K6-1-u1-X12"}],"explanation":["간판만 보면 무엇이든 고치는 것 같아요.","그런데 돌려보낸 장면이 있어요.","손님을 생각하는 정성이 보여요."],"asset":{"type":"passage","lines":["어떤 날은 할아버지가 고치지 않고 돌려보냈다.","「고쳐도 오래 못 씁니다. 값도 새것과 비슷해요. 새로 사시는 게 낫겠습니다.」","「고치는 게 늘 옳은 건 아니야. 손님한테 손해가 되면 그건 고집이지 정성이 아니다.」","겨울이 오기 전, 나는 돌아가신 할머니가 쓰던 탁상시계를 들고 갔다.","할아버지가 아주 작은 나사 하나를 갈아 끼우자 시계가 다시 돌았다.","「이건 시계를 고친 게 아니라 시간을 고친 거다.」","나는 그날 간판을 다시 보았다. 이제는 부끄럽지 않았다."],"title":"이야기 「고치는 손」 뒷부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_challenge#4','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C25',3,'mc','auto','「낡은 물건을 고칠까, 새로 살까」를 고민할 때 이 단원에서 배운 대로 생각한 것은 어느 것인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X28']::text[],false,'{"seq":4,"concept":"K6-1-u1-C25","difficulty":3,"kind":"mc","stem":"「낡은 물건을 고칠까, 새로 살까」를 고민할 때 이 단원에서 배운 대로 생각한 것은 어느 것인가요?","options":[{"t":"어떤 때에는 고치고 어떤 때에는 새로 사는지 까닭과 함께 정하고, 그 선택에 드는 시간 · 값까지 생각한다","correct":true},{"t":"고치는 것이 언제나 옳으므로 무조건 고친다","mis":"K6-1-u1-X03"},{"t":"새로 사는 것이 언제나 편하므로 고민할 필요가 없다","mis":"K6-1-u1-X28"},{"t":"정답이 정해져 있으니 선생님께 여쭈어 따른다","mis":"K6-1-u1-X28"}],"explanation":["정답은 없어요.","까닭이 있으면 돼요.","가치를 고르면 그 어려움까지 골라요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#5','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C23',3,'mc','auto','진아가 이야기 끝에서 간판을 다시 보며 「이제는 부끄럽지 않았다」고 느낀 데에 가장 큰 영향을 준 장면은 어느 것인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":5,"concept":"K6-1-u1-C23","difficulty":3,"kind":"mc","stem":"진아가 이야기 끝에서 간판을 다시 보며 「이제는 부끄럽지 않았다」고 느낀 데에 가장 큰 영향을 준 장면은 어느 것인가요?","options":[{"t":"할머니가 쓰던 시계가 다시 돌고 「시간을 고친 거다」라는 말을 들은 장면","correct":true},{"t":"친구들이 수선집을 칭찬한 장면","mis":"K6-1-u1-X09"},{"t":"할아버지가 상을 받은 장면","mis":"K6-1-u1-X09"},{"t":"간판을 새로 칠한 장면","mis":"K6-1-u1-X09"}],"explanation":["간판은 여전히 조금 낡았어요.","바뀐 것은 진아의 생각이에요.","할머니의 시계가 마음을 바꾸었어요."],"asset":{"type":"passage","lines":["어떤 날은 할아버지가 고치지 않고 돌려보냈다.","「고쳐도 오래 못 씁니다. 값도 새것과 비슷해요. 새로 사시는 게 낫겠습니다.」","「고치는 게 늘 옳은 건 아니야. 손님한테 손해가 되면 그건 고집이지 정성이 아니다.」","겨울이 오기 전, 나는 돌아가신 할머니가 쓰던 탁상시계를 들고 갔다.","할아버지가 아주 작은 나사 하나를 갈아 끼우자 시계가 다시 돌았다.","「이건 시계를 고친 게 아니라 시간을 고친 거다.」","나는 그날 간판을 다시 보았다. 이제는 부끄럽지 않았다."],"title":"이야기 「고치는 손」 뒷부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_L09_challenge#6','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C26',3,'match','auto','독서 감상문의 내용과 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u1-C26","difficulty":3,"kind":"match","stem":"독서 감상문의 내용과 예를 알맞게 이으세요.","pairs":[{"l":"가치와 근거 장면","r":"할아버지는 손해가 될 때 돌려보냈다 — 정성"},{"l":"내 경험","r":"나도 낡은 필통을 버리지 못한다"},{"l":"실천할 일","r":"이번 주에 고장 난 우산을 고쳐 쓴다"}],"mis":"K6-1-u1-X29","explanation":["가치와 근거 장면을 함께 써요.","떠오른 내 경험을 붙여요.","앞으로 실천할 일을 정해요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#7','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C27',3,'ox','auto','감상을 나눌 때 나와 다른 생각을 들으면 「틀렸다」고 바로잡아 주는 것이 좋아요.',ARRAY['K6-1-u1-X04']::text[],false,'{"seq":7,"concept":"K6-1-u1-C27","difficulty":3,"kind":"ox","stem":"감상을 나눌 때 나와 다른 생각을 들으면 「틀렸다」고 바로잡아 주는 것이 좋아요.","answer":"X","reason_options":[{"t":"같은 작품도 생각이 다를 수 있어 근거가 된 장면을 묻고 존중해야 하기 때문에","correct":true},{"t":"감상에는 하나의 정답이 있기 때문에","mis":"K6-1-u1-X04"}],"mis":"K6-1-u1-X04","explanation":["생각은 서로 달라요.","어느 장면을 보고 그렇게 생각했는지 물어요.","예의 바르게 의견을 나눠요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#8','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C26',4,'mc','auto','도윤이가 쓴 감상문 「할아버지는 착하다. 재미있었다.」를 고칠 방향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X29','K6-1-u1-X30','K6-1-u1-X31']::text[],false,'{"seq":8,"concept":"K6-1-u1-C26","difficulty":4,"kind":"mc","stem":"도윤이가 쓴 감상문 「할아버지는 착하다. 재미있었다.」를 고칠 방향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할아버지가 추구한 가치와 근거 장면, 그에 대한 내 생각과 경험을 덧붙인다","correct":true},{"t":"줄거리를 처음부터 끝까지 덧붙인다","mis":"K6-1-u1-X29"},{"t":"「정말 정말 재미있었다」로 느낌을 더 세게 쓴다","mis":"K6-1-u1-X30"},{"t":"줄글은 안 되니 만화로만 다시 그린다","mis":"K6-1-u1-X31"}],"explanation":["줄거리를 늘리는 것이 아니에요.","느낌을 세게 쓰는 것도 아니에요.","가치 · 근거 · 내 생각을 넣어요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#9','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C26',4,'essay','teacher','「고치는 손」을 읽고 할아버지나 진아가 추구하는 가치에 대한 내 생각이 드러나게 짧은 독서 감상문을 쓰세요. 가치와 근거 장면, 내 경험, 앞으로 실천할 일이 들어가야 해요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u1-C26","difficulty":4,"kind":"essay","stem":"「고치는 손」을 읽고 할아버지나 진아가 추구하는 가치에 대한 내 생각이 드러나게 짧은 독서 감상문을 쓰세요. 가치와 근거 장면, 내 경험, 앞으로 실천할 일이 들어가야 해요.","answer_guide":{"answer":"예: 나는 이 이야기에서 할아버지가 「정성」을 소중히 여긴다고 생각했다. 왜냐하면 손님에게 손해가 될 때는 고치지 않고 새로 사라고 돌려보냈고, 할머니의 시계를 고치며 「시간을 고친 거다」라고 했기 때문이다. 나도 할머니가 떠 주신 목도리를 보풀이 많아도 버리지 못한다. 앞으로 내 물건에 담긴 시간을 생각해, 이번 주에 망가진 필통 지퍼를 직접 고쳐 쓰겠다.","scoring_points":["가치와 근거 장면을 썼는가","떠오른 내 경험을 썼는가","앞으로 실천할 일을 썼는가"]},"explanation":["가치와 근거 장면을 먼저 써요.","내 경험을 붙여요.","실천할 일로 마무리해요."]}'::jsonb),
('g6_1_kor_u1_L09_challenge#10','kor',6,1,'u1','L09','g6_1_kor_u1_L09_challenge','lesson_challenge','K6-1-u1-C24',4,'essay','teacher','「할아버지는 지나치게 옛것을 붙잡는다.」와 「할아버지는 고집이 아니라 정성이다.」 가운데 하나를 골라 근거를 들어 쓰고, 다른 판단을 한 친구에게 어떻게 말할지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u1-C24","difficulty":4,"kind":"essay","stem":"「할아버지는 지나치게 옛것을 붙잡는다.」와 「할아버지는 고집이 아니라 정성이다.」 가운데 하나를 골라 근거를 들어 쓰고, 다른 판단을 한 친구에게 어떻게 말할지도 쓰세요.","answer_guide":{"answer":"예: 나는 「고집이 아니라 정성이다」를 골랐다. 할아버지는 손님에게 손해가 될 때 고치지 않고 새로 사라고 돌려보냈기 때문이다. 다른 판단을 한 친구에게는 「너는 고치는 값이 새것과 비슷하다는 데에서 그렇게 본 거구나. 그 근거도 글에 있어. 나는 돌려보낸 장면을 보고 생각이 달라졌어.」라고 말하겠다.","scoring_points":["판단 하나를 골랐는가","글에서 근거를 들었는가","다른 판단을 존중하며 근거 장면을 묻거나 인정하는 말을 썼는가"]},"explanation":["판단을 하나 골라요.","글에서 근거를 들어요.","다른 판단도 근거가 있음을 인정해요."]}'::jsonb),
('g6_1_kor_u1_L12_basic#1','kor',6,1,'u1','L12','g6_1_kor_u1_L12_basic','lesson_basic','K6-1-u1-C28',1,'mc','auto','인물을 소개할 때 소개의 중심은 무엇인가요?',ARRAY['K6-1-u1-X33']::text[],false,'{"seq":1,"concept":"K6-1-u1-C28","difficulty":1,"kind":"mc","stem":"인물을 소개할 때 소개의 중심은 무엇인가요?","options":[{"t":"그 인물이 추구하는 가치","correct":true},{"t":"인물의 이름과 나이","mis":"K6-1-u1-X33"},{"t":"책의 줄거리","mis":"K6-1-u1-X33"},{"t":"책이 얼마나 재미있는지","mis":"K6-1-u1-X33"}],"explanation":["이름이나 줄거리가 중심이 아니에요.","책 자랑도 아니에요.","인물이 추구하는 가치가 중심이에요."]}'::jsonb),
('g6_1_kor_u1_L12_basic#2','kor',6,1,'u1','L12','g6_1_kor_u1_L12_basic','lesson_basic','K6-1-u1-C28',1,'mc','auto','소개할 인물을 고르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X34']::text[],false,'{"seq":2,"concept":"K6-1-u1-C28","difficulty":1,"kind":"mc","stem":"소개할 인물을 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"추구하는 가치와 그 근거가 되는 장면을 말할 수 있는 인물","correct":true},{"t":"가장 인기가 많고 유명한 인물","mis":"K6-1-u1-X34"},{"t":"가장 두꺼운 책에 나오는 인물","mis":"K6-1-u1-X34"},{"t":"그림이 가장 예쁜 인물","mis":"K6-1-u1-X34"}],"explanation":["인기나 책 두께는 기준이 아니에요.","가치를 근거로 설명할 수 있어야 해요.","본받고 싶은 인물도, 생각할 거리를 남긴 인물도 좋아요."]}'::jsonb),
('g6_1_kor_u1_L12_basic#3','kor',6,1,'u1','L12','g6_1_kor_u1_L12_basic','lesson_basic','K6-1-u1-C29',1,'match','auto','발표 짜임과 넣을 내용을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u1-C29","difficulty":1,"kind":"match","stem":"발표 짜임과 넣을 내용을 이으세요.","pairs":[{"l":"처음","r":"책 제목 · 지은이 · 인물 이름"},{"l":"가운데","r":"상황 · 말과 행동 · 추구하는 가치"},{"l":"끝","r":"내 생각과 느낌 · 실천할 다짐"}],"mis":"K6-1-u1-X35","explanation":["듣는 사람이 먼저 알아야 할 정보로 시작해요.","가운데에서 가치를 소개해요.","끝에 내 생각과 다짐을 말해요."],"asset":{"type":"passage","lines":["처음 · 책 제목과 지은이, 소개할 인물의 이름","가운데 · 인물이 처한 상황, 말과 행동, 추구하는 가치","끝 · 인물에 대한 내 생각과 느낌, 내가 실천하고 싶은 다짐"],"title":"인물 소개 발표의 짜임"}}'::jsonb),
('g6_1_kor_u1_L12_basic#4','kor',6,1,'u1','L12','g6_1_kor_u1_L12_basic','lesson_basic','K6-1-u1-C31',1,'mc','auto','시 「다시 도는 줄」에서 말하는 이는 줄에 걸렸을 때 어떻게 하나요?',ARRAY['K6-1-u1-X37']::text[],false,'{"seq":4,"concept":"K6-1-u1-C31","difficulty":1,"kind":"mc","stem":"시 「다시 도는 줄」에서 말하는 이는 줄에 걸렸을 때 어떻게 하나요?","options":[{"t":"「한 번 더」라고 말하며 다시 넘는다","correct":true},{"t":"줄넘기를 그만둔다","mis":"K6-1-u1-X37"},{"t":"친구보다 많이 넘어 일 등을 한다","mis":"K6-1-u1-X37"},{"t":"줄을 탓하며 화를 낸다","mis":"K6-1-u1-X37"}],"explanation":["마지막 줄을 다시 읽어요.","「오늘도 한 번 더」라고 해요.","걸린 뒤에 다시 넘어요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
