('g6_1_kor_u1_review_b#14','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C26',2,'mc','auto','도윤이의 감상문에 덧붙이면 가장 좋은 내용은 어느 것인가요?',ARRAY['K6-1-u1-X29','K6-1-u1-X30','K6-1-u1-X35']::text[],false,'{"seq":14,"concept":"K6-1-u1-C26","difficulty":2,"kind":"mc","stem":"도윤이의 감상문에 덧붙이면 가장 좋은 내용은 어느 것인가요?","options":[{"t":"도담이가 추구한 가치와 그 근거가 된 장면, 떠오른 내 경험","correct":true},{"t":"장마가 얼마나 길었는지","mis":"K6-1-u1-X29"},{"t":"「정말 정말 재미있었다」","mis":"K6-1-u1-X30"},{"t":"책의 쪽수와 값","mis":"K6-1-u1-X35"}],"explanation":["줄거리를 더 쓰지 않아요.","느낌을 세게 쓰는 것도 아니에요.","가치 · 근거 · 내 경험을 넣어요."],"asset":{"type":"passage","lines":["나는 「징검다리」를 읽었다. 장마 뒤에 돌이 떠내려갔다.","해솔이는 편지를 썼고, 도담이는 돌을 옮겼다.","가을에 마을에서 다리를 놓기로 했다.","정말 재미있었다. 다른 사람도 읽으면 좋겠다."],"title":"도윤이가 쓴 독서 감상문 초안"}}'::jsonb),
('g6_1_kor_u1_review_b#15','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C30',2,'mc','auto','「할아버지는 세상에서 가장 훌륭한 사람이에요.」를 균형 있게 고친 문장은 어느 것인가요?',ARRAY['K6-1-u1-X17','K6-1-u1-X05']::text[],false,'{"seq":15,"concept":"K6-1-u1-C30","difficulty":2,"kind":"mc","stem":"「할아버지는 세상에서 가장 훌륭한 사람이에요.」를 균형 있게 고친 문장은 어느 것인가요?","options":[{"t":"「할아버지는 손해가 될 때는 새로 사라고 돌려보낼 만큼 손님을 생각합니다. 고치는 데 오래 걸리는 점은 아쉬울 수 있지만 그 까닭이 이해됩니다.」","correct":true},{"t":"「할아버지는 고집쟁이입니다.」","mis":"K6-1-u1-X17"},{"t":"「할아버지는 돋보기를 씁니다.」","mis":"K6-1-u1-X05"},{"t":"「할아버지는 정말 정말 훌륭합니다.」","mis":"K6-1-u1-X17"}],"explanation":["흠만 잡지 않아요.","무조건 칭찬하지 않아요.","근거와 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["제가 소개할 책은 「고치는 손」입니다. 정말 재미있어요.","표지 그림이 예쁘고 쪽수가 많지 않아서 금방 읽을 수 있어요.","할아버지는 세상에서 가장 훌륭한 사람이에요.","마지막 장면이 깜짝 놀라우니 꼭 읽어 보세요."],"title":"서아의 인물 소개 발표 초안"}}'::jsonb),
('g6_1_kor_u1_review_b#16','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C32',2,'ox','auto','「앞으로 무슨 일이든 열심히 하겠다.」는 실천할 일로 알맞게 쓴 다짐이에요.',ARRAY['K6-1-u1-X25']::text[],false,'{"seq":16,"concept":"K6-1-u1-C32","difficulty":2,"kind":"ox","stem":"「앞으로 무슨 일이든 열심히 하겠다.」는 실천할 일로 알맞게 쓴 다짐이에요.","answer":"X","reason_options":[{"t":"언제 · 무엇을 할지 드러나지 않아 실제로 할 수 없기 때문에","correct":true},{"t":"열심히 하겠다는 마음이 가장 중요하기 때문에","mis":"K6-1-u1-X25"}],"mis":"K6-1-u1-X25","explanation":["마음만으로는 실천이 아니에요.","언제 할지 적어요.","무엇을 할지 적어요."],"asset":{"type":"speech","turns":[{"who":"주원","text":"가치: 끈기 / 할 일: 앞으로 무슨 일이든 열심히 하겠다."},{"who":"다인","text":"가치: 책임 / 할 일: 이번 주 모둠 관찰 기록을 금요일까지 날마다 빠짐없이 적기."},{"who":"태오","text":"가치: 배려 / 할 일: 착한 사람이 되겠다."}]}}'::jsonb),
('g6_1_kor_u1_review_b#17','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C16',3,'ox','auto','두 인물이 같은 가치 낱말을 추구하면 그 가치의 뜻도 언제나 똑같아요.',ARRAY['K6-1-u1-X18']::text[],false,'{"seq":17,"concept":"K6-1-u1-C16","difficulty":3,"kind":"ox","stem":"두 인물이 같은 가치 낱말을 추구하면 그 가치의 뜻도 언제나 똑같아요.","answer":"X","reason_options":[{"t":"어떤 상황에서 어떻게 실천되는지에 따라 그 가치의 뜻이 달라지기 때문에","correct":true},{"t":"가치 낱말의 뜻은 사전에 하나만 있기 때문에","mis":"K6-1-u1-X18"}],"mis":"K6-1-u1-X18","explanation":["만복의 효와 연수의 효가 달랐어요.","실천하는 모습을 봐요.","맥락을 함께 봐야 뜻이 보여요."]}'::jsonb),
('g6_1_kor_u1_review_b#18','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C20',3,'ox','auto','「도담이는 대단하다.」라고 말하면 도담이의 가치를 내 삶과 관련지은 거예요.',ARRAY['K6-1-u1-X24']::text[],false,'{"seq":18,"concept":"K6-1-u1-C20","difficulty":3,"kind":"ox","stem":"「도담이는 대단하다.」라고 말하면 도담이의 가치를 내 삶과 관련지은 거예요.","answer":"X","reason_options":[{"t":"관련짓기는 내 경험과 선택을 인물과 견주고 앞으로 할 일을 정하는 것이기 때문에","correct":true},{"t":"인물을 칭찬하면 내 생각이 드러나기 때문에","mis":"K6-1-u1-X24"}],"mis":"K6-1-u1-X24","explanation":["평가만으로는 부족해요.","비슷한 내 경험을 떠올려요.","같은 점 · 다른 점과 할 일을 정해요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_b#19','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C23',3,'mc','auto','「한 칸 뒤에서」에서 소진의 생각이 바뀌는 계기가 된 것은 무엇인가요?',ARRAY['K6-1-u1-X09','K6-1-u1-X27']::text[],false,'{"seq":19,"concept":"K6-1-u1-C23","difficulty":3,"kind":"mc","stem":"「한 칸 뒤에서」에서 소진의 생각이 바뀌는 계기가 된 것은 무엇인가요?","options":[{"t":"「너는 왜 플루트 불어?」라는 윤아의 물음","correct":true},{"t":"가율이 합주부를 그만둔 일","mis":"K6-1-u1-X09"},{"t":"소진이 첫째 줄로 돌아간 일","mis":"K6-1-u1-X09"},{"t":"처음부터 끝까지 생각이 바뀌지 않음","mis":"K6-1-u1-X27"}],"explanation":["윤아의 물음이 집에 오는 길까지 따라왔어요.","이기려고 부는지, 좋아서 부는지 물었어요.","그 물음이 생각을 움직였어요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_review_b#20','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C31',3,'mc','auto','「숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까」는 가치 파악 방법에서 무엇에 해당하나요?',ARRAY['K6-1-u1-X11','K6-1-u1-X05','K6-1-u1-X37']::text[],false,'{"seq":20,"concept":"K6-1-u1-C31","difficulty":3,"kind":"mc","stem":"「숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까」는 가치 파악 방법에서 무엇에 해당하나요?","options":[{"t":"그렇게 한 까닭","correct":true},{"t":"처한 상황","mis":"K6-1-u1-X11"},{"t":"말하는 이의 생김새","mis":"K6-1-u1-X05"},{"t":"시의 제목","mis":"K6-1-u1-X37"}],"explanation":["왜 「한 번 더」라고 하는지 알려 줘요.","수가 아니라 내가 늘어난다고 여겨요.","그렇게 한 까닭이에요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
('g6_1_kor_u1_review_b#21','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C27',3,'mc','auto','지우의 말을 존중하며 의견을 나누는 말로 고친 것은 어느 것인가요?',ARRAY['K6-1-u1-X04','K6-1-u1-X03']::text[],false,'{"seq":21,"concept":"K6-1-u1-C27","difficulty":3,"kind":"mc","stem":"지우의 말을 존중하며 의견을 나누는 말로 고친 것은 어느 것인가요?","options":[{"t":"「나는 도담이가 더 마음에 남았어. 그런데 하람이는 어느 장면을 보고 해솔이를 그렇게 봤는지 궁금해.」","correct":true},{"t":"「하람이 말은 틀렸어.」","mis":"K6-1-u1-X04"},{"t":"「도담이가 해솔이보다 훨씬 훌륭해.」","mis":"K6-1-u1-X03"},{"t":"「해솔이 이야기는 그만하자.」","mis":"K6-1-u1-X04"}],"explanation":["틀렸다고 하지 않아요.","등수를 매기지 않아요.","근거 장면을 물으며 내 생각을 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 해솔이가 「함께함」을 소중히 여긴다고 봤어. 친구들 이름을 하나하나 받으러 다녔잖아."},{"who":"지우","text":"그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해."},{"who":"시온","text":"나는 도담이가 「꾸준함」을 앞에 둔다고 봤어. 돌이 밀려나도 이튿날 다시 옮겼으니까."},{"who":"나윤","text":"시온아, 어느 장면에서 그렇게 생각했는지 더 말해 줄래? 나는 「책임」으로 봤거든."}]}}'::jsonb),
('g6_1_kor_u1_review_b#22','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C25',3,'ox','auto','「물건을 아끼자」는 가치를 고르면 시간과 값이 더 들 수 있다는 어려움도 함께 생각해야 해요.',ARRAY['K6-1-u1-X28']::text[],false,'{"seq":22,"concept":"K6-1-u1-C25","difficulty":3,"kind":"ox","stem":"「물건을 아끼자」는 가치를 고르면 시간과 값이 더 들 수 있다는 어려움도 함께 생각해야 해요.","answer":"O","reason_options":[{"t":"가치를 고른다는 것은 그 가치에 따르는 어려움까지 고르는 일이기 때문에","correct":true},{"t":"좋은 가치에는 어려움이 따르지 않기 때문에","mis":"K6-1-u1-X28"}],"mis":"K6-1-u1-X28","explanation":["말하기는 쉬워요.","실제로는 시간 · 값 · 기다림이 따라요.","그 어려움까지 고르는 일이에요."]}'::jsonb),
('g6_1_kor_u1_review_b#23','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C26',4,'mc','auto','도윤이의 감상문을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X29','K6-1-u1-X30','K6-1-u1-X17']::text[],false,'{"seq":23,"concept":"K6-1-u1-C26","difficulty":4,"kind":"mc","stem":"도윤이의 감상문을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「도담이는 돌이 밀려나도 이튿날 다시 옮겼다. 나는 이것을 꾸준함이라고 생각한다. 나도 받아쓰기에서 틀린 낱말을 몇 번 쓰다 그만둔 적이 있다. 이번 주에는 날마다 틀린 낱말 하나씩 끝까지 익히겠다.」","correct":true},{"t":"「장마 뒤에 돌이 떠내려갔다. 해솔이는 편지를 썼다. 도담이는 돌을 옮겼다. 가을에 다리를 놓기로 했다. 아이들이 학교에 갔다.」","mis":"K6-1-u1-X29"},{"t":"「정말 정말 재미있었다. 최고의 이야기다. 꼭 읽어 보길 바란다.」","mis":"K6-1-u1-X30"},{"t":"「도담이는 착하다. 해솔이는 나쁘다. 끝.」","mis":"K6-1-u1-X17"}],"explanation":["줄거리를 늘리지 않아요.","막연한 느낌을 세게 쓰지 않아요.","가치 · 근거 · 내 경험 · 실천할 일을 써요."],"asset":{"type":"passage","lines":["나는 「징검다리」를 읽었다. 장마 뒤에 돌이 떠내려갔다.","해솔이는 편지를 썼고, 도담이는 돌을 옮겼다.","가을에 마을에서 다리를 놓기로 했다.","정말 재미있었다. 다른 사람도 읽으면 좋겠다."],"title":"도윤이가 쓴 독서 감상문 초안"}}'::jsonb),
('g6_1_kor_u1_review_b#24','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C26',4,'essay','teacher','도윤이의 감상문 초안에서 고쳐야 할 점을 두 가지 쓰고, 가치와 근거, 내 경험, 실천할 일이 드러나게 감상문을 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u1-C26","difficulty":4,"kind":"essay","stem":"도윤이의 감상문 초안에서 고쳐야 할 점을 두 가지 쓰고, 가치와 근거, 내 경험, 실천할 일이 드러나게 감상문을 고쳐 쓰세요.","answer_guide":{"answer":"예: 고칠 점 — 첫째, 줄거리만 옮겨 적어 가치에 대한 내 생각이 없다. 둘째, 「재미있었다」처럼 어느 장면이 왜 좋았는지 없이 막연한 느낌으로 끝났다. 고쳐 쓴 감상문 — 나는 「징검다리」에서 해솔이가 함께함을 소중히 여긴다고 생각했다. 친구들의 이름을 하나하나 받으러 다닌 장면에서 그렇게 느꼈다. 나도 우리 반 쓰레기통이 부족했을 때 혼자 투덜대기만 했는데, 해솔이처럼 친구들과 뜻을 모아 말했다면 달랐을 것이다. 이번 주 학급 회의 때 우리 반에 필요한 것을 친구들과 함께 정리해 말해 보겠다.","scoring_points":["고칠 점 두 가지를 썼는가","가치와 근거 장면을 썼는가","내 경험과 실천할 일을 썼는가"]},"explanation":["줄거리 · 막연한 느낌을 찾아요.","가치와 근거 장면을 넣어요.","내 경험과 실천할 일로 마무리해요."],"asset":{"type":"passage","lines":["나는 「징검다리」를 읽었다. 장마 뒤에 돌이 떠내려갔다.","해솔이는 편지를 썼고, 도담이는 돌을 옮겼다.","가을에 마을에서 다리를 놓기로 했다.","정말 재미있었다. 다른 사람도 읽으면 좋겠다."],"title":"도윤이가 쓴 독서 감상문 초안"}}'::jsonb),
('g6_1_kor_u1_review_b#25','kor',6,1,'u1','','g6_1_kor_u1_review_b','unit_review','K6-1-u1-C3',4,'essay','teacher','「사람마다 추구하는 가치가 다르고, 가치에는 등수가 없다.」는 것을 이 단원에서 읽은 작품의 두 인물을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u1-C3","difficulty":4,"kind":"essay","stem":"「사람마다 추구하는 가치가 다르고, 가치에는 등수가 없다.」는 것을 이 단원에서 읽은 작품의 두 인물을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 「한 칸 뒤에서」의 소진은 밀려도 연습을 두 배로 하며 끈기를 앞에 두고, 윤아는 할 만큼 해 본 뒤 팀파니로 옮겨 좋아하는 일을 앞에 둔다. 소진은 끝이라고 할 만큼 해 보지 않았다고 느끼고, 윤아는 할 만큼 해 보았기 때문에 서로 다른 선택을 했다. 둘 다 대충 한 사람이 아니며 까닭이 다를 뿐이다. 그러므로 끈기와 즐거움 가운데 어느 것이 더 훌륭하다고 줄 세울 수 없고, 까닭을 살펴 서로를 이해해야 한다.","scoring_points":["두 인물의 가치를 바르게 썼는가","선택의 까닭이 다름을 썼는가","등수가 없고 이해 · 존중해야 함을 썼는가"]},"explanation":["두 인물의 가치를 찾아요.","선택의 까닭을 견주어요.","등수 대신 이해를 써요."]}'::jsonb),
('g6_1_kor_u1_review_c#1','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C1',1,'sa','auto','「사람들이 자신의 삶에서 중요하게 여기는 것」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u1-C1","difficulty":1,"kind":"sa","stem":"「사람들이 자신의 삶에서 중요하게 여기는 것」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["가치"],"explanation":["이 단원의 중심 낱말이에요.","인물이 소중히 여기는 것이에요.","두 글자로 「가치」예요."],"mis":"K6-1-u1-X01"}'::jsonb),
('g6_1_kor_u1_review_c#2','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C3',1,'mc','auto','나와 다른 가치를 소중히 여기는 친구에게 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u1-X04','K6-1-u1-X03']::text[],false,'{"seq":2,"concept":"K6-1-u1-C3","difficulty":1,"kind":"mc","stem":"나와 다른 가치를 소중히 여기는 친구에게 알맞은 태도는 어느 것인가요?","options":[{"t":"친구가 소중히 여기는 것을 이해하고 존중한다","correct":true},{"t":"친구가 틀렸다고 말해 준다","mis":"K6-1-u1-X04"},{"t":"내 가치가 더 훌륭하다고 알려 준다","mis":"K6-1-u1-X03"},{"t":"친구의 가치를 모른 척한다","mis":"K6-1-u1-X04"}],"explanation":["틀렸다고 하지 않아요.","등수를 매기지 않아요.","이해하고 존중해요."]}'::jsonb),
('g6_1_kor_u1_review_c#3','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C7',1,'mc','auto','전기문 「강을 건넌 사람」에서 그때가 어떤 때였는지 알려 주는 문장은 어느 것인가요?',ARRAY['K6-1-u1-X08']::text[],false,'{"seq":3,"concept":"K6-1-u1-C7","difficulty":1,"kind":"mc","stem":"전기문 「강을 건넌 사람」에서 그때가 어떤 때였는지 알려 주는 문장은 어느 것인가요?","options":[{"t":"나라는 이미 일본에 빼앗긴 뒤였다","correct":true},{"t":"정정화는 혼자 압록강을 건넜다","mis":"K6-1-u1-X08"},{"t":"「제가 다녀오겠습니다.」","mis":"K6-1-u1-X08"},{"t":"그는 아픈 사람을 돌보았다","mis":"K6-1-u1-X08"}],"explanation":["건넘 · 말 · 돌봄은 인물이 한 일이에요.","그때가 어떤 때였는지 찾아요.","나라를 빼앗긴 때였어요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_review_c#4','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C13',1,'ox','auto','가치를 파악하는 방법은 이야기 · 시 · 극본에도 쓸 수 있어요.',ARRAY['K6-1-u1-X13']::text[],false,'{"seq":4,"concept":"K6-1-u1-C13","difficulty":1,"kind":"ox","stem":"가치를 파악하는 방법은 이야기 · 시 · 극본에도 쓸 수 있어요.","answer":"O","reason_options":[{"t":"어느 작품의 인물이나 말하는 이에게도 상황과 말 · 행동 · 까닭이 있기 때문에","correct":true},{"t":"전기문에만 인물이 나오기 때문에","mis":"K6-1-u1-X13"}],"mis":"K6-1-u1-X13","explanation":["이야기에도 인물이 있어요.","시에도 말하는 이가 있어요.","같은 방법을 써요."]}'::jsonb),
('g6_1_kor_u1_review_c#5','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C12',1,'mc','auto','「낡거나 헌 물건을 고침」을 뜻하는 낱말은 무엇인가요?',ARRAY['K6-1-u1-X14']::text[],false,'{"seq":5,"concept":"K6-1-u1-C12","difficulty":1,"kind":"mc","stem":"「낡거나 헌 물건을 고침」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"수선","correct":true},{"t":"부품","mis":"K6-1-u1-X14"},{"t":"고집","mis":"K6-1-u1-X14"},{"t":"가마","mis":"K6-1-u1-X14"}],"explanation":["부품은 기계의 조각이에요.","고집은 생각을 굽히지 않는 거예요.","고치는 것은 수선이에요."]}'::jsonb),
('g6_1_kor_u1_review_c#6','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C26',1,'ox','auto','독서 감상문은 그림이나 만화로 나타내도 돼요.',ARRAY['K6-1-u1-X31']::text[],false,'{"seq":6,"concept":"K6-1-u1-C26","difficulty":1,"kind":"ox","stem":"독서 감상문은 그림이나 만화로 나타내도 돼요.","answer":"O","reason_options":[{"t":"형식은 자유이고 가치에 대한 내 생각이 드러나는 것이 중요하기 때문에","correct":true},{"t":"감상문은 줄글로만 써야 하기 때문에","mis":"K6-1-u1-X31"}],"mis":"K6-1-u1-X31","explanation":["줄글 · 편지 · 그림 · 만화 모두 돼요.","형식보다 내용이 중요해요.","가치에 대한 내 생각이 드러나야 해요."]}'::jsonb),
('g6_1_kor_u1_review_c#7','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C29',1,'mc','auto','인물 소개 발표의 「끝」에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X35']::text[],false,'{"seq":7,"concept":"K6-1-u1-C29","difficulty":1,"kind":"mc","stem":"인물 소개 발표의 「끝」에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"인물에 대한 내 생각과 느낌, 실천할 다짐","correct":true},{"t":"책 제목과 지은이","mis":"K6-1-u1-X35"},{"t":"인물이 처한 상황","mis":"K6-1-u1-X35"},{"t":"책의 쪽수","mis":"K6-1-u1-X35"}],"explanation":["제목과 지은이는 처음이에요.","상황은 가운데예요.","끝에는 내 생각과 다짐을 말해요."],"asset":{"type":"passage","lines":["처음 · 책 제목과 지은이, 소개할 인물의 이름","가운데 · 인물이 처한 상황, 말과 행동, 추구하는 가치","끝 · 인물에 대한 내 생각과 느낌, 내가 실천하고 싶은 다짐"],"title":"인물 소개 발표의 짜임"}}'::jsonb),
('g6_1_kor_u1_review_c#8','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C9',1,'mc','auto','「징검다리」에서 해솔이가 한 일은 어느 것인가요?',ARRAY['K6-1-u1-X09']::text[],false,'{"seq":8,"concept":"K6-1-u1-C9","difficulty":1,"kind":"mc","stem":"「징검다리」에서 해솔이가 한 일은 어느 것인가요?","options":[{"t":"마을 회관에 보낼 편지를 쓰고 친구들의 이름을 받으러 다녔다","correct":true},{"t":"날마다 돌을 옮겼다","mis":"K6-1-u1-X09"},{"t":"신발을 벗지 않고 건넜다","mis":"K6-1-u1-X09"},{"t":"다리를 놓는 날 학교에 가지 않았다","mis":"K6-1-u1-X09"}],"explanation":["돌을 옮긴 것은 도담이에요.","해솔이는 어른들께 다리를 놓아 달라고 했어요.","편지를 쓰고 이름을 받았어요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_c#9','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C14',2,'mc','auto','해솔이와 도담이를 비교한 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X16','K6-1-u1-X05','K6-1-u1-X17']::text[],false,'{"seq":9,"concept":"K6-1-u1-C14","difficulty":2,"kind":"mc","stem":"해솔이와 도담이를 비교한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"처지는 같지만 해솔이는 함께 바꾸는 길을, 도담이는 날마다 손으로 메우는 길을 골랐다","correct":true},{"t":"처지가 같으니 두 아이의 가치도 똑같다","mis":"K6-1-u1-X16"},{"t":"도담이는 말이 없으니 가치가 없다","mis":"K6-1-u1-X05"},{"t":"해솔이는 말만 했으니 아무 일도 하지 않았다","mis":"K6-1-u1-X17"}],"explanation":["같은 처지에서 다른 길을 골랐어요.","두 사람 모두 할 일을 했어요.","바라보는 곳이 달랐을 뿐이에요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_c#10','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C15',2,'error','auto','만복과 연수를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u1-X17','K6-1-u1-X16']::text[],false,'{"seq":10,"concept":"K6-1-u1-C15","difficulty":2,"kind":"error","stem":"만복과 연수를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"라희 — 「돈을 좇은 만복은 나쁜 아이야.」","correct":true,"mis_target":"K6-1-u1-X17"},{"t":"지안 — 「만복은 어머니를 빨리 모시고 싶었어.」","mis":"K6-1-u1-X17"},{"t":"우진 — 「연수는 과정을 앞에 두었어.」","mis":"K6-1-u1-X16"}],"explanation":["지안과 우진은 까닭과 차이를 살폈어요.","라희는 만복을 나쁘다고 갈랐어요.","좋다 · 나쁘다로 가르지 않아요."]}'::jsonb),
('g6_1_kor_u1_review_c#11','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C8',2,'ox','auto','같은 말이라도 시대 상황을 넣고 보면 그 말의 무게가 달라질 수 있어요.',ARRAY['K6-1-u1-X08']::text[],false,'{"seq":11,"concept":"K6-1-u1-C8","difficulty":2,"kind":"ox","stem":"같은 말이라도 시대 상황을 넣고 보면 그 말의 무게가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"「제가 다녀오겠습니다.」가 목숨을 건 말이 되듯 때에 따라 뜻이 달라지기 때문에","correct":true},{"t":"말의 뜻은 언제나 똑같기 때문에","mis":"K6-1-u1-X08"}],"mis":"K6-1-u1-X08","explanation":["시대를 빼면 심부름 같아요.","시대를 넣으면 목숨을 건 말이에요.","말과 행동은 시대 안에서 봐요."]}'::jsonb),
('g6_1_kor_u1_review_c#12','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C24',2,'mc','auto','도담이의 가치를 시온이는 「꾸준함」, 나윤이는 「책임」으로 보았어요. 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X12','K6-1-u1-X04']::text[],false,'{"seq":12,"concept":"K6-1-u1-C24","difficulty":2,"kind":"mc","stem":"도담이의 가치를 시온이는 「꾸준함」, 나윤이는 「책임」으로 보았어요. 알맞은 말은 어느 것인가요?","options":[{"t":"둘 다 근거를 댈 수 있다면 가치에 대한 판단이 갈려도 괜찮다","correct":true},{"t":"꾸준함이 책임보다 훌륭하므로 시온이가 맞다","mis":"K6-1-u1-X03"},{"t":"판단이 갈리면 둘 다 틀린 것이다","mis":"K6-1-u1-X12"},{"t":"나윤이는 시온이와 다르므로 틀렸다","mis":"K6-1-u1-X04"}],"explanation":["같은 인물도 다르게 볼 수 있어요.","가치에는 위아래가 없어요.","중요한 것은 근거예요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 해솔이가 「함께함」을 소중히 여긴다고 봤어. 친구들 이름을 하나하나 받으러 다녔잖아."},{"who":"지우","text":"그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해."},{"who":"시온","text":"나는 도담이가 「꾸준함」을 앞에 둔다고 봤어. 돌이 밀려나도 이튿날 다시 옮겼으니까."},{"who":"나윤","text":"시온아, 어느 장면에서 그렇게 생각했는지 더 말해 줄래? 나는 「책임」으로 봤거든."}]}}'::jsonb),
('g6_1_kor_u1_review_c#13','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C18',2,'mc','auto','연수가 첫 그릇 앞에서 「기쁨보다 무거운 것」을 느낀 마음 아래에 있는 가치는 무엇인가요?',ARRAY['K6-1-u1-X21','K6-1-u1-X22']::text[],false,'{"seq":13,"concept":"K6-1-u1-C18","difficulty":2,"kind":"mc","stem":"연수가 첫 그릇 앞에서 「기쁨보다 무거운 것」을 느낀 마음 아래에 있는 가치는 무엇인가요?","options":[{"t":"그릇을 쓸 사람을 생각하는 책임","correct":true},{"t":"그릇이 비뚤어 창피한 마음 그 자체","mis":"K6-1-u1-X21"},{"t":"만복을 이기고 싶은 마음","mis":"K6-1-u1-X22"},{"t":"가마 어른의 칭찬","mis":"K6-1-u1-X22"}],"explanation":["무거운 마음은 마음이에요.","그 그릇이 한 해 내내 장을 품을 것을 생각했어요.","그 아래에 책임이 있어요."],"asset":{"type":"passage","lines":["장에서 물을 담던 항아리가 겨울을 넘기지 못하고 갈라졌다.","「흙에 굵은 알갱이가 섞이면 불을 견디지 못한다. 그릇은 빚는 날이","아니라 흙을 거르는 날에 이미 반쯤 만들어진다.」 가마 어른이 말했다.","그해 가을, 만복은 그릇을 사다 되파는 일이 더 빨리 돈이 된다며 떠났다.","연수는 남았다. 세 해째 되던 날 처음으로 물레 앞에 앉았다.","연수가 빚은 첫 그릇은 비뚤었다. 그런데도 연수의 마음에는","기쁨보다 무거운 것이 먼저 내려앉았다. 누군가의 집에서","한 해 내내 장을 품고 있을 그릇이었기 때문이다."],"title":"이야기 「흙을 고르는 아이」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_review_c#14','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C26',2,'ox','auto','도윤이의 감상문은 줄거리를 잘 옮겼으므로 좋은 독서 감상문이에요.',ARRAY['K6-1-u1-X29']::text[],false,'{"seq":14,"concept":"K6-1-u1-C26","difficulty":2,"kind":"ox","stem":"도윤이의 감상문은 줄거리를 잘 옮겼으므로 좋은 독서 감상문이에요.","answer":"X","reason_options":[{"t":"독서 감상문은 줄거리가 아니라 가치에 대한 내 생각이 드러나야 하기 때문에","correct":true},{"t":"줄거리만 정확하면 감상문이 되기 때문에","mis":"K6-1-u1-X29"}],"mis":"K6-1-u1-X29","explanation":["줄거리는 간단히만 써요.","가치에 대한 생각이 빠졌어요.","내 경험도 빠졌어요."],"asset":{"type":"passage","lines":["나는 「징검다리」를 읽었다. 장마 뒤에 돌이 떠내려갔다.","해솔이는 편지를 썼고, 도담이는 돌을 옮겼다.","가을에 마을에서 다리를 놓기로 했다.","정말 재미있었다. 다른 사람도 읽으면 좋겠다."],"title":"도윤이가 쓴 독서 감상문 초안"}}'::jsonb),
('g6_1_kor_u1_review_c#15','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C28',2,'ox','auto','서아의 초안은 인물이 추구하는 가치를 잘 소개했어요.',ARRAY['K6-1-u1-X33']::text[],false,'{"seq":15,"concept":"K6-1-u1-C28","difficulty":2,"kind":"ox","stem":"서아의 초안은 인물이 추구하는 가치를 잘 소개했어요.","answer":"X","reason_options":[{"t":"재미 · 표지 · 쪽수 이야기만 있고 가치와 근거 장면이 없기 때문에","correct":true},{"t":"책이 재미있다고 했기 때문에","mis":"K6-1-u1-X33"}],"mis":"K6-1-u1-X33","explanation":["재미있다는 말은 가치가 아니에요.","표지와 쪽수도 가치가 아니에요.","가치와 근거 장면이 필요해요."],"asset":{"type":"passage","lines":["제가 소개할 책은 「고치는 손」입니다. 정말 재미있어요.","표지 그림이 예쁘고 쪽수가 많지 않아서 금방 읽을 수 있어요.","할아버지는 세상에서 가장 훌륭한 사람이에요.","마지막 장면이 깜짝 놀라우니 꼭 읽어 보세요."],"title":"서아의 인물 소개 발표 초안"}}'::jsonb),
('g6_1_kor_u1_review_c#16','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C32',2,'mc','auto','태오의 다짐 「착한 사람이 되겠다.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X25','K6-1-u1-X39','K6-1-u1-X03']::text[],false,'{"seq":16,"concept":"K6-1-u1-C32","difficulty":2,"kind":"mc","stem":"태오의 다짐 「착한 사람이 되겠다.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이번 주 점심시간마다 혼자 있는 친구에게 먼저 말을 걸기」","correct":true},{"t":"「앞으로 정말 착한 사람이 되겠다」","mis":"K6-1-u1-X25"},{"t":"「배려의 뜻을 공책에 적어 두기」","mis":"K6-1-u1-X39"},{"t":"「착한 사람이 되는 것이 가장 훌륭하다」","mis":"K6-1-u1-X03"}],"explanation":["두루뭉술한 다짐을 고쳐요.","뜻만 적는 것은 실천이 아니에요.","언제 · 무엇을 할지 적어요."],"asset":{"type":"speech","turns":[{"who":"주원","text":"가치: 끈기 / 할 일: 앞으로 무슨 일이든 열심히 하겠다."},{"who":"다인","text":"가치: 책임 / 할 일: 이번 주 모둠 관찰 기록을 금요일까지 날마다 빠짐없이 적기."},{"who":"태오","text":"가치: 배려 / 할 일: 착한 사람이 되겠다."}]}}'::jsonb),
('g6_1_kor_u1_review_c#17','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C16',3,'mc','auto','만복의 「효」와 연수의 「효」를 알맞게 비교한 것은 어느 것인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X17']::text[],false,'{"seq":17,"concept":"K6-1-u1-C16","difficulty":3,"kind":"mc","stem":"만복의 「효」와 연수의 「효」를 알맞게 비교한 것은 어느 것인가요?","options":[{"t":"만복은 빨리 돈을 벌어 집을 지어 드리고, 연수는 어머니가 부끄럽지 않을 만큼 한 가지 일을 익힌다","correct":true},{"t":"두 사람의 효는 똑같다","mis":"K6-1-u1-X18"},{"t":"만복의 효는 효가 아니다","mis":"K6-1-u1-X17"},{"t":"연수는 효를 생각하지 않는다","mis":"K6-1-u1-X18"}],"explanation":["같은 효도 실천이 달라요.","만복에게도 까닭이 있어요.","상황 속 실천을 봐요."],"asset":{"type":"passage","lines":["만복과 연수는 같은 해에 옹기점에 들어왔다. 둘 다 집이 가난했다.","가마 어른은 두 아이에게 똑같이 수비를 맡겼다.","그날 걸러 낸 흙은 이듬해에나 그릇이 되었다.","반년이 지나도 흙만 거르자 만복은 조바심이 났다.","「흙 고르는 일이야 사람을 사서 시키면 그만 아닙니까.","저는 빨리 그릇을 빚어 팔고, 어머니께 기와집을 지어 드리고 싶습니다.」","연수는 걸러 낸 흙을 손끝으로 문질러 보는 버릇이 있었다.","어제 흙보다 오늘 흙이 곱게 걸러졌는지 알아보려는 것이었다."],"title":"이야기 「흙을 고르는 아이」 앞부분"}}'::jsonb),
('g6_1_kor_u1_review_c#18','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C20',3,'mc','auto','인물의 가치를 나와 견줄 때 「그때 나의 선택과 인물의 선택에서 같은 점과 다른 점 찾기」 다음에 할 일은 무엇인가요?',ARRAY['K6-1-u1-X24','K6-1-u1-X03']::text[],false,'{"seq":18,"concept":"K6-1-u1-C20","difficulty":3,"kind":"mc","stem":"인물의 가치를 나와 견줄 때 「그때 나의 선택과 인물의 선택에서 같은 점과 다른 점 찾기」 다음에 할 일은 무엇인가요?","options":[{"t":"내가 앞으로 추구할 가치와 해 볼 일 정하기","correct":true},{"t":"인물 평가하기","mis":"K6-1-u1-X24"},{"t":"줄거리 다시 쓰기","mis":"K6-1-u1-X24"},{"t":"더 훌륭한 인물 고르기","mis":"K6-1-u1-X03"}],"explanation":["경험을 떠올렸어요.","같은 점과 다른 점을 찾았어요.","앞으로 할 일을 정해요."]}'::jsonb),
('g6_1_kor_u1_review_c#19','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C21',3,'ox','auto','소진과 윤아의 선택 가운데 더 옳은 쪽을 골라야 이야기를 제대로 읽은 거예요.',ARRAY['K6-1-u1-X03']::text[],false,'{"seq":19,"concept":"K6-1-u1-C21","difficulty":3,"kind":"ox","stem":"소진과 윤아의 선택 가운데 더 옳은 쪽을 골라야 이야기를 제대로 읽은 거예요.","answer":"X","reason_options":[{"t":"두 사람의 선택에는 저마다 까닭이 있고 가치에는 등수가 없기 때문에","correct":true},{"t":"끝까지 버틴 쪽이 언제나 옳기 때문에","mis":"K6-1-u1-X03"}],"mis":"K6-1-u1-X03","explanation":["옳은 쪽을 고르지 않아요.","선택의 까닭을 살펴요.","까닭을 알면 다른 선택도 이해돼요."]}'::jsonb),
('g6_1_kor_u1_review_c#20','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C31',3,'ox','auto','시의 말하는 이에게도 추구하는 가치가 있어요.',ARRAY['K6-1-u1-X37']::text[],false,'{"seq":20,"concept":"K6-1-u1-C31","difficulty":3,"kind":"ox","stem":"시의 말하는 이에게도 추구하는 가치가 있어요.","answer":"O","reason_options":[{"t":"말하는 이의 상황과 말 · 행동 · 까닭에서 가치를 찾을 수 있기 때문에","correct":true},{"t":"가치는 이야기 속 인물에게만 있기 때문에","mis":"K6-1-u1-X37"}],"mis":"K6-1-u1-X37","explanation":["말하는 이는 「한 번 더」라고 말해요.","다시 넘는 행동을 해요.","거기서 가치를 찾아요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
('g6_1_kor_u1_review_c#21','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C27',3,'mc','auto','나윤이의 말에서 본받을 점은 무엇인가요?',ARRAY['K6-1-u1-X04','K6-1-u1-X03']::text[],false,'{"seq":21,"concept":"K6-1-u1-C27","difficulty":3,"kind":"mc","stem":"나윤이의 말에서 본받을 점은 무엇인가요?","options":[{"t":"다른 생각을 들었을 때 어느 장면을 보고 그렇게 생각했는지 물었다","correct":true},{"t":"친구의 생각을 바로 고쳐 주었다","mis":"K6-1-u1-X04"},{"t":"자기 생각만 말하고 끝냈다","mis":"K6-1-u1-X04"},{"t":"가장 훌륭한 가치를 정해 주었다","mis":"K6-1-u1-X03"}],"explanation":["나윤이는 시온이에게 물었어요.","자기 생각(책임)도 말했어요.","근거 장면을 묻고 존중했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 해솔이가 「함께함」을 소중히 여긴다고 봤어. 친구들 이름을 하나하나 받으러 다녔잖아."},{"who":"지우","text":"그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해."},{"who":"시온","text":"나는 도담이가 「꾸준함」을 앞에 둔다고 봤어. 돌이 밀려나도 이튿날 다시 옮겼으니까."},{"who":"나윤","text":"시온아, 어느 장면에서 그렇게 생각했는지 더 말해 줄래? 나는 「책임」으로 봤거든."}]}}'::jsonb),
('g6_1_kor_u1_review_c#22','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C5',3,'mc','auto','「징검다리」에 「돌을 옮겨 봤자 또 밀려난다」며 개울을 피해 먼 길로만 다닌 아이가 있었다고 해 봐요. 이 아이에게서 얻을 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X06','K6-1-u1-X03','K6-1-u1-X17']::text[],false,'{"seq":22,"concept":"K6-1-u1-C5","difficulty":3,"kind":"mc","stem":"「징검다리」에 「돌을 옮겨 봤자 또 밀려난다」며 개울을 피해 먼 길로만 다닌 아이가 있었다고 해 봐요. 이 아이에게서 얻을 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나만 편한 길을 고르면 다른 아이들이 건널 길은 그대로 남는다는 것","correct":true},{"t":"실망스러운 인물에게서는 배울 것이 없다","mis":"K6-1-u1-X06"},{"t":"먼 길로 다니는 것이 가장 옳다","mis":"K6-1-u1-X03"},{"t":"그 아이는 나쁜 아이라고 정하면 된다","mis":"K6-1-u1-X17"}],"explanation":["실망스러운 인물도 생각을 남겨요.","편한 쪽만 고르면 무엇이 남는지 봐요.","나쁘다고 정하지 않고 생각할 거리를 찾아요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_c#23','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C30',4,'mc','auto','서아의 소개 초안을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X33','K6-1-u1-X17','K6-1-u1-X32']::text[],false,'{"seq":23,"concept":"K6-1-u1-C30","difficulty":4,"kind":"mc","stem":"서아의 소개 초안을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「『고치는 손』의 할아버지를 소개합니다. 할아버지는 손님에게 손해가 될 때는 새로 사라고 돌려보낼 만큼 손님을 생각하고, 할머니의 시계를 고치며 시간을 지켰습니다. 저는 고치는 데 오래 걸리는 점이 아쉬울 수 있다고 생각하지만, 물건에 담긴 마음을 지키려는 정성은 본받고 싶습니다.」","correct":true},{"t":"「『고치는 손』은 표지가 예쁘고 얇아서 금방 읽을 수 있어요. 마지막 장면이 놀라우니 꼭 읽어 보세요.」","mis":"K6-1-u1-X33"},{"t":"「할아버지는 세상에서 가장 훌륭한 사람이에요. 정말 정말 훌륭해요.」","mis":"K6-1-u1-X17"},{"t":"「할아버지는 고집쟁이예요. 새것을 사면 될 텐데 왜 고치는지 모르겠어요.」","mis":"K6-1-u1-X32"}],"explanation":["책 자랑은 소개가 아니에요.","칭찬만도 흠잡기만도 하지 않아요.","가치 · 근거 · 균형 잡힌 내 생각을 담아요."],"asset":{"type":"passage","lines":["제가 소개할 책은 「고치는 손」입니다. 정말 재미있어요.","표지 그림이 예쁘고 쪽수가 많지 않아서 금방 읽을 수 있어요.","할아버지는 세상에서 가장 훌륭한 사람이에요.","마지막 장면이 깜짝 놀라우니 꼭 읽어 보세요."],"title":"서아의 인물 소개 발표 초안"}}'::jsonb),
('g6_1_kor_u1_review_c#24','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C28',4,'essay','teacher','서아의 인물 소개 초안에서 알맞지 않은 점을 세 가지 찾아 까닭을 쓰고, 처음 · 가운데 · 끝의 짜임에 맞게 소개를 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u1-C28","difficulty":4,"kind":"essay","stem":"서아의 인물 소개 초안에서 알맞지 않은 점을 세 가지 찾아 까닭을 쓰고, 처음 · 가운데 · 끝의 짜임에 맞게 소개를 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 「정말 재미있어요」, 「꼭 읽어 보세요」는 책 자랑이라 인물의 가치가 드러나지 않는다. 둘째, 표지 그림과 쪽수는 가치를 알려 주지 못하는 정보다. 셋째, 「세상에서 가장 훌륭한 사람」은 근거 없이 무조건 칭찬한 말이다. 고친 소개 — 처음: 「고치는 손」의 할아버지를 소개합니다. 가운데: 할아버지는 「무엇이든 고칩니다」 수선집을 하지만, 손님에게 손해가 될 때는 새로 사라고 돌려보냅니다. 할머니의 시계를 고치고는 시간을 고쳤다고 말합니다. 할아버지는 물건에 담긴 마음을 지키는 정성을 소중히 여깁니다. 끝: 고치는 데 오래 걸리는 점은 아쉬울 수 있지만 그 까닭이 이해됩니다. 저도 이번 주에 망가진 필통을 버리지 않고 고쳐 쓰겠습니다.","scoring_points":["알맞지 않은 점 세 가지와 까닭을 썼는가","처음 · 가운데 · 끝의 짜임으로 고쳐 썼는가","가치와 근거를 넣고 균형 있게 소개했는가"]},"explanation":["책 자랑 · 겉 정보 · 무조건 칭찬을 찾아요.","짜임에 맞게 고쳐요.","가치와 근거, 균형을 담아요."],"asset":{"type":"passage","lines":["제가 소개할 책은 「고치는 손」입니다. 정말 재미있어요.","표지 그림이 예쁘고 쪽수가 많지 않아서 금방 읽을 수 있어요.","할아버지는 세상에서 가장 훌륭한 사람이에요.","마지막 장면이 깜짝 놀라우니 꼭 읽어 보세요."],"title":"서아의 인물 소개 발표 초안"}}'::jsonb),
('g6_1_kor_u1_review_c#25','kor',6,1,'u1','','g6_1_kor_u1_review_c','unit_review','K6-1-u1-C8',4,'essay','teacher','전기문 「강을 건넌 사람」을 예로 들어, 인물의 말과 행동을 시대 상황과 관련지어 읽어야 하는 까닭을 설명하세요. 연도 같은 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u1-C8","difficulty":4,"kind":"essay","stem":"전기문 「강을 건넌 사람」을 예로 들어, 인물의 말과 행동을 시대 상황과 관련지어 읽어야 하는 까닭을 설명하세요. 연도 같은 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 정정화는 혼자 압록강을 건너고 「제가 다녀오겠습니다.」 하며 국내와 상하이를 여러 차례 오갔다. 시대를 빼고 보면 그저 먼 길을 다녀온 일과 심부름을 맡겠다는 말처럼 보인다. 그러나 그때는 나라를 빼앗겨 감시가 심했고 여자가 홀로 먼 길을 떠나기 어려웠으며 국경을 넘다 붙잡히면 목숨이 위험했다. 이 시대 상황을 넣고 보면 그 말과 행동은 목숨을 건 용기와 책임이 된다. 그래서 전기문은 시대 상황과 관련지어 읽어야 인물이 추구한 가치가 제대로 보인다.","scoring_points":["인물의 말과 행동을 글에서 찾았는가","시대 상황을 넣기 전과 뒤의 뜻을 견주었는가","관련지어 읽어야 가치가 보인다는 까닭을 썼는가"]},"explanation":["말과 행동을 먼저 찾아요.","시대를 넣고 빼서 견주어요.","가치가 어떻게 보이는지 써요."],"asset":{"type":"passage","lines":["정정화가 스무 살이 되기 전, 나라는 이미 일본에 빼앗긴 뒤였다.","남편과 시아버지는 나라를 되찾으려고 중국 상하이로 떠났다.","정정화는 「기다리기만 해서는 아무것도 달라지지 않는다.」고 생각했다.","여자가 먼 길을 홀로 떠나는 일이 드물고, 국경을 넘다 붙잡히면","목숨이 위험하던 때였다. 정정화는 혼자 압록강을 건넜다.","임시정부는 가난했고, 돈은 국내에서 모아 와야 했다.","아무도 선뜻 나서지 못할 때 정정화가 말했다.","「제가 다녀오겠습니다. 저는 눈에 덜 띕니다.」"],"title":"전기문 「강을 건넌 사람」 앞부분"}}'::jsonb),
('g6_1_kor_u1_review_d#1','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C2',1,'mc','auto','두 낱말 모두 가치를 나타내는 것은 어느 것인가요?',ARRAY['K6-1-u1-X02']::text[],false,'{"seq":1,"concept":"K6-1-u1-C2","difficulty":1,"kind":"mc","stem":"두 낱말 모두 가치를 나타내는 것은 어느 것인가요?","options":[{"t":"용기 · 끈기","correct":true},{"t":"용기 · 숙제","mis":"K6-1-u1-X02"},{"t":"시간표 · 끈기","mis":"K6-1-u1-X02"},{"t":"우물 · 급식","mis":"K6-1-u1-X02"}],"explanation":["숙제 · 시간표 · 급식은 하는 일이에요.","우물은 물건이에요.","용기와 끈기는 가치 낱말이에요."]}'::jsonb),
('g6_1_kor_u1_review_d#2','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C21',1,'mc','auto','「끈기가 즐거움보다 훌륭하다.」는 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X02']::text[],false,'{"seq":2,"concept":"K6-1-u1-C21","difficulty":1,"kind":"mc","stem":"「끈기가 즐거움보다 훌륭하다.」는 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"가치에는 등수가 없기 때문에","correct":true},{"t":"즐거움이 끈기보다 훌륭하기 때문에","mis":"K6-1-u1-X03"},{"t":"끈기는 가치가 아니기 때문에","mis":"K6-1-u1-X02"},{"t":"즐거움은 물건이기 때문에","mis":"K6-1-u1-X02"}],"explanation":["어느 쪽이 더 훌륭하다고 하지 않아요.","끈기와 즐거움 모두 가치예요.","가치에는 등수가 없어요."]}'::jsonb),
