('g6_1_kor_u1_review_d#4','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C10',1,'mc','auto','인물이 추구하는 가치를 파악할 때 살필 것이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u1-X05']::text[],false,'{"seq":4,"concept":"K6-1-u1-C10","difficulty":1,"kind":"mc","stem":"인물이 추구하는 가치를 파악할 때 살필 것이 아닌 것은 어느 것인가요?","options":[{"t":"작품이 팔린 부수","correct":true},{"t":"인물이 처한 상황","mis":"K6-1-u1-X05"},{"t":"인물의 말과 행동","mis":"K6-1-u1-X05"},{"t":"그렇게 말하거나 행동한 까닭","mis":"K6-1-u1-X05"}],"explanation":["상황 · 말과 행동 · 까닭을 살펴요.","글 밖의 정보는 근거가 못 돼요.","팔린 부수는 가치를 알려 주지 못해요."]}'::jsonb),
('g6_1_kor_u1_review_d#5','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C33',1,'mc','auto','「여러 가지를 한데 모아서 합하다」의 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-1-u1-X38','K6-1-u1-X14']::text[],false,'{"seq":5,"concept":"K6-1-u1-C33","difficulty":1,"kind":"mc","stem":"「여러 가지를 한데 모아서 합하다」의 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"종합하다","correct":true},{"t":"개선하다","mis":"K6-1-u1-X38"},{"t":"적용하다","mis":"K6-1-u1-X38"},{"t":"수선하다","mis":"K6-1-u1-X14"}],"explanation":["개선은 고쳐 좋게 하는 거예요.","적용은 맞추어 쓰는 거예요.","모아서 합하는 것은 종합하다예요."]}'::jsonb),
('g6_1_kor_u1_review_d#6','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C26',1,'mc','auto','독서 감상문에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X35','K6-1-u1-X29','K6-1-u1-X30']::text[],false,'{"seq":6,"concept":"K6-1-u1-C26","difficulty":1,"kind":"mc","stem":"독서 감상문에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 앞으로 추구하고 싶은 가치와 실천할 일","correct":true},{"t":"책을 산 가게 이름","mis":"K6-1-u1-X35"},{"t":"이야기를 처음부터 끝까지 옮긴 글","mis":"K6-1-u1-X29"},{"t":"「좋았다」를 여러 번 쓴 문장","mis":"K6-1-u1-X30"}],"explanation":["가게 이름은 가치와 상관없어요.","줄거리를 옮기지 않아요.","추구하고 싶은 가치와 실천할 일을 넣어요."]}'::jsonb),
('g6_1_kor_u1_review_d#7','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C29',1,'ox','auto','소개 자료에 남이 그린 그림을 쓸 때에는 출처를 밝혀요.',ARRAY['K6-1-u1-X36']::text[],false,'{"seq":7,"concept":"K6-1-u1-C29","difficulty":1,"kind":"ox","stem":"소개 자료에 남이 그린 그림을 쓸 때에는 출처를 밝혀요.","answer":"O","reason_options":[{"t":"남의 그림 · 사진 · 글에는 만든 사람이 있기 때문에","correct":true},{"t":"그림은 누구나 마음대로 써도 되기 때문에","mis":"K6-1-u1-X36"}],"mis":"K6-1-u1-X36","explanation":["만든 사람을 존중해요.","출처를 밝혀요.","직접 만든 것을 써도 돼요."]}'::jsonb),
('g6_1_kor_u1_review_d#8','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C13',1,'ox','auto','「징검다리」에서 돌이 떠내려간 일은 해솔이와 도담이가 저마다 무언가를 하게 된 까닭이 되었어요.',ARRAY['K6-1-u1-X15']::text[],false,'{"seq":8,"concept":"K6-1-u1-C13","difficulty":1,"kind":"ox","stem":"「징검다리」에서 돌이 떠내려간 일은 해솔이와 도담이가 저마다 무언가를 하게 된 까닭이 되었어요.","answer":"O","reason_options":[{"t":"앞의 일(돌이 떠내려감)이 뒤의 일(편지 · 돌 옮기기)을 불렀기 때문에","correct":true},{"t":"두 아이가 한 일은 장마와 아무 상관이 없기 때문에","mis":"K6-1-u1-X15"}],"mis":"K6-1-u1-X15","explanation":["장마 뒤에 돌이 떠내려갔어요.","그래서 둘은 각자 할 일을 찾았어요.","앞의 일이 뒤의 일을 불러요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_d#9','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C14',2,'ox','auto','같은 징검다리를 건너는 해솔이와 도담이도 추구하는 가치가 다를 수 있어요.',ARRAY['K6-1-u1-X16']::text[],false,'{"seq":9,"concept":"K6-1-u1-C14","difficulty":2,"kind":"ox","stem":"같은 징검다리를 건너는 해솔이와 도담이도 추구하는 가치가 다를 수 있어요.","answer":"O","reason_options":[{"t":"처지가 같아도 무엇을 앞에 두느냐가 다를 수 있기 때문에","correct":true},{"t":"처지가 같으면 가치도 같아야 하기 때문에","mis":"K6-1-u1-X16"}],"mis":"K6-1-u1-X16","explanation":["해솔이는 함께 바꾸는 길을 골랐어요.","도담이는 날마다 돌을 옮겼어요.","처지가 같아도 가치는 다를 수 있어요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_d#10','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C15',2,'mc','auto','만복이 돈을 앞에 둔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X17','K6-1-u1-X22']::text[],false,'{"seq":10,"concept":"K6-1-u1-C15","difficulty":2,"kind":"mc","stem":"만복이 돈을 앞에 둔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가난한 어머니를 하루라도 빨리 모시고 싶었기 때문에","correct":true},{"t":"돈을 좇는 나쁜 성격이기 때문에","mis":"K6-1-u1-X17"},{"t":"흙 고르는 일이 무서웠기 때문에","mis":"K6-1-u1-X22"},{"t":"연수를 이기고 싶었기 때문에","mis":"K6-1-u1-X22"}],"explanation":["나쁜 성격이라고 가르지 않아요.","만복의 말에 까닭이 있어요.","어머니께 기와집을 지어 드리고 싶었어요."],"asset":{"type":"passage","lines":["만복과 연수는 같은 해에 옹기점에 들어왔다. 둘 다 집이 가난했다.","가마 어른은 두 아이에게 똑같이 수비를 맡겼다.","그날 걸러 낸 흙은 이듬해에나 그릇이 되었다.","반년이 지나도 흙만 거르자 만복은 조바심이 났다.","「흙 고르는 일이야 사람을 사서 시키면 그만 아닙니까.","저는 빨리 그릇을 빚어 팔고, 어머니께 기와집을 지어 드리고 싶습니다.」","연수는 걸러 낸 흙을 손끝으로 문질러 보는 버릇이 있었다.","어제 흙보다 오늘 흙이 곱게 걸러졌는지 알아보려는 것이었다."],"title":"이야기 「흙을 고르는 아이」 앞부분"}}'::jsonb),
('g6_1_kor_u1_review_d#11','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C10',2,'ox','auto','한 번 한 행동보다 여러 번 되풀이한 행동에서 인물이 소중히 여기는 것이 더 잘 드러나요.',ARRAY['K6-1-u1-X10']::text[],false,'{"seq":11,"concept":"K6-1-u1-C10","difficulty":2,"kind":"ox","stem":"한 번 한 행동보다 여러 번 되풀이한 행동에서 인물이 소중히 여기는 것이 더 잘 드러나요.","answer":"O","reason_options":[{"t":"처음부터 끝까지 이어지는 태도에 가치가 드러나기 때문에","correct":true},{"t":"한 번 한 행동만 보아도 가치를 정할 수 있기 때문에","mis":"K6-1-u1-X10"}],"mis":"K6-1-u1-X10","explanation":["정정화는 여러 차례 오갔어요.","연수는 날마다 흙을 살폈어요.","되풀이한 일에 주목해요."]}'::jsonb),
('g6_1_kor_u1_review_d#12','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C11',2,'mc','auto','「다시 도는 줄」의 말하는 이의 가치를 「끈기」로 본 친구와 「즐거움」으로 본 친구가 있어요. 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u1-X12','K6-1-u1-X37','K6-1-u1-X02']::text[],false,'{"seq":12,"concept":"K6-1-u1-C11","difficulty":2,"kind":"mc","stem":"「다시 도는 줄」의 말하는 이의 가치를 「끈기」로 본 친구와 「즐거움」으로 본 친구가 있어요. 알맞은 판단은 어느 것인가요?","options":[{"t":"「한 번 더」와 「싫지 않다」처럼 둘 다 시에서 근거를 찾았으므로 둘 다 좋은 답이다","correct":true},{"t":"끈기만 정답이다","mis":"K6-1-u1-X12"},{"t":"시에는 말하는 이가 없으므로 가치를 찾을 수 없다","mis":"K6-1-u1-X37"},{"t":"즐거움은 가치가 아니다","mis":"K6-1-u1-X02"}],"explanation":["끈기 — 걸려도 다시 해요.","즐거움 — 싫지 않다고 했어요.","둘 다 근거가 있어요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
('g6_1_kor_u1_review_d#13','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C17',2,'mc','auto','인물 면담에서 해솔이가 되어 답할 때 가장 알맞은 답은 어느 것인가요?',ARRAY['K6-1-u1-X20','K6-1-u1-X09','K6-1-u1-X22']::text[],false,'{"seq":13,"concept":"K6-1-u1-C17","difficulty":2,"kind":"mc","stem":"인물 면담에서 해솔이가 되어 답할 때 가장 알맞은 답은 어느 것인가요?","options":[{"t":"「신발을 벗고 건너는 동생들을 보며, 우리 모두 걱정 없이 건널 다리가 있어야겠다고 생각했어요.」","correct":true},{"t":"「저라면 그냥 돌을 옮겼을 거예요.」","mis":"K6-1-u1-X20"},{"t":"「저는 원래 개울을 건넌 적이 없어요.」","mis":"K6-1-u1-X09"},{"t":"「도담이가 미워서 편지를 썼어요.」","mis":"K6-1-u1-X22"}],"explanation":["면담은 그 인물의 처지에서 답해요.","내 생각으로 답하지 않아요.","이야기에 어울리게 답해요."],"asset":{"type":"passage","lines":["개울 건너 학교로 가는 길에 징검다리가 하나 있었다. 장마가 지나자","돌 몇 개가 떠내려가 아이들은 신발을 벗고 건너야 했다.","해솔이는 「어른들께 튼튼한 다리를 놓아 달라고 하자.」 하며","마을 회관에 보낼 편지를 쓰고 친구들의 이름을 하나하나 받으러 다녔다.","도담이는 말없이 날마다 일찍 나와 개울 바닥의 돌을 하나씩 옮겨 놓았다.","돌은 비가 오면 또 밀려났지만 도담이는 이튿날 다시 옮겼다.","가을이 되어 마을에서 다리를 놓기로 했다. 다리가 놓이는 날까지","아이들은 도담이가 놓은 돌을 밟고 학교에 갔다."],"title":"새 이야기 「징검다리」"}}'::jsonb),
('g6_1_kor_u1_review_d#14','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C26',2,'mc','auto','「정말 재미있었다. 다른 사람도 읽으면 좋겠다.」를 고친 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X30','K6-1-u1-X29']::text[],false,'{"seq":14,"concept":"K6-1-u1-C26","difficulty":2,"kind":"mc","stem":"「정말 재미있었다. 다른 사람도 읽으면 좋겠다.」를 고친 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「돌이 밀려나도 이튿날 다시 옮긴 도담이를 보며, 숙제를 미루던 내 모습이 떠올랐다.」","correct":true},{"t":"「정말 정말 재미있었다.」","mis":"K6-1-u1-X30"},{"t":"「돌이 떠내려가서 아이들이 신발을 벗었다.」","mis":"K6-1-u1-X29"},{"t":"「표지가 예뻤다.」","mis":"K6-1-u1-X30"}],"explanation":["막연한 느낌을 구체적으로 바꿔요.","근거 장면을 넣어요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["나는 「징검다리」를 읽었다. 장마 뒤에 돌이 떠내려갔다.","해솔이는 편지를 썼고, 도담이는 돌을 옮겼다.","가을에 마을에서 다리를 놓기로 했다.","정말 재미있었다. 다른 사람도 읽으면 좋겠다."],"title":"도윤이가 쓴 독서 감상문 초안"}}'::jsonb),
('g6_1_kor_u1_review_d#15','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C29',2,'mc','auto','서아가 소개 발표의 「가운데」에 넣어야 할 내용은 어느 것인가요?',ARRAY['K6-1-u1-X35','K6-1-u1-X33']::text[],false,'{"seq":15,"concept":"K6-1-u1-C29","difficulty":2,"kind":"mc","stem":"서아가 소개 발표의 「가운데」에 넣어야 할 내용은 어느 것인가요?","options":[{"t":"할아버지가 처한 상황, 말과 행동, 추구하는 가치","correct":true},{"t":"표지 그림이 예쁘다는 것","mis":"K6-1-u1-X35"},{"t":"쪽수가 많지 않다는 것","mis":"K6-1-u1-X35"},{"t":"꼭 읽어 보라는 부탁","mis":"K6-1-u1-X33"}],"explanation":["표지와 쪽수는 가치와 상관없어요.","부탁은 책 광고예요.","가운데에는 상황 · 말과 행동 · 가치를 넣어요."],"asset":{"type":"passage","lines":["제가 소개할 책은 「고치는 손」입니다. 정말 재미있어요.","표지 그림이 예쁘고 쪽수가 많지 않아서 금방 읽을 수 있어요.","할아버지는 세상에서 가장 훌륭한 사람이에요.","마지막 장면이 깜짝 놀라우니 꼭 읽어 보세요."],"title":"서아의 인물 소개 발표 초안"}}'::jsonb),
('g6_1_kor_u1_review_d#16','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C32',2,'mc','auto','이 단원을 마친 뒤 스스로 확인할 때 가장 마지막까지 해야 할 일은 어느 것인가요?',ARRAY['K6-1-u1-X39','K6-1-u1-X03']::text[],false,'{"seq":16,"concept":"K6-1-u1-C32","difficulty":2,"kind":"mc","stem":"이 단원을 마친 뒤 스스로 확인할 때 가장 마지막까지 해야 할 일은 어느 것인가요?","options":[{"t":"내가 추구하는 가치를 내 삶에서 실천할 일로 정하기","correct":true},{"t":"가치 낱말 열 개 외우기","mis":"K6-1-u1-X39"},{"t":"파악하는 방법을 아는 것으로 끝내기","mis":"K6-1-u1-X39"},{"t":"친구의 가치에 등수 매기기","mis":"K6-1-u1-X03"}],"explanation":["방법을 아는 데서 그치지 않아요.","내 삶과 이어요.","실천할 일까지 정해요."]}'::jsonb),
('g6_1_kor_u1_review_d#17','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C16',3,'mc','auto','「끈기」를 소중히 여기는 소진과 「다시 도는 줄」의 말하는 이를 비교한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X18','K6-1-u1-X37','K6-1-u1-X03']::text[],false,'{"seq":17,"concept":"K6-1-u1-C16","difficulty":3,"kind":"mc","stem":"「끈기」를 소중히 여기는 소진과 「다시 도는 줄」의 말하는 이를 비교한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소진은 밀려도 연습을 두 배로 하며 버티고, 말하는 이는 걸릴 때마다 「한 번 더」라고 다시 시작한다","correct":true},{"t":"두 사람의 끈기는 실천하는 모습까지 똑같다","mis":"K6-1-u1-X18"},{"t":"말하는 이는 시의 인물이라 가치가 없다","mis":"K6-1-u1-X37"},{"t":"소진의 끈기가 더 훌륭하다","mis":"K6-1-u1-X03"}],"explanation":["같은 끈기도 실천이 달라요.","시의 말하는 이도 가치가 있어요.","어떻게 실천하는지 봐요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
('g6_1_kor_u1_review_d#18','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C20',3,'mc','auto','윤아의 가치를 내 삶과 관련지은 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X24','K6-1-u1-X23']::text[],false,'{"seq":18,"concept":"K6-1-u1-C20","difficulty":3,"kind":"mc","stem":"윤아의 가치를 내 삶과 관련지은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나도 태권도를 오래 했지만 요즘은 그림이 더 좋다. 윤아처럼 할 만큼 해 봤는지 먼저 생각해 보고 정하겠다.」","correct":true},{"t":"「윤아는 팀파니를 친다.」","mis":"K6-1-u1-X24"},{"t":"「윤아는 참을성이 없다.」","mis":"K6-1-u1-X23"},{"t":"「윤아처럼 아무 때나 그만두면 된다.」","mis":"K6-1-u1-X23"}],"explanation":["인물 이야기만 하지 않아요.","윤아는 참을성이 없지 않았어요.","내 경험과 앞으로의 선택을 말해요."],"asset":{"type":"passage","lines":["「나는 진짜 할 만큼 해 봐서 아쉽지가 않아.」 윤아가 말했다.","「팀파니는 소리가 바닥에서 올라와. 내가 치면 강당이 같이 울려.","그게 좋아.」 말하는 윤아의 얼굴이 환했다.","「근데 너는 왜 플루트 불어?」 소진은 대답하지 못했다.","이기려고 부는 걸까. 아니면 그냥 좋아서 부는 걸까.","다음 날 아침, 소진은 평소보다 십 분 일찍 음악실 문을 열었다.","아직은 그만두고 싶지 않았다."],"title":"이야기 「한 칸 뒤에서」 뒷부분"}}'::jsonb),
('g6_1_kor_u1_review_d#19','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C27',3,'mc','auto','진아가 처음에 간판을 부끄러워한 것을 두고 친구가 「진아는 나쁜 손녀야.」라고 했어요. 알맞게 답한 말은 어느 것인가요?',ARRAY['K6-1-u1-X17','K6-1-u1-X04','K6-1-u1-X27']::text[],false,'{"seq":19,"concept":"K6-1-u1-C27","difficulty":3,"kind":"mc","stem":"진아가 처음에 간판을 부끄러워한 것을 두고 친구가 「진아는 나쁜 손녀야.」라고 했어요. 알맞게 답한 말은 어느 것인가요?","options":[{"t":"「처음엔 고치는 값이 비싸서 그렇게 느꼈지만, 장면을 따라가면 생각이 바뀌어. 어느 장면을 보고 그렇게 생각했어?」","correct":true},{"t":"「맞아, 진아는 나빠.」","mis":"K6-1-u1-X17"},{"t":"「네 생각은 틀렸어.」","mis":"K6-1-u1-X04"},{"t":"「진아의 생각은 처음부터 끝까지 똑같아.」","mis":"K6-1-u1-X27"}],"explanation":["나쁘다고 가르지 않아요.","틀렸다고 하지 않아요.","생각의 변화와 근거 장면을 물어요."],"asset":{"type":"passage","lines":["할아버지는 골목 끝에서 「무엇이든 고칩니다」 수선집을 한다.","나는 그 간판이 조금 부끄럽다. 고치는 값이 새로 사는 값보다 비쌀 때가 많다.","토요일마다 가게를 지키다 이름표 뒷면에 적힌 글씨를 보았다.","낡은 손목시계에는 「아버지 것. 소리만 나면 됩니다.」","부러진 우산에는 「첫 출근 날 산 것.」","나는 손님들이 왜 굳이 여기까지 오는지 조금 알 것 같았다."],"title":"이야기 「고치는 손」 앞부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_review_d#20','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C31',3,'match','auto','「다시 도는 줄」을 가치 파악 방법에 따라 이으세요.','{}'::text[],false,'{"seq":20,"concept":"K6-1-u1-C31","difficulty":3,"kind":"match","stem":"「다시 도는 줄」을 가치 파악 방법에 따라 이으세요.","pairs":[{"l":"처한 상황","r":"줄에 자꾸 걸려 세던 수가 처음으로 돌아감"},{"l":"말과 행동","r":"「한 번 더」라고 말하고 다시 넘음"},{"l":"그렇게 한 까닭","r":"수가 아니라 내가 한 번씩 늘어난다고 여김"}],"mis":"K6-1-u1-X13","explanation":["상황을 먼저 봐요.","말과 행동을 살펴요.","까닭을 찾아요."],"asset":{"type":"passage","lines":["넘다가 걸렸다 / 줄이 발목을 잡는다","한 번 더, 하고 말하면 / 줄은 다시 돌기 시작한다","세는 소리가 자꾸 처음으로 돌아가도 / 나는 그게 싫지 않다","숫자가 줄어드는 것이 아니라 / 내가 한 번씩 늘어나는 것이니까","오늘도 걸렸다 / 그러니까 오늘도 한 번 더"],"title":"시 「다시 도는 줄」 (/ 는 행이 바뀌는 곳)"}}'::jsonb),
('g6_1_kor_u1_review_d#21','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C27',3,'ox','auto','감상을 주고받을 때 나와 다른 생각이 나오면 근거가 된 장면을 물어보는 것이 좋아요.',ARRAY['K6-1-u1-X04']::text[],false,'{"seq":21,"concept":"K6-1-u1-C27","difficulty":3,"kind":"ox","stem":"감상을 주고받을 때 나와 다른 생각이 나오면 근거가 된 장면을 물어보는 것이 좋아요.","answer":"O","reason_options":[{"t":"같은 작품도 생각이 다를 수 있고, 근거를 알면 다른 생각도 이해할 수 있기 때문에","correct":true},{"t":"내 생각이 맞는지 이기기 위해서이기 때문에","mis":"K6-1-u1-X04"}],"mis":"K6-1-u1-X04","explanation":["생각은 서로 달라요.","틀렸다고 하지 않아요.","장면을 물으며 예의 바르게 나눠요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 해솔이가 「함께함」을 소중히 여긴다고 봤어. 친구들 이름을 하나하나 받으러 다녔잖아."},{"who":"지우","text":"그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해."},{"who":"시온","text":"나는 도담이가 「꾸준함」을 앞에 둔다고 봤어. 돌이 밀려나도 이튿날 다시 옮겼으니까."},{"who":"나윤","text":"시온아, 어느 장면에서 그렇게 생각했는지 더 말해 줄래? 나는 「책임」으로 봤거든."}]}}'::jsonb),
('g6_1_kor_u1_review_d#22','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C25',3,'mc','auto','「고치는 손」을 읽고 「나라면 고칠까, 새로 살까」를 생각할 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u1-X03','K6-1-u1-X28']::text[],false,'{"seq":22,"concept":"K6-1-u1-C25","difficulty":3,"kind":"mc","stem":"「고치는 손」을 읽고 「나라면 고칠까, 새로 살까」를 생각할 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"정답을 찾기보다 어떤 때 고치고 어떤 때 새로 살지 까닭을 들어 정한다","correct":true},{"t":"고치는 것이 언제나 옳다","mis":"K6-1-u1-X03"},{"t":"새로 사는 것이 언제나 쉽다","mis":"K6-1-u1-X28"},{"t":"할아버지가 고치니까 나도 무조건 고친다","mis":"K6-1-u1-X28"}],"explanation":["정답은 없어요.","까닭이 있으면 돼요.","그에 따르는 어려움까지 생각해요."],"asset":{"type":"passage","lines":["어떤 날은 할아버지가 고치지 않고 돌려보냈다.","「고쳐도 오래 못 씁니다. 값도 새것과 비슷해요. 새로 사시는 게 낫겠습니다.」","「고치는 게 늘 옳은 건 아니야. 손님한테 손해가 되면 그건 고집이지 정성이 아니다.」","겨울이 오기 전, 나는 돌아가신 할머니가 쓰던 탁상시계를 들고 갔다.","할아버지가 아주 작은 나사 하나를 갈아 끼우자 시계가 다시 돌았다.","「이건 시계를 고친 게 아니라 시간을 고친 거다.」","나는 그날 간판을 다시 보았다. 이제는 부끄럽지 않았다."],"title":"이야기 「고치는 손」 뒷부분 (말하는 이 = 진아)"}}'::jsonb),
('g6_1_kor_u1_review_d#23','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C32',4,'mc','auto','세 친구의 다짐을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u1-X25','K6-1-u1-X03','K6-1-u1-X39']::text[],false,'{"seq":23,"concept":"K6-1-u1-C32","difficulty":4,"kind":"mc","stem":"세 친구의 다짐을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다인이는 언제 · 무엇을 할지 적어 실천할 수 있고, 주원이와 태오는 할 일을 구체적으로 고쳐야 한다","correct":true},{"t":"주원이의 다짐이 가장 크고 멋있으니 가장 좋다","mis":"K6-1-u1-X25"},{"t":"태오는 배려를 골랐으니 가장 훌륭하다","mis":"K6-1-u1-X03"},{"t":"셋 다 가치 낱말을 적었으니 모두 알맞다","mis":"K6-1-u1-X39"}],"explanation":["다짐의 크기로 재지 않아요.","가치에 등수를 매기지 않아요.","언제 · 무엇을 할지가 드러나야 해요."],"asset":{"type":"speech","turns":[{"who":"주원","text":"가치: 끈기 / 할 일: 앞으로 무슨 일이든 열심히 하겠다."},{"who":"다인","text":"가치: 책임 / 할 일: 이번 주 모둠 관찰 기록을 금요일까지 날마다 빠짐없이 적기."},{"who":"태오","text":"가치: 배려 / 할 일: 착한 사람이 되겠다."}]}}'::jsonb),
('g6_1_kor_u1_review_d#24','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C27',4,'essay','teacher','감상 나누기 대화에서 알맞지 않은 말을 고르고 왜 알맞지 않은지 쓴 뒤, 그 친구가 할 수 있는 알맞은 말로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u1-C27","difficulty":4,"kind":"essay","stem":"감상 나누기 대화에서 알맞지 않은 말을 고르고 왜 알맞지 않은지 쓴 뒤, 그 친구가 할 수 있는 알맞은 말로 고쳐 쓰세요.","answer_guide":{"answer":"예: 지우의 「그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해.」가 알맞지 않다. 하람이는 친구들의 이름을 받으러 다닌 장면을 근거로 들었으므로 틀린 생각이 아니고, 두 인물에 등수를 매기는 말이기 때문이다. 고친 말 — 「하람이는 이름 받는 장면을 보고 그렇게 생각했구나. 나는 돌을 날마다 옮긴 도담이가 더 마음에 남았어. 너는 해솔이의 어떤 점이 가장 기억에 남았어?」","scoring_points":["알맞지 않은 말을 바르게 골랐는가","틀렸다고 함 · 등수를 매김을 까닭으로 썼는가","근거 장면을 인정하거나 묻는 말로 고쳤는가"]},"explanation":["누가 「틀렸다」고 했는지 찾아요.","왜 알맞지 않은지 써요.","장면을 묻는 말로 고쳐요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 해솔이가 「함께함」을 소중히 여긴다고 봤어. 친구들 이름을 하나하나 받으러 다녔잖아."},{"who":"지우","text":"그건 틀렸어. 해솔이는 그냥 말만 했잖아. 도담이가 훨씬 훌륭해."},{"who":"시온","text":"나는 도담이가 「꾸준함」을 앞에 둔다고 봤어. 돌이 밀려나도 이튿날 다시 옮겼으니까."},{"who":"나윤","text":"시온아, 어느 장면에서 그렇게 생각했는지 더 말해 줄래? 나는 「책임」으로 봤거든."}]}}'::jsonb),
('g6_1_kor_u1_review_d#25','kor',6,1,'u1','','g6_1_kor_u1_review_d','unit_review','K6-1-u1-C33',4,'essay','teacher','「개선하다 · 적용하다 · 종합하다」 가운데 두 낱말을 넣어, 이 단원에서 배운 것을 내 삶에서 어떻게 쓸지 짧은 글로 쓰고 두 낱말의 뜻을 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u1-C33","difficulty":4,"kind":"essay","stem":"「개선하다 · 적용하다 · 종합하다」 가운데 두 낱말을 넣어, 이 단원에서 배운 것을 내 삶에서 어떻게 쓸지 짧은 글로 쓰고 두 낱말의 뜻을 설명하세요.","answer_guide":{"answer":"예: 나는 인물이 추구하는 가치를 파악하는 방법을 친구 사이의 다툼에도 적용해 보겠다. 친구가 왜 그렇게 말했는지 상황과 까닭부터 생각하면 다투는 일이 줄 것이다. 그리고 숙제를 미루는 버릇을 개선하려고 이번 주에는 집에 오자마자 숙제부터 하겠다. 「적용하다」는 알맞게 이용하거나 맞추어 쓴다는 뜻이고, 「개선하다」는 부족한 것을 고쳐 더 좋게 만든다는 뜻이다.","scoring_points":["두 낱말을 알맞은 자리에 넣었는가","배운 것을 내 삶과 이어 썼는가","두 낱말의 뜻을 바르게 설명했는가"]},"explanation":["두 낱말을 골라요.","내 삶에서 쓸 곳을 떠올려요.","뜻을 바르게 설명해요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-1-u2-C1','kor',6,1,'u2',1,'고쳐쓰기의 뜻 — 쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일로, 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일이 아니다',ARRAY['6국03-06 쓰기']::text[],1),
('K6-1-u2-C2','kor',6,1,'u2',1,'고쳐쓰기의 네 가지 일 — 주제에서 벗어난 내용 빼기 · 부족한 내용 더하기 · 어색한 표현을 알맞은 말로 바꾸기 · 순서가 뒤엉킨 부분 옮기기를 필요한 곳에만 하며, 친구 글을 고칠 때에는 다시 짜기까지 다섯 가지로 볼 수 있다',ARRAY['6국04-06 문법']::text[],2),
('K6-1-u2-C3','kor',6,1,'u2',1,'세 수준으로 보기와 큰 것부터 — 고쳐 쓸 때에는 글 수준(제목과 내용 · 처음 · 가운데 · 끝의 흐름) · 문단 수준(중심 문장 · 어울리지 않는 뒷받침 문장) · 문장 수준(호응 · 띄어쓰기)의 세 크기로 보며, 글 → 문단 → 문장의 차례로 큰 것부터 살펴야 헛수고가 줄어든다',ARRAY['6국04-06 문법']::text[],3),
('K6-1-u2-C4','kor',6,1,'u2',1,'고쳐 쓴 글을 나누는 까닭 — 고쳐 쓴 글을 게시판 등에 올려 다른 사람과 나누면 내가 못 본 곳을 친구가 짚어 주고, 읽는 사람의 반응을 바로 알 수 있으며, 읽는 사람이 있다고 생각하면 문장을 더 꼼꼼히 보게 되어 고쳐쓰기에 큰 도움이 된다',ARRAY['6국03-06 쓰기']::text[],4),
('K6-1-u2-C5','kor',6,1,'u2',1,'친구 글에 의견을 말하는 방법 — 같은 내용이라도 말하는 방식에 따라 듣는 사람의 마음이 달라지므로, 잘한 곳을 먼저 말하고 고칠 곳은 반드시 까닭과 함께 말해(잘한 곳 → 고칠 곳 → 까닭) 글쓴이가 다시 고쳐 쓰고 싶어지게 한다',ARRAY['6국03-06 쓰기']::text[],5),
('K6-1-u2-C6','kor',6,1,'u2',1,'온라인에 글을 올릴 때 지킬 것 — 여러 사람이 읽고 의견을 주고 고치기 쉬우며 사진 · 영상도 함께 올릴 수 있지만, 한 번 올린 글은 널리 퍼지므로 줄임말 · 은어 · 비속어를 쓰지 않고 자료를 옮길 때에는 출처를 밝히며 읽는 사람이 누구인지 떠올리며 쓴다',ARRAY['6국03-06 쓰기']::text[],6),
('K6-1-u2-C7','kor',6,1,'u2',1,'고쳐쓰기는 혼나는 일이 아니다 — 고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이 아니라 여기만 손보면 하고 싶은 말이 더 잘 전해진다는 뜻이며, 완벽한 글을 만드는 일이 아니므로 한 군데를 고쳤으면 그만큼 나아진 것이고 작게 고친 것도 잘 고친 것이다',ARRAY['6국03-06 쓰기']::text[],7),
('K6-1-u2-C8','kor',6,1,'u2',2,'제목이 내용을 나타내는가 — 글 수준에서 제목에 글의 내용과 중심 생각, 글쓴이가 느낀 것이 드러나는지 보며(「모래성 이야기」 → 「무너져도 다시 손을 대는 힘」), 글을 다 쓴 뒤 가장 하고 싶었던 말을 한 줄로 적어 제목으로 옮겨 본다',ARRAY['6국04-06 문법']::text[],8),
('K6-1-u2-C9','kor',6,1,'u2',2,'처음 · 가운데 · 끝의 흐름 — 감상문은 처음(무엇을 보았는지 · 왜 보게 되었는지) → 가운데(간단한 줄거리 · 인상 깊은 장면과 그때의 생각) → 끝(느낀 점이나 다짐)으로 이어지며, 차례가 뒤엉켰으면 내용은 그대로 두고 문단의 차례만 옮겨도 글이 훨씬 잘 읽힌다',ARRAY['6국04-06 문법']::text[],9),
('K6-1-u2-C10','kor',6,1,'u2',2,'중심 내용은 근거가 있으면 여럿 — 같은 글의 중심 내용도 사람마다 조금씩 다르게 말할 수 있어(다시 시작하는 힘 · 함께하면 더 오래 버틴다), 물어야 할 것은 「정답인가」가 아니라 글에서 근거를 댈 수 있는가이다',ARRAY['6국04-06 문법']::text[],10),
('K6-1-u2-C11','kor',6,1,'u2',2,'중심 문장과 뒷받침 문장 — 문단에는 하고 싶은 말을 담은 중심 문장(보통 하나)과 그것을 자세히 설명하거나 예를 드는 뒷받침 문장이 있으며, 문단을 고칠 때에는 먼저 중심 문장을 찾고 뒷받침 문장 가운데 중심 문장과 상관없는 것이 있는지 본다',ARRAY['6국04-06 문법']::text[],11),
('K6-1-u2-C12','kor',6,1,'u2',2,'거리가 먼 문장은 빼거나 고쳐 쓴다 — 중심 문장과 아무 관련이 없으면 지우고(우리 집 강아지도 모래를 좋아한다 → 삭제), 관련은 있는데 표현이 어긋났으면 바꾸어(여름 내내 쌓았다 → 여름 내내 모래성을 쌓았다) 무조건 지우지 않고 지울지 고칠지부터 정한다',ARRAY['6국04-06 문법']::text[],12),
('K6-1-u2-C13','kor',6,1,'u2',2,'문장 성분과 호응 — 주어(무엇이 · 누가) · 목적어(무엇을 · 누구를) · 서술어(어찌하다 · 어떠하다)가 서로 어울리는 것을 호응이라 하며, 내용이 아무리 좋아도 호응이 어긋나면 뜻이 제대로 전해지지 않으므로 고쳐 쓸 때에는 내용과 형식을 함께 본다',ARRAY['6국04-04 문법']::text[],13),
('K6-1-u2-C14','kor',6,1,'u2',2,'호응이 어긋나는 네 가지 — 높임(선생님이 소개했다 → 선생님께서 소개해 주셨다) · 피동과 사동(성이 파도에 무너뜨렸다 → 무너졌다) · 시제(어제 볼 것이다 → 어제 보았다) · 부정(전혀 지루했다 → 전혀 지루하지 않았다)에서 자주 어긋나며, 서술어를 짚고 앞의 말과 어울리는지 소리 내어 읽어 찾는다',ARRAY['6국04-04 문법']::text[],14),
('K6-1-u2-C15','kor',6,1,'u2',2,'세 수준은 따로 도는 절차가 아니다 — 큰 흐름을 손보다 보면 문단이, 문단을 손보다 보면 문장이 보이므로 어느 수준에서 발견하든 그때그때 함께 고치며, 고칠 때 쓰는 부호(∨ 띄어 쓸 때 · ⌒ 붙여 쓸 때 · ⊂ 내용을 더 넣을 때)를 쓰면 지우고 다시 옮겨 쓸 필요가 없다',ARRAY['6국04-06 문법']::text[],15),
('K6-1-u2-C16','kor',6,1,'u2',4,'띄어쓰기는 뜻을 가르는 일 — 같은 글자도 어디서 띄느냐에 따라 전혀 다른 말이 되므로(오늘 밤 나무를 심자 · 오늘 밤나무를 심자 / 큰 집 · 큰집 / 잘 못했다 · 잘못했다), 띄어쓰기는 글씨를 예쁘게 쓰는 일이 아니라 읽는 사람이 글쓴이의 뜻을 알아내게 하는 일이다',ARRAY['6국04-06 문법']::text[],16),
('K6-1-u2-C17','kor',6,1,'u2',4,'수와 세는 말은 띄어 쓴다 — 권 · 마리 · 원 · 그루 · 장 · 잔 · 자루 · 개처럼 세는 말(단위를 나타내는 말)은 앞의 수와 띄어 쓴다(책 세 권 · 나무 두 그루 · 삼천 원 · 종이 스물네 장)',ARRAY['6국04-06 문법']::text[],17),
('K6-1-u2-C18','kor',6,1,'u2',4,'잇거나 나열하는 말은 띄어 쓴다 — 및 · 대 · 겸 · 등처럼 두 말 사이를 잇거나 나열하는 말은 앞뒤를 모두 띄어 쓴다(학생 및 학부모 · 청군 대 백군 · 서점 겸 찻집 · 연필이나 볼펜 등)',ARRAY['6국04-06 문법']::text[],18),
('K6-1-u2-C19','kor',6,1,'u2',4,'조사는 붙이고 홀로 못 쓰는 이름씨는 띄운다 — 이/가 · 을/를 · 은/는 · 에서 · 에게 · 도 · 만 · 처럼 같은 조사는 앞말에 붙여 쓰고(나무처럼), 것 · 수 · 데 · 지 · 만큼처럼 홀로 못 쓰는 이름씨는 띄어 쓰며(할 수 있다), 헷갈리면 앞말에 얹혀 가는 말인지 따로 뜻을 가진 말인지 물어본다',ARRAY['6국04-06 문법']::text[],19),
('K6-1-u2-C20','kor',6,1,'u2',4,'내 띄어쓰기 습관을 점검하기 — 띄어 쓸 곳은 ∨ 부호로 표시해 두고 마지막에 한 번에 옮기면 고칠 곳이 많아도 처음부터 다시 쓸 필요가 없으며, 내가 자주 놓치는 띄어쓰기 한 가지를 스스로 정해 다음 글부터 챙긴다',ARRAY['6국04-06 문법']::text[],20),
('K6-1-u2-C21','kor',6,1,'u2',5,'감상문과 줄거리 요약 — 줄거리 요약은 무슨 일이 일어났는지만 적어 누가 써도 거의 같은 글이 되지만, 감상문은 본 것에 더해 내가 무엇을 느끼고 생각했는지를 적어 쓴 사람마다 다른 글이 된다',ARRAY['6국03-06 쓰기']::text[],21),
('K6-1-u2-C22','kor',6,1,'u2',5,'인상 깊은 장면과 그 까닭 — 감상문의 출발점은 마음에 남은 한 장면이며, 「이 장면이 좋았다」로 끝내지 않고 왜 그 장면이 남았는지(각자 우산을 쓰는데도 둘이 더 가까워 보여서 · 도움을 받는 게 왜 어려웠을지 생각하게 돼서)까지 적어야 감상문이 된다',ARRAY['6국03-06 쓰기']::text[],22),
('K6-1-u2-C23','kor',6,1,'u2',5,'감상문에 담을 내용과 짜임 — 보게 된 동기 · 간단한 줄거리 · 인상 깊은 장면과 까닭 · 느낀 점이나 다짐을 담고, 처음(무엇을 · 어떻게 보게 되었는지) → 가운데(줄거리는 짧게, 장면과 생각은 길게 — 가장 긺) → 끝(느낀 점과 앞으로 하고 싶은 일)으로 짜며, 모든 장면이나 상관없는 자잘한 것은 넣지 않는다',ARRAY['6국03-06 쓰기']::text[],23),
('K6-1-u2-C24','kor',6,1,'u2',5,'고칠 차례 — 큰 것부터, 고르게 — 초고를 고칠 때에는 제목과 글 전체의 흐름부터 잡고(문장을 다 다듬었는데 그 문장이 통째로 빠져야 하면 헛수고) 문단 → 문장 차례로 고르게 살피며, 맞춤법 · 띄어쓰기는 마지막에 하는 일이라 그것만 바로잡거나 낱말 몇 개만 바꾸는 것으로 고쳐쓰기가 끝나지 않는다',ARRAY['6국04-06 문법']::text[],24),
('K6-1-u2-C25','kor',6,1,'u2',7,'명확한 문장의 세 가지 조건 — 한 문장에는 한 가지만 담고(길면 나눔) · 주어 · 목적어 · 서술어 가운데 빠진 것이 없게 하고 · 겹치는 표현은 하나로 줄이면(되풀이되던 「번호」 → 숫자 · 표시) 글자 수는 줄어도 뜻은 더 또렷해져 읽는 사람이 두 번 읽지 않아도 된다',ARRAY['6국04-04 문법']::text[],25),
('K6-1-u2-C26','kor',6,1,'u2',7,'말과 달리 글에서는 필수 성분을 갖춘다 — 말할 때에는 서로 아는 것이 많아 주어와 목적어를 빼도 통하지만(여기 있어. 아까 찾던 거.), 읽는 사람은 그 자리에 없었으므로 글에서는 주어 · 목적어 · 서술어 같은 필수 성분을 갖춰야 뜻이 전해진다',ARRAY['6국04-04 문법']::text[],26),
('K6-1-u2-C27','kor',6,1,'u2',7,'주제와 제목 정하기 — 좋은 주제는 친구들이 궁금해할 만하고 내가 끝까지 자료를 모을 수 있는 것이며(너무 넓거나 자료를 거의 찾을 수 없는 것은 어렵다), 제목은 내용과 일치하고 짧으면서 읽는 사람의 관심을 끌어야 하므로 주제를 정한 다음에 정한다',ARRAY['6국03-06 쓰기']::text[],27),
('K6-1-u2-C28','kor',6,1,'u2',7,'믿을 수 있는 자료와 출처 — 자료는 누가 만들었는지(믿을 수 있는가) · 언제 만들었는지(지금도 맞는가) · 어디서 가져왔는지(출처를 밝혔는가)를 확인하며, 누가 언제 썼는지 알 수 없는 글이나 어디선가 들었다는 이야기처럼 확인하지 않은 자료는 쓰지 않는다',ARRAY['6국03-06 쓰기']::text[],28),
('K6-1-u2-C29','kor',6,1,'u2',7,'설명하는 글의 짜임 — 처음(무엇을 설명할지 밝히고 관심을 끎) → 가운데(설명하려는 내용을 알기 쉽고 자세하게 — 무엇을 나타내는지 · 나누는 방법의 예 · 찾는 차례) → 끝(전체 내용을 간추리고 마무리)으로 짜며, 쓰기 전에 세 칸을 한 줄씩 채워 두면 글이 흩어지지 않는다',ARRAY['6국03-06 쓰기']::text[],29),
('K6-1-u2-C30','kor',6,1,'u2',7,'찾은 자료는 내 말로 바꾸어 쓴다 — 찾은 자료를 그대로 붙여 넣는 것은 글쓰기가 아니며 읽고 이해한 뒤 내 말로 다시 쓰고, 읽는 사람이 아는 말로 풀어 쓰며 줄임말 · 은어 · 비속어를 쓰지 않고 가져온 곳을 함께 적으며, 디지털 매체로 쓸 때에는 자주 저장하고 내용과 이어지는 그림만 넣는다',ARRAY['6국03-06 쓰기']::text[],30),
('K6-1-u2-C31','kor',6,1,'u2',9,'친구 글에 대한 의견의 네 갈래 — 친구 글은 먼저 무슨 말을 하려는 글인지 한 줄로 잡은 뒤, 새롭게 안 점(몰랐는데 알게 된 것) · 궁금한 점(더 알고 싶은 것) · 좋은 점(잘 쓴 곳과 까닭) · 고쳤으면 하는 점(고칠 곳과 까닭)으로 나누어 「그냥 좋아」나 「별로야」로 끝나지 않게 한다',ARRAY['6국03-06 쓰기']::text[],31),
('K6-1-u2-C32','kor',6,1,'u2',9,'의견은 골라서 받아들인다 — 의견은 받는 것이고 고르는 것은 글쓴이이므로 친구의 의견을 모두 따를 필요는 없으며, 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」를 기준으로 고르고 따르지 않기로 했다면 그 까닭을 스스로 말할 수 있으면 된다',ARRAY['6국03-06 쓰기']::text[],32),
('K6-1-u2-C33','kor',6,1,'u2',9,'공유하는 차례와 좋은 점 — 고쳐 쓴 마지막 글을 올리고 → 제대로 올라갔는지 확인하고 → 친구 글에 댓글을 달고 → 내 글에 달린 댓글을 읽고 다시 점검하며, 댓글에는 읽었다는 것과 어떻게 했는지를 답글로 알린다; 공유하면 혼자서는 놓친 곳 · 내 글이 어떻게 읽히는지 · 새로운 생각을 얻는다',ARRAY['6국03-06 쓰기']::text[],33),
('K6-1-u2-C34','kor',6,1,'u2',9,'맞춤법 검사기와 인공 지능 도구 — 띄어쓰기와 맞춤법을 빠르게 짚어 주고 내가 자주 틀리는 곳을 알게 해 주지만, 글의 중심 생각은 도구가 정해 주지 못하고 고칠지 말지는 글쓴이가 정하며, 도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다',ARRAY['6국04-06 문법']::text[],34),
('K6-1-u2-C35','kor',6,1,'u2',9,'사진과 영상도 글의 한 부분 — 글에 넣은 사진 · 영상이 설명하는 내용을 바로 보여 주는지(책등의 숫자가 보이는 서가 사진) 겉도는지(도서관 건물 바깥 풍경) 점검하며, 내용과 이어지지 않으면 보기 좋아도 빼는 것이 고쳐쓰기다',ARRAY['6국03-06 쓰기']::text[],35),
('K6-1-u2-C36','kor',6,1,'u2',12,'소개하는 글 — 고르기와 짜임 — 물건 · 작품(감상문 형식) · 알게 된 것(설명하는 형식) 가운데 쓸 말이 세 문단쯤 나오는 것을 고르고, 처음(무엇을 소개할지 · 왜 골랐는지) → 가운데(어떤 것인지 자세히 · 나와 얽힌 그것만의 이야기) → 끝(소개를 맺으며 앞으로 하고 싶은 일)으로 쓴다',ARRAY['6국03-06 쓰기']::text[],36),
('K6-1-u2-C37','kor',6,1,'u2',12,'소개는 자랑이 아니다 — 「내 자전거가 제일 좋다」처럼 쓰면 읽는 사람이 알 수 있는 것이 없으므로 「손잡이가 손 모양대로 닳아서 잡으면 손이 딱 맞는다」처럼 읽는 사람이 그려 볼 수 있게 쓰며, 친구 글에는 잘한 곳을 짚고 부족한 곳은 까닭과 함께 알려 주며 글을 조금씩 나아지게 한다',ARRAY['6국03-06 쓰기']::text[],37),
('K6-1-u2-C38','kor',6,1,'u2',12,'시간 표현 · 주어와 서술어의 짝 — 어제 · 지난주 · 아까는 「보았다」, 오늘 · 지금은 「본다」, 내일 · 다음 주는 「볼 것이다」처럼 시간을 나타내는 말이 앞에 나오면 서술어가 끌려가고, 주어가 「내 생각은」이면 「~것이다」로, 주어가 스스로 한 일이 아니면 「~되다 · ~히다」로 받는다(화면이 어둠으로 채워졌다)',ARRAY['6국04-04 문법']::text[],38),
('K6-1-u2-C39','kor',6,1,'u2',12,'주동과 피동 — 주체가 스스로 하는 일은 주동(내가 문을 닫다 · 그림을 걸다 · 책을 놓다), 다른 힘에 의해 그리 되는 일은 피동(문이 닫히다 · 그림이 걸리다 · 책이 놓이다)으로 쓰며, 스스로 하는 일에는 -히- · -리- · -이-를 붙이지 않는다 (기초 다지기)',ARRAY['기초 다지기(주동과 피동)']::text[],39)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-1-u2-X01','kor',6,'u2',ARRAY['K6-1-u2-C1']::text[],'고쳐쓰기를 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일로 여긴다','필요한 곳만 손보기'),
('K6-1-u2-X02','kor',6,'u2',ARRAY['K6-1-u2-C7']::text[],'고쳐 쓰라는 말을 내 글이 잘못됐다는 뜻으로 여겨 통째로 다시 쓰거나, 완벽하게 고쳐야 하며 작게 고친 것은 소용없다고 여긴다','작게 고친 것도 잘 고친 것'),
('K6-1-u2-X03','kor',6,'u2',ARRAY['K6-1-u2-C2']::text[],'빼기 · 더하기 · 바꾸기 · 옮기기를 서로 헷갈리거나, 고칠 필요가 없는 곳까지 손본다','필요한 곳에 알맞은 손질'),
('K6-1-u2-X04','kor',6,'u2',ARRAY['K6-1-u2-C3']::text[],'살필 일이 글 · 문단 · 문장 가운데 어느 수준의 일인지 헷갈린다','글 전체? 문단 하나? 한 문장?'),
('K6-1-u2-X05','kor',6,'u2',ARRAY['K6-1-u2-C3','K6-1-u2-C24']::text[],'띄어쓰기 · 맞춤법부터 손대거나, 그것만 바로잡고 낱말 몇 개만 바꾸면 고쳐쓰기가 끝났다고 여긴다','큰 것부터, 맞춤법은 마지막'),
('K6-1-u2-X06','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳만 늘어놓거나 「다시 써」처럼 글쓴이를 위축시키는 말로 의견을 말한다','잘한 곳을 먼저'),
('K6-1-u2-X07','kor',6,'u2',ARRAY['K6-1-u2-C5','K6-1-u2-C31']::text[],'「다 좋아, 고칠 곳 하나도 없어」처럼 막연한 칭찬만 해 글쓴이에게 쓸모 있는 말을 주지 못한다','어디가 왜 좋은지'),
('K6-1-u2-X08','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳을 까닭 없이 「여기 고쳐」라고만 말한다','고칠 곳은 까닭과 함께'),
('K6-1-u2-X09','kor',6,'u2',ARRAY['K6-1-u2-C6','K6-1-u2-C30']::text[],'온라인에 줄임말 · 은어 · 비속어를 쓰거나, 남의 자료를 출처를 밝히지 않고 옮긴다','한 번 올린 글은 널리 퍼져요'),
('K6-1-u2-X10','kor',6,'u2',ARRAY['K6-1-u2-C4','K6-1-u2-C33']::text[],'글을 나누는 것을 칭찬받는 일로 여기거나, 나누면 더 고치지 않아도 된다고 여긴다','못 본 곳을 알게 되는 일'),
('K6-1-u2-X11','kor',6,'u2',ARRAY['K6-1-u2-C8','K6-1-u2-C27']::text[],'제목은 글감이나 줄거리만 알리면 된다고 여겨 중심 생각이나 느낀 것을 담지 않는다','가장 하고 싶었던 말'),
('K6-1-u2-X12','kor',6,'u2',ARRAY['K6-1-u2-C9','K6-1-u2-C23','K6-1-u2-C29']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 뒤섞거나 문단의 차례를 뒤엉킨 채 둔다','처음 · 가운데 · 끝'),
('K6-1-u2-X13','kor',6,'u2',ARRAY['K6-1-u2-C10']::text[],'글의 중심 내용은 정답이 하나뿐이라고 여기거나, 근거 없이 중심 내용을 정한다','근거를 댈 수 있는가'),
('K6-1-u2-X14','kor',6,'u2',ARRAY['K6-1-u2-C11']::text[],'중심 문장과 뒷받침 문장을 서로 헷갈린다','하고 싶은 말 / 자세히 설명'),
('K6-1-u2-X15','kor',6,'u2',ARRAY['K6-1-u2-C11','K6-1-u2-C12']::text[],'주제나 중심 문장과 상관없는 문장을 그대로 둔다','중심 문장과 이어지나?'),
('K6-1-u2-X16','kor',6,'u2',ARRAY['K6-1-u2-C12']::text[],'중심 문장과 관련은 있는데 표현만 어긋난 문장까지 무조건 지운다','뺄지 고칠지부터'),
('K6-1-u2-X17','kor',6,'u2',ARRAY['K6-1-u2-C13']::text[],'내용만 좋으면 문장 성분의 호응이 어긋나도 뜻이 전해진다고 여긴다','내용과 형식을 함께'),
('K6-1-u2-X18','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'웃어른이 주어인데 높임 표현으로 받지 않는다(선생님이 소개했다 · 아버지가 물려줬다)','께서 · ~시다'),
('K6-1-u2-X19','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C39']::text[],'당하는 말을 써야 할 곳에 시키거나 스스로 하는 말을 쓴다(성이 파도에 무너뜨렸다)','누가 한 일인가?'),
('K6-1-u2-X20','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C38']::text[],'시간을 나타내는 말과 서술어의 때를 어긋나게 쓴다(어제 볼 것이다)','어제 → 보았다'),
('K6-1-u2-X21','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'「전혀 · 조금도 · 별로」 같은 말 뒤에 부정하는 서술어를 쓰지 않는다(전혀 지루했다)','전혀 → ~지 않다'),
('K6-1-u2-X22','kor',6,'u2',ARRAY['K6-1-u2-C15']::text[],'글 · 문단 · 문장 수준을 따로따로 세 번 차례대로 도는 절차로 여겨 발견한 것을 미뤄 둔다','보이는 그때그때 함께'),
('K6-1-u2-X23','kor',6,'u2',ARRAY['K6-1-u2-C15','K6-1-u2-C20']::text[],'고칠 때 쓰는 부호(∨ · ⌒ · ⊂)의 쓰임을 서로 헷갈린다','띄움 · 붙임 · 더 넣음'),
('K6-1-u2-X24','kor',6,'u2',ARRAY['K6-1-u2-C16']::text[],'띄어쓰기를 뜻과 상관없는 글씨 문제로 여겨 조금 틀려도 읽는 사람이 다 알아듣는다고 여긴다','한 칸이 뜻을 갈라요'),
('K6-1-u2-X25','kor',6,'u2',ARRAY['K6-1-u2-C17']::text[],'권 · 마리 · 장 · 개 같은 세는 말을 앞의 수에 붙여 쓴다','수 ∨ 세는 말'),
('K6-1-u2-X26','kor',6,'u2',ARRAY['K6-1-u2-C18']::text[],'및 · 대 · 겸 · 등 같은 잇거나 나열하는 말을 앞말이나 뒷말에 붙여 쓴다','잇는 말 앞뒤를 띄워요'),
('K6-1-u2-X27','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'이/가 · 을/를 · 처럼 · 에게 같은 조사를 앞말과 띄어 쓴다','조사는 앞말에 얹혀 가요'),
('K6-1-u2-X28','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'것 · 수 · 데 · 지 · 만큼 같은 홀로 못 쓰는 이름씨를 앞말에 붙여 쓴다','할 ∨ 수 ∨ 있다'),
('K6-1-u2-X29','kor',6,'u2',ARRAY['K6-1-u2-C20']::text[],'띄어 쓸 곳이 많으면 지우고 처음부터 옮겨 쓰거나, 내가 자주 놓치는 곳을 정해 두지 않고 규칙만 외우면 된다고 여긴다','∨ 로 표시 · 내 버릇 한 가지'),
('K6-1-u2-X30','kor',6,'u2',ARRAY['K6-1-u2-C21']::text[],'감상문을 무슨 일이 일어났는지만 적는 줄거리 요약으로 여긴다','내가 느끼고 생각한 것'),
('K6-1-u2-X31','kor',6,'u2',ARRAY['K6-1-u2-C22']::text[],'인상 깊은 장면을 고르고 「좋았다 · 재미있었다」로 끝내 왜 그 장면이 남았는지 쓰지 않는다','왜 그 장면이 남았나?'),
('K6-1-u2-X32','kor',6,'u2',ARRAY['K6-1-u2-C23']::text[],'감상문에 모든 장면이나 옷 색깔 같은 상관없는 자잘한 것을 넣고, 줄거리를 길게 늘어놓는다','줄거리는 짧게, 생각은 길게'),
('K6-1-u2-X33','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'한 문장에 여러 가지를 이어 붙여 길게 쓴다','한 문장에 한 가지'),
('K6-1-u2-X34','kor',6,'u2',ARRAY['K6-1-u2-C26','K6-1-u2-C25']::text[],'글에서도 말할 때처럼 주어 · 목적어 · 서술어를 빼고 쓴다','읽는 사람은 그 자리에 없었어요'),
('K6-1-u2-X35','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'같은 낱말이나 겹치는 표현을 되풀이해 쓴다','겹치는 것은 하나로'),
('K6-1-u2-X36','kor',6,'u2',ARRAY['K6-1-u2-C27','K6-1-u2-C36']::text[],'너무 넓거나 쓸 말 · 자료가 거의 없는 주제를 고르거나, 내용과 다른 제목을 단다','끝까지 쓸 수 있는 주제'),
('K6-1-u2-X37','kor',6,'u2',ARRAY['K6-1-u2-C28']::text[],'누가 언제 만들었는지 모르는 자료나 어디선가 들은 이야기를 확인하지 않고 쓴다','누가 · 언제 · 어디서'),
('K6-1-u2-X38','kor',6,'u2',ARRAY['K6-1-u2-C30']::text[],'찾은 자료를 이해하지 않고 그대로 옮겨 붙여도 내 글이 된다고 여긴다','내 말로 바꾸어 쓰기'),
('K6-1-u2-X39','kor',6,'u2',ARRAY['K6-1-u2-C31']::text[],'친구의 말이 새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점 가운데 어느 갈래인지 헷갈린다','알게 됨? 궁금함? 잘함? 고칠 곳?'),
('K6-1-u2-X40','kor',6,'u2',ARRAY['K6-1-u2-C32']::text[],'친구가 말한 의견은 모두 따라 고쳐야 한다고 여긴다','고르는 것은 글쓴이'),
('K6-1-u2-X41','kor',6,'u2',ARRAY['K6-1-u2-C33']::text[],'글을 올린 뒤 확인하지 않거나, 달린 댓글을 읽고 답글을 달거나 다시 점검하지 않고 끝낸다','올리고 → 확인 → 댓글 → 다시 점검'),
('K6-1-u2-X42','kor',6,'u2',ARRAY['K6-1-u2-C34']::text[],'맞춤법 검사기나 인공 지능 도구가 고친 곳을 까닭 확인 없이 받아들이거나, 도구가 중심 생각까지 정해 준다고 여긴다','고칠지 말지는 글쓴이가'),
('K6-1-u2-X43','kor',6,'u2',ARRAY['K6-1-u2-C35','K6-1-u2-C30']::text[],'보기 좋은 사진 · 영상을 글의 내용과 상관없이 넣는다','내용과 이어지나?'),
('K6-1-u2-X44','kor',6,'u2',ARRAY['K6-1-u2-C37']::text[],'소개하는 글을 자랑하는 글로 여겨 「제일 좋다」처럼 읽는 사람이 그려 볼 수 없는 말을 쓴다','그려 볼 수 있게'),
('K6-1-u2-X45','kor',6,'u2',ARRAY['K6-1-u2-C36','K6-1-u2-C37']::text[],'소개할 것만의 이야기 없이 누구에게나 있는 말(자전거는 바퀴가 두 개인 탈것)로 소개한다','그것만의 이야기'),
('K6-1-u2-X46','kor',6,'u2',ARRAY['K6-1-u2-C38']::text[],'주어와 서술어의 짝을 어긋나게 쓴다(내 생각은 판단하면 안 된다 · 화면이 어둠으로 채웠다)','주어에 맞는 서술어'),
('K6-1-u2-X47','kor',6,'u2',ARRAY['K6-1-u2-C39']::text[],'스스로 하는 일과 다른 힘에 의해 그리 되는 일의 말을 헷갈린다(내가 창문을 닫혔다 · 바람에 창문이 닫았다)','스스로? 다른 힘?')
